local config = {
  ui_story_5051_50510101_X1_dialog_content = "Aviso, aviso, situação de emergência.",
  ui_story_5051_50510101_X2_dialog_content = "Aviso, aviso, situação de emergência.",
  ui_story_5051_50510101_1_dialog_content = "De novo não.",
  ui_story_5051_50510101_2_dialog_content = "Por que agora, de todos os tempos?!",
  ui_story_5051_50510101_3_dialog_content = "O médico... Ah, aqui.",
  ui_story_5051_50510101_4_dialog_content = "Sua condição está piorando ultimamente.",
  ui_story_5051_50510101_5_dialog_content = "Pelo que sei, talvez já seja...",
  ui_story_5051_50510101_6_dialog_content = "Meu senhor, há algo de errado?",
  ui_story_5051_50510101_7_dialog_content = "Não é nada! Como eu disse antes, não quero ser incomodado!",
  ui_story_5051_50510101_8_dialog_content = "Mas sua carruagem para o banquete do Dia da Família chegou.",
  ui_story_5051_50510101_9_dialog_content = "Eu vou me ver para baixo em um momento!",
  ui_story_5051_50510101_10_dialog_content = "<color=#FFB400>Dia da família</color>? Que farsa.",
  ui_story_5051_50510101_11_dialog_content = "Ele arruinou sua vida e ainda tem a ousadia de dar uma festa e chamá-la de banquete do Dia da Família?",
  ui_story_5051_50510101_12_dialog_content = "Não se preocupe, não vou lutar com ele.",
  ui_story_5051_50510101_13_dialog_content = "Esta pode ser a última chance. devo trazer <color=#FFB400>isto</color> voltar.",
  ui_story_5051_50510101_14_dialog_content = "Você nunca quebrou suas promessas para mim, e nem eu.",
  ui_story_5051_50510101_15_dialog_content = "Desta vez, eu prometo que vou...",
  ui_story_5051_50510101_16_dialog_content = "Eita.",
  ui_story_5051_50510101_17_dialog_content = "Vamos nos atrasar nesse ritmo!",
  ui_story_5051_50510101_18_dialog_content = "Eu até mudei de roupa duas horas antes, então por que ninguém aqui ainda?!",
  ui_story_5051_50510101_19_dialog_content = "Onde diabos está o enviado da Rainha Belém?",
  ui_story_5051_50510101_20_dialog_content = "\"Querido PlayerName, um enviado de Northland logo estará visitando Lumopolis para participar do banquete.\"",
  ui_story_5051_50510101_21_dialog_content = "\"Como você provavelmente também estará presente, peço humildemente que a acompanhe durante sua estada.\"",
  ui_story_5051_50510101_22_dialog_content = "\"Ela estará esperando por você fora de Umbraton na hora predeterminada.\"",
  ui_story_5051_50510101_X22_dialog_content = "Estamos sem tempo. Vamos nos atrasar!",
  ui_story_5051_50510101_X23_dialog_content = "Onde está o mensageiro mencionado na correspondência?",
  ui_story_5051_50510101_23_dialog_content = "A Rainha Belém é outra coisa. Ela até sabia que eu iria assistir ao <color=#FFB400>Schwartz Dia da família</color> banquete hoje.",
  ui_story_5051_50510101_24_dialog_content = "<size=30>Hum...</size>",
  ui_story_5051_50510101_25_dialog_content = "Até eu fiquei chocado ao receber um convite. Nunca estive em um banquete tão formal quanto este.",
  ui_story_5051_50510101_26_dialog_content = "Minha roupa é chique o suficiente para a ocasião? Eles não vão pensar que eu sou estranho, certo?",
  ui_story_5051_50510101_27_dialog_content = "Lady Sheol diz que este é o traje formal mais moderno em Lumopolis no momento. Custou-me uma fortuna só para alugar.",
  ui_story_5051_50510101_28_dialog_content = "E eu não entendo nada de roupas, então paguei sem pensar...",
  ui_story_5051_50510101_29_dialog_content = "Suspiro, se apenas Carleen estivessem por perto, ela saberia o que fazer.",
  ui_story_5051_50510101_30_dialog_content = "Não consegui falar com ela recentemente. Eu me pergunto onde ela poderia ter ido.",
  ui_story_5051_50510101_31_dialog_content = "Hum... Perdoe-me...",
  ui_story_5051_50510101_32_dialog_content = "Ah sim, também tem o presente! Só espero que seja bom o suficiente...",
  ui_story_5051_50510101_33_dialog_content = "E-Com licença...!",
  ui_story_5051_50510101_34_dialog_content = "Bwaaaa!!! BB-Baba Yaga! O que você está fazendo aqui?!",
  ui_story_5051_50510101_35_dialog_content = "Ei!",
  ui_story_5051_50510101_36_dialog_content = "Eu sinto Muito!",
  ui_story_5051_50510101_37_dialog_content = "Espere, você não é Baba Yaga. Você é a outra personalidade dela, <color=#FFB400>Mia</color>! Certo?",
  ui_story_5051_50510101_38_dialog_content = "Sim, sou eu.",
  ui_story_5051_50510101_39_dialog_content = "Embora, para ser preciso, eu seja a personalidade dominante, não ela...",
  ui_story_5051_50510101_40_dialog_content = "Só não sou tão forte quanto Baba Yaga e também não consigo controlar meus próprios poderes, então preciso confiar nela para fazer as coisas.",
  ui_story_5051_50510101_41_dialog_content = "Desculpa se te assustei...",
  ui_story_5051_50510101_42_dialog_content = "Não se preocupe com isso! Então, você precisa de algo?",
  ui_story_5051_50510101_X42_dialog_content = "Uh, então eu ouvi que você está indo para o Schwartz banquete do dia da família, PlayerName.",
  ui_story_5051_50510101_X43_dialog_content = "Você se importa... em me trazer junto?",
  ui_story_5051_50510101_X44_dialog_content = "Trazer você? Claro, mas o que faz você de repente querer ir a um banquete?",
  ui_story_5051_50510101_X45_dialog_content = "Uh, tenho me sentido muito melhor ultimamente com os tratamentos recentes.",
  ui_story_5051_50510101_43_dialog_content = "Bem, recentemente fiz algum tratamento e agora minha condição melhorou muito.",
  ui_story_5051_50510101_44_dialog_content = "Tanto que finalmente me lembrei de algo importante...",
  ui_story_5051_50510101_45_dialog_content = "O que seria?",
  ui_story_5051_50510101_46_dialog_content = "Que eu sou... <color=#FFB400>irmã mais velha de Carleen</color>.",
  ui_story_5051_50510101_47_dialog_content = "A irmã de C-Carleen?!",
  ui_story_5051_50510101_48_dialog_content = "Mas eu pensei que Lumópolis só tinha uma princesa?!",
  ui_story_5051_50510101_49_dialog_content = "Sem falar que vocês dois realmente não... Não, espere, se eu olhar de perto, posso ver uma semelhança.",
  ui_story_5051_50510101_50_dialog_content = "É difícil de acreditar, não é?",
  ui_story_5051_50510101_51_dialog_content = "Ninguém está disposto a acreditar em uma palavra que eu digo. Tio mesmo Istvan apenas fiquei sentado em silêncio quando eu disse a ele.",
  ui_story_5051_50510101_52_dialog_content = "Mas é a verdade. Mesmo agora, fragmentos de memórias continuam piscando em minha mente.",
  ui_story_5051_50510101_53_dialog_content = "Alguns são claros como o dia. Outros foram esquecidos...",
  ui_story_5051_50510101_54_dialog_content = "Minha mãe, minha irmã... meu pai. Minha família.",
  ui_story_5051_50510101_55_dialog_content = "Acho que você mencionou algo antes...",
  ui_story_5051_50510101_56_dialog_content = "Você disse uma vez que seu pai era um senhor da cidade e que sua mãe e sua irmã viviam no palácio.",
  ui_story_5051_50510101_57_dialog_content = "Além disso, você e Baba Yaga sempre prestaram muita atenção Carleen.",
  ui_story_5051_50510101_58_dialog_content = "Mas como você costuma esquecer tudo o que fala, não tinha como saber se você estava falando a verdade ou não...",
  ui_story_5051_50510101_59_dialog_content = "Ainda assim, fico feliz que seu tratamento esteja funcionando e que você esteja se sentindo muito melhor, Mia.",
  ui_story_5051_50510101_60_dialog_content = "Ouvi dizer que Lumopolis estava oferecendo um banquete para Schwartz Dia da família.",
  ui_story_5051_50510101_61_dialog_content = "Pelo que pude perceber, é uma ocasião muito especial e importante.",
  ui_story_5051_50510101_62_dialog_content = "imagino minha irmã Carleen provavelmente estará lá.",
  ui_story_5051_50510101_X62_dialog_content = "Eu gostaria de ir à festa e ver por mim mesmo se essas emoções persistentes são reais.",
  ui_story_5051_50510101_X63_dialog_content = "Ou talvez apenas um vislumbre dela de longe seria o suficiente...",
  ui_story_5051_50510101_63_dialog_content = "Eu quero assistir. Quero vê-la e provar se essas boas lembranças são reais ou não.",
  ui_story_5051_50510101_64_dialog_content = "Mesmo que eu não possa provar nenhuma dessas coisas, desde que eu veja que ela está bem, mesmo de longe, isso será bom o suficiente para mim...",
  ui_story_5051_50510101_65_dialog_content = "PlayerName, você é um dos amigos mais próximos de Carleen, bem como uma figura respeitada em Lumopolis...",
  ui_story_5051_50510101_X65_dialog_content = "Por isso vim te ver...",
  ui_story_5051_50510101_X66_dialog_content = "Eu vejo. Ops, estamos com pouco tempo!",
  ui_story_5051_50510101_X67_dialog_content = "Você tem um vestido adequado? E um presente também...",
  ui_story_5051_50510101_66_dialog_content = "Você acha que poderia me ajudar?",
  ui_story_5051_50510101_67_dialog_content = "É verdade que hoje vou ao banquete, mas não sei se posso levar amigos comigo.",
  ui_story_5051_50510101_68_dialog_content = "Hum... Tem que ser hoje?",
  ui_story_5051_50510101_69_dialog_content = "(Em vez de encontrar o enviado de Northland aqui, acabei encontrando Mia precisando de ajuda.)",
  ui_story_5051_50510101_70_dialog_content = "(Mas tudo bem se eu a trouxer como convidada tão de repente?)",
  ui_story_5051_50510101_71_dialog_content = "(O banquete do Dia da Família parece ser um evento realmente importante. Não traria aleatoriamente alguém que afirma ser um Schwartz seja gentil...)",
  ui_story_5051_50510101_72_dialog_content = "(Além disso, todo o banquete será arruinado se Baba Yaga fizer uma aparição inesperada!)",
  ui_story_5051_50510101_73_dialog_content = "Estou criando problemas para você, não estou?",
  ui_story_5051_50510101_74_dialog_content = "Desculpe. Esqueça que eu disse qualquer coisa.",
  ui_story_5051_50510101_75_dialog_content = "Não tenho o direito de pressioná-lo com minhas próprias exigências egoístas.",
  ui_story_5051_50510101_76_dialog_content = "L-vamos fingir que essa conversa nunca aconteceu.",
  ui_story_5051_50510101_77_dialog_content = "Ah, tanto faz! Vamos, Mia! Você vem comigo ao banquete do Dia da Família!",
  ui_story_5051_50510101_78_dialog_content = "H-Huh? Mas não seria muito problema para você?",
  ui_story_5051_50510101_79_dialog_content = "Esta é a primeira vez que você realmente se abriu comigo.",
  ui_story_5051_50510101_80_dialog_content = "Sempre que há um problema, Baba Yaga costuma ser quem resolve.",
  ui_story_5051_50510101_81_dialog_content = "Como eu poderia recusar você quando você está claramente se esforçando tanto?",
  ui_story_5051_50510101_82_dialog_content = "Então relaxe! eu sou um bom amigo de Carleen, assim como muitas pessoas de Lumopolis.",
  ui_story_5051_50510101_83_dialog_content = "Se não conseguimos fazer nada hoje, pelo menos ainda podemos nos divertir muito no banquete!",
  ui_story_5051_50510101_84_dialog_content = "Além disso, tenho certeza que haverá muitas oportunidades no futuro também!",
  ui_story_5051_50510101_85_dialog_content = "PlayerName... Obrigado!",
  ui_story_5051_50510101_86_dialog_content = "(Ainda tenho muitas perguntas sobre tudo isso.)",
  ui_story_5051_50510101_87_dialog_content = "(Mas Mia parece realmente interessado em falar com Carleen. No mínimo, eu deveria apresentá-los um ao outro.)",
  ui_story_5051_50510101_88_dialog_content = "(Ainda assim, não posso deixar de notar que ela só quer ver Carleen. Por que ela não perguntou sobre o Senhor da Cidade...?)",
  ui_story_5051_50510101_89_dialog_content = "<size=45>Desculpe estou atrasado!</size>",
  ui_story_5051_50510101_90_dialog_content = "Ei!",
  ui_story_5051_50510101_91_dialog_content = "Q-Quem é você?!",
  ui_story_5051_50510101_92_dialog_content = "Meu, oh meu! Umbraton está cheio de todos os tipos de coisas bizarras e interessantes!",
  ui_story_5051_50510101_93_dialog_content = "Embora, para ser justo, fiquei impressionado com quase tudo desde que saí de Northland!",
  ui_story_5051_50510101_94_dialog_content = "Fiquei tão encantado com as vistas ao longo do caminho, e antes que eu percebesse ... eu me perdi! Heehee!",
  ui_story_5051_50510101_95_dialog_content = "Mas tudo bem. Minha linda bola de cristal sempre encontra o caminho!",
  ui_story_5051_50510101_96_dialog_content = "Claro, às vezes pode me levar direto para um penhasco...",
  ui_story_5051_50510101_97_dialog_content = "Mas viajar tem tudo a ver com emoção e emoção! Pelo menos é o que a senhora Jeriah diz!",
  ui_story_5051_50510101_98_dialog_content = "Agora, do que eu estava falando agora? Ah, certo, Umbraton!",
  ui_story_5051_50510101_99_dialog_content = "As ruas de Umbraton parecem uma bagunça complicada, mas seguem seus próprios princípios.",
  ui_story_5051_50510101_X99_dialog_content = "As pessoas aqui que entendem esses princípios sabem exatamente onde colocar suas lojas para a prosperidade.",
  ui_story_5051_50510101_100_dialog_content = "Ah, ouvi isso de viajantes que encontrei no caminho.",
  ui_story_5051_50510101_101_dialog_content = "Eu adoraria aprender mais quando estiver livre... Ei, o que é aquela coisa voadora?!",
  ui_story_5051_50510101_102_dialog_content = "Hum, me perdoe...",
  ui_story_5051_50510101_103_dialog_content = "Quem é você de novo?",
  ui_story_5051_50510101_104_dialog_content = "Opa! Que bobagem, esqueci de me apresentar!",
  ui_story_5051_50510101_105_dialog_content = "Meu nome é <color=#FFB400>Jakine</color>. Eu sou o enviado de Northland!",
  ui_story_5051_50510101_106_dialog_content = "Desculpe por estar um pouco atrasado, mas você sabe o que eles dizem: os maiores heróis estão sempre atrasados!",
  ui_story_5051_50510101_107_dialog_content = "<size=45>... Acho que você excedeu em muito o que se poderia considerar um atraso \"elegante\"!</size>",
  ui_story_5051_50510101_X107_dialog_content = "Bem, você sabe o que eles dizem. O protagonista sempre aparece por último!",
  ui_story_5051_50510101_X108_dialog_content = "Ahem, boa noite, senhores e senhoras!",
  ui_story_5051_50510101_X109_dialog_content = "Esta noite, nos reunimos aqui sob o mesmo teto...",
  ui_story_5051_50510101_X110_dialog_content = "Para o banquete anual.",
  ui_story_5051_50510101_X111_dialog_content = "Aprecie a refeição sumptuosa.",
  ui_story_5051_50510101_X112_dialog_content = "Mas mesmo que as porções acabem saciando.",
  ui_story_5051_50510101_X113_dialog_content = "E as libações acabarão.",
  ui_story_5051_50510101_X114_dialog_content = "Ainda podemos nos misturar e festejar.",
  ui_story_5051_50510101_X115_dialog_content = "Enquanto desfruta do delicioso entretenimento.",
  ui_story_5051_50510101_108_dialog_content = "Saudações, estimados convidados.",
  ui_story_5051_50510101_109_dialog_content = "Nós somos os Keating Coro,",
  ui_story_5051_50510101_110_dialog_content = "e agora vamos cantar uma canção.",
  ui_story_5051_50510101_111_dialog_content = "Nós a chamamos de \"Ode a Lumopolis\".",
  ui_story_5051_50510101_112_dialog_content = "Esperamos que você goste!",
  ui_story_5051_50510101_113_dialog_content = "O sol e as estrelas sobem no céu! ♪",
  ui_story_5051_50510101_114_dialog_content = "Brilhando sua luz em um trono tão alto! ♪",
  ui_story_5051_50510101_115_dialog_content = "Nosso escudo inabalável! ♪",
  ui_story_5051_50510101_116_dialog_content = "Nossa lança imparável! ♪",
  ui_story_5051_50510101_117_dialog_content = "Glória e nobreza, um testemunho de fé! ♪",
  ui_story_5051_50510101_118_dialog_content = "Esplendor retumbante, para afastar a escuridão! ♪",
  ui_story_5051_50510101_119_dialog_content = "Um castelo no alto que sempre permanecerá! ♪",
  ui_story_5051_50510101_120_dialog_content = "Uma fonte de doces lembranças! ♪",
  ui_story_5051_50510101_121_dialog_content = "O objeto de nosso louvor! ♪",
  ui_story_5051_50510101_122_dialog_content = "Seu brilho derrota a escuridão, ♪",
  ui_story_5051_50510101_123_dialog_content = "E nos traz dias infindáveis e alegres! ♪",
  ui_story_5051_50510101_124_dialog_content = "Noite Branca nas alturas! Obrigado a todos.",
  ui_story_5051_50510101_125_dialog_content = "Nossa que legal, que música linda!",
  ui_story_5051_50510101_X125_dialog_content = "Essas crianças têm um talento especial para as artes!",
  ui_story_5051_50510101_126_dialog_content = "Eles realmente sabem como limpar e fazer um bom show, hein?",
  ui_story_5051_50510101_127_dialog_content = "Naturalmente. Caso contrário, quem os convidaria para uma ocasião tão importante como esta?",
  ui_story_5051_50510101_128_dialog_content = "Se ao menos eles pudessem ser tão bem-comportados o tempo todo...",
  ui_story_5051_50510101_129_dialog_content = "...",
  ui_story_5051_50510101_130_dialog_content = "Hum? Ooh, eu acho Michael concorda!",
  ui_story_5051_50510101_131_dialog_content = "\"Esplendor retumbante, para afastar a escuridão. Um castelo no alto que sempre permanecerá.\"",
  ui_story_5051_50510101_132_dialog_content = "— A Crise de Darkover.",
  ui_story_5051_50510101_133_dialog_content = "Essa catástrofe de pesadelo é apenas uma parte de nossa história agora.",
  ui_story_5051_50510101_134_dialog_content = "A Crise de Darkover... Pai... Mãe...",
  ui_story_5051_50510101_135_dialog_content = "Ah! Pare com isso, pare com isso, pare com isso! Este é para ser um banquete feliz, então chega de pensamentos sombrios!",
  ui_story_5051_50510101_136_dialog_content = "...",
  ui_story_5051_50510101_137_dialog_content = "Ver? Até Michael está concordando com a cabeça!",
  ui_story_5051_50510101_138_dialog_content = "Me perdoe, Uriel. Falei mal agora há pouco.",
  ui_story_5051_50510101_139_dialog_content = "Está tudo bem, estou acostumada com esse tipo de dor. Não estou acostumada a banquetes.",
  ui_story_5051_50510101_140_dialog_content = "S-Sim, sem brincadeira! Está tão abafado aqui com toda essa gente!",
  ui_story_5051_50510101_141_dialog_content = "Vamos, vamos tomar um sorvete!",
  ui_story_5051_50510101_142_dialog_content = "<size=30>Não fique aí parado, Michael! Me ajude com Uriel!</size>",
  ui_story_5051_50510101_143_dialog_content = "...",
  ui_story_5051_50510101_144_dialog_content = "Nossa, que crianças travessas. Desvio o olhar por um segundo e eles não estão em lugar nenhum.",
  ui_story_5051_50510101_145_dialog_content = "Mas o sofrimento que trouxe ainda é tão indelével e persistente quanto antes.",
  ui_story_5051_50510101_146_dialog_content = "Quem sobreviveu à provação não tem como se livrar dessa dor. Mesmo os poderosos Quatro Anjos não são exceção.",
  ui_story_5051_50510101_147_dialog_content = "Venha agora, Irridon! Por que você não se anima um pouco?",
  ui_story_5051_50510101_148_dialog_content = "O banquete desta noite não será longo.",
  ui_story_5051_50510101_149_dialog_content = "Continue se lamentando assim e você vai perder o resto!",
  ui_story_5051_50510101_150_dialog_content = "Schwartz O Dia da Família foi originalmente uma comemoração das muitas conquistas do Schwartz família.",
  ui_story_5051_50510101_151_dialog_content = "Neste dia <color=#FFB400>doze anos atrás</color>, o atual senhor da cidade superou uma série de situações perigosas, acabando por provar a Schwartz o poder da família para toda Lumopolis.",
  ui_story_5051_50510101_152_dialog_content = "Mas desde a Crise de Darkover, o banquete de celebração foi reduzido em tamanho e grandeza.",
  ui_story_5051_50510101_153_dialog_content = "Ainda me lembro de uma época em que bandas marciais e carros alegóricos eram a norma para este feriado.",
  ui_story_5051_50510101_154_dialog_content = "É assim mesmo? Eu não me lembro de tudo isso claramente.",
  ui_story_5051_50510101_155_dialog_content = "Mas eu me lembro que as pessoas reclamam Schwartz Dia da Família todos os anos.",
  ui_story_5051_50510101_156_dialog_content = "Quais foram as palavras deles de novo... Oh, certo.",
  ui_story_5051_50510101_157_dialog_content = "\"Uma ocasião como esta exige uma celebração adequada, que transmita a lealdade e o respeito dos jovens talentos de Lumopolis ao seu senhor da cidade\", ou algo assim!",
  ui_story_5051_50510101_158_dialog_content = "É por isso que uma versão menos ostensiva do banquete acabou sendo preservada.",
  ui_story_5051_50510101_159_dialog_content = "Concordo plenamente com a decisão do City Lord de manter as coisas simples. Em termos de custos trabalhistas e monetários, essa é uma escolha muito mais razoável.",
  ui_story_5051_50510101_160_dialog_content = "Mas uma celebração dá a muitas pessoas que trabalham duro a chance de descansar um pouco.",
  ui_story_5051_50510101_161_dialog_content = "E para ficar por dentro das últimas fofocas!",
  ui_story_5051_50510101_162_dialog_content = "Não é necessário.",
  ui_story_5051_50510101_163_dialog_content = "Podemos entrar agora?",
  ui_story_5051_50510101_164_dialog_content = "Claro que estamos!",
  ui_story_5051_50510101_165_dialog_content = "A propósito, por que não entramos enquanto o coral cantava?",
  ui_story_5051_50510101_166_dialog_content = "Todo mundo estava curtindo silenciosamente a performance do coral, então eu não queria distrair ninguém me intrometendo. Teria sido rude.",
  ui_story_5051_50510101_167_dialog_content = "Huh? Isso é uma coisa?",
  ui_story_5051_50510101_168_dialog_content = "Bem... sim... interromper uma performance é bastante rude.",
  ui_story_5051_50510101_169_dialog_content = "Mia, se você estivesse usando essa roupa quando me disse que era a irmã mais velha de Carleen...",
  ui_story_5051_50510101_170_dialog_content = "Eu totalmente teria acreditado em você em um instante.",
  ui_story_5051_50510101_171_dialog_content = "Você parece exatamente como uma princesa Lumopolis agora!",
  ui_story_5051_50510101_172_dialog_content = "Th-Este é apenas um vestido normal. Só estou me arrumando para ficar bem no banquete...",
  ui_story_5051_50510101_173_dialog_content = "Já são três vezes! Você disse exatamente a mesma coisa três vezes no caminho até aqui!",
  ui_story_5051_50510101_174_dialog_content = "Você pararia de cobiçá-la como um idiota?",
  ui_story_5051_50510101_175_dialog_content = "Eu não estava cobiçando! Estou tão maravilhado, só isso!",
  ui_story_5051_50510101_176_dialog_content = "Eu não compro! Além disso, você não prometeu àquela outra garota que a levaria ao banquete? A do vestido roxo?",
  ui_story_5051_50510101_177_dialog_content = "Como você pode trocá-la por outra garota tão facilmente?!",
  ui_story_5051_50510101_178_dialog_content = "O que você está falando? A garota de vestido roxo no Colossus era Mia! Ela está apenas usando um vestido branco agora!",
  ui_story_5051_50510101_179_dialog_content = "Você está brincando comigo? Eu não poderia nem dizer! Que tipo de Luminatics mágico ela usou?!",
  ui_story_5051_50510101_180_dialog_content = "Huh?! P-Por que você está chegando tão perto, de repente...?",
  ui_story_5051_50510101_181_dialog_content = "Você esteve conosco o tempo todo! Como você pode deixar de notar?!",
  ui_story_5051_50510101_182_dialog_content = "Heehee, acho que estava muito distraído com as vistas de Lumopolis!",
  ui_story_5051_50510101_183_dialog_content = "Não deveríamos entrar agora, vocês dois...?",
  ui_story_5051_50510101_184_dialog_content = "Y-Sim, você está certo.",
  ui_story_5051_50510101_185_dialog_content = "Devemos verificar nossos dons, apenas para estarmos seguros. Todos nos lembramos de trazer um, certo?",
  ui_story_5051_50510101_186_dialog_content = "Mas é claro! Como enviado da Rainha, trouxe um presente inesquecível!",
  ui_story_5051_50510101_187_dialog_content = "Eu trouxe um também, mas...",
  ui_story_5051_50510101_188_dialog_content = "(Um pote de mel de dente-de-leão pode ser muito pobre para esse tipo de evento...)",
  ui_story_5051_50510101_189_dialog_content = "(É o melhor lote do ano, mas não parece caber nesta mansão.)",
  ui_story_5051_50510101_190_dialog_content = "Esse pote de mel parece incrível. Aposto que ficaria ótimo com uma xícara de chá.",
  ui_story_5051_50510101_191_dialog_content = "Quem sabe? Pode até iniciar uma nova tendência entre os nobres!",
  ui_story_5051_50510101_192_dialog_content = "(Mia viu através de mim! Ela já está até tentando me consolar!)",
  ui_story_5051_50510101_193_dialog_content = "Só espero que o Senhor da Cidade goste. De qualquer forma, estou pronto sempre que vocês estiverem! Vamos!",
  ui_story_5051_50510101_194_dialog_content = "A todos os nossos respeitados convidados, bem-vindos ao evento deste ano Schwartz Dia da família.",
  ui_story_5051_50510101_195_dialog_content = "Por favor, prepare seus convites e assine aqui.",
  ui_story_5051_50510101_196_dialog_content = "Convite, convite... tenho o meu aqui mesmo! Agora é só assinar meu nome!",
  ui_story_5051_50510101_197_dialog_content = "Enviado de Northland? Sim, você parece estar na lista.",
  ui_story_5051_50510101_198_dialog_content = "Para a segurança das pessoas ao seu redor, peço que mantenha seu animal de estimação sob supervisão. Aproveite o banquete.",
  ui_story_5051_50510101_199_dialog_content = "Não é um problema! Sussurro é perfeitamente bem-comportado, não é?",
  ui_story_5051_50510101_200_dialog_content = "Sibilo!",
  ui_story_5051_50510101_X200_dialog_content = "Por favor, aproveite as festividades desta noite.",
  ui_story_5051_50510101_X201_dialog_content = "Claro. Obrigado!",
  ui_story_5051_50510101_201_dialog_content = "Fica o meu convite.",
  ui_story_5051_50510101_202_dialog_content = "PlayerName de Eravel. Estamos honrados em tê-lo aqui hoje.",
  ui_story_5051_50510101_203_dialog_content = "Obrigado por reservar uma noite do seu tempo para se juntar a nós para Schwartz Dia da família. Por favor, divirta-se esta noite.",
  ui_story_5051_50510101_204_dialog_content = "Nossos servos estão à sua disposição, caso precise de alguma coisa. Teremos todo o prazer em oferecer-lhe apenas o nosso melhor serviço.",
  ui_story_5051_50510101_205_dialog_content = "Ei, o que dá? Por que eles estão tratando você como realeza? Eu pensei que era o enviado de Northland!",
  ui_story_5051_50510101_206_dialog_content = "E eu sou o último celestita!",
  ui_story_5051_50510101_207_dialog_content = "(Não fazia ideia de que era tão respeitado por aqui!)",
  ui_story_5051_50510101_208_dialog_content = "Perdoe-me, senhorita, mas quem seria você? Você tem um convite?",
  ui_story_5051_50510101_209_dialog_content = "!",
  ui_story_5051_50510101_210_dialog_content = "(Mia está confortável o suficiente com Jakine e eu para falar conosco, mas ela ainda é muito tímida para falar com estranhos.)",
  ui_story_5051_50510101_211_dialog_content = "(Ela está agindo de forma estranha desde que chegamos, como se estivesse com medo das pessoas reunidas aqui hoje.)",
  ui_story_5051_50510101_212_dialog_content = "Sh-Ela é minha amiga!",
  ui_story_5051_50510101_213_dialog_content = "Eu vejo. Qualquer amigo seu dispensa convite.",
  ui_story_5051_50510101_214_dialog_content = "Entre, por favor.",
  ui_story_5051_50510101_215_dialog_content = "(Ele realmente tinha que dizer isso? Ou é assim que as pessoas falam na classe alta?)",
  ui_story_5051_50510101_216_dialog_content = "Obrigado, PlayerName...",
  ui_story_5051_50510101_217_dialog_content = "Pedaco de bolo! Te peguei.",
  ui_story_5051_50510101_218_dialog_content = "Tch! Todo mundo está tão ocupado bajulando PlayerName que eles se esqueceram de mim!",
  ui_story_5051_50510101_219_dialog_content = "Perdoe-me, mas você é a senhorita Jakine, o enviado de Northland?",
  ui_story_5051_50510101_220_dialog_content = "Isso mesmo! Eu sou a única, a mais nova mensageira da Rainha do Norte, Jakine!",
  ui_story_5051_50510101_221_dialog_content = "Eu vejo. Portanto, os rumores eram verdadeiros - a nova enviada de Northland tem os mesmos lindos cabelos carmesim de seu predecessor.",
  ui_story_5051_50510101_222_dialog_content = "Espere, você conheceu <color=#FFB400>boaz</color> antes? Essa é a minha mãe, você sabe!",
  ui_story_5051_50510101_223_dialog_content = "Excelente...",
  ui_story_5051_50510101_224_dialog_content = "Permita-me apresentar-me. Sou Caleb, um nobre de Lumópolis. Assim como você, estou aqui a convite de Lord Schwartz.",
  ui_story_5051_50510101_225_dialog_content = "Eu estava indo vê-lo. Você se importaria de me acompanhar?",
  ui_story_5051_50510101_226_dialog_content = "Bom...",
  ui_story_5051_50510101_227_dialog_content = "Podemos falar sobre sua mãe no caminho, se você quiser?",
  ui_story_5051_50510101_228_dialog_content = "R-Sério? Isso é ótimo!",
  ui_story_5051_50510101_X225_dialog_content = "Você tem a honra? Importa-se de colocar isso em linguagem simples?",
  ui_story_5051_50510101_X226_dialog_content = "Hahaha... Simplificando, o City Lord me enviou especificamente para você.",
  ui_story_5051_50510101_X227_dialog_content = "Ele mandou pessoas virem me escoltar?!",
  ui_story_5051_50510101_X228_dialog_content = "Eu sabia! Como poderia um enviado do Norte não ter influência?",
  ui_story_5051_50510101_X229_dialog_content = "Espere, deixe-me dizer aos meus amigos que vieram comigo!",
  ui_story_5051_50510101_229_dialog_content = "Heehee! Confira, PlayerName! Este simpático nobre está me levando para ver o Lorde da Cidade! Tchau tchau!",
  ui_story_5051_50510101_230_dialog_content = "Espere, onde você está - e ela se foi, assim.",
  ui_story_5051_50510101_231_dialog_content = "Ela realmente é outra coisa. Como ela pode fugir com um estranho assim, quando a Rainha Bethlehem especificamente me pediu para acompanhá-la?",
  ui_story_5051_50510101_X231_dialog_content = "(Bem, só vim aqui porque não queria recusar o convite.)",
  ui_story_5051_50510101_X232_dialog_content = "(Mas desde Mia está contando comigo para estender a mão para sua família, não posso decepcioná-la.)",
  ui_story_5051_50510101_X233_dialog_content = "Você tá bem, Mia?",
  ui_story_5051_50510101_232_dialog_content = "eu, eh...",
  ui_story_5051_50510101_233_dialog_content = "(Oh não, este lugar está cheio de nobres de Lumopolis. Parece que Mia já está no limite.)",
  ui_story_5051_50510101_234_dialog_content = "Que tal encontrarmos um lugar tranquilo por enquanto?",
  ui_story_5051_50510101_235_dialog_content = "Mas ainda tenho que ver Carleen...",
  ui_story_5051_50510101_236_dialog_content = "Não se preocupe! Por enquanto, apenas fique aqui e descanse. Eu prometo que vou trazê-la para vê-lo em breve!",
  ui_story_5051_50510101_237_dialog_content = "PlayerName...",
  ui_story_5051_50510101_238_dialog_content = "Há uma sala de recepção à esquerda...",
  ui_story_5051_50510101_239_dialog_content = "Para a esquerda! Entendi!",
  ui_story_5051_50510101_240_dialog_content = "A porta se abre para o outro lado. Não adianta puxar...",
  ui_story_5051_50510101_241_dialog_content = "Oh, certo! E lá vamos nós!",
  ui_story_5051_50510101_X238_dialog_content = "Existem três portas. A porta da sala de recepção tem dois vasos brancos ao lado...",
  ui_story_5051_50510101_X239_dialog_content = "Quando Carleen era jovem, ela inadvertidamente arranhou o batente da porta...",
  ui_story_5051_50510101_X240_dialog_content = "Vire à esquerda na porta... Você está certo, há três portas aqui.",
  ui_story_5051_50510101_X241_dialog_content = "Aquele com dois vasos brancos é... a porta mais à esquerda.",
  ui_story_5051_50510101_X242_dialog_content = "Sim, é a sala de recepção com certeza!",
  ui_story_5051_50510101_X243_dialog_content = "(Há um arranhão bastante imperceptível na parte interna da porta, assim como Mia disse.)",
  ui_story_5051_50510101_242_dialog_content = "(Mia parece terrivelmente familiarizado com este lugar. É como se ela já tivesse estado aqui antes.)",
  ui_story_5051_50510101_243_dialog_content = "(Ela poderia realmente ser uma princesa de Lumopolis...?)",
  ui_story_5051_50510201_1_dialog_content = "A interpretação do coro de Ode to Lumopolis está agora concluída.",
  ui_story_5051_50510201_2_dialog_content = "O restante das apresentações desta noite são principalmente canções e danças apresentadas por talentosos jovens nobres.",
  ui_story_5051_50510201_3_dialog_content = "Muitos de nossos ilustres convidados esperam que você apareça e se divirta.",
  ui_story_5051_50510201_4_dialog_content = "Alguns deles também gostariam de fazer mudanças no programa desta noite.",
  ui_story_5051_50510201_5_dialog_content = "\"O solo de instrumento do meu filho deveria ser o final\", \"A dança da minha filha precisa ser adiada até encontrarmos um fundo adequado para ela\" e assim por diante.",
  ui_story_5051_50510201_6_dialog_content = "Já atendi esses pedidos de maneira... adequada. Você se importaria de dar uma olhada?",
  ui_story_5051_50510201_7_dialog_content = "Está tudo bem, eu confio em você.",
  ui_story_5051_50510201_8_dialog_content = "Obrigado por cuidar do planejamento e segurança do banquete na ausência de Carleen.",
  ui_story_5051_50510201_9_dialog_content = "Supõe-se que seja dever de Carleen organizar o Dia da Família.",
  ui_story_5051_50510201_10_dialog_content = "Mas todos esses anos, ela sempre escolheu ignorá-lo.",
  ui_story_5051_50510201_11_dialog_content = "Para mim, hoje é o dia em que mamãe faleceu.",
  ui_story_5051_50510201_12_dialog_content = "Não pude estar com ela em seus momentos finais, então não vou ficar na cidade agora.",
  ui_story_5051_50510201_13_dialog_content = "Ela diz a mesma coisa todos os anos e depois desaparece de Lumopolis.",
  ui_story_5051_50510201_14_dialog_content = "Embora ela não tenha ficado com ela por muito tempo, a perda de sua mãe ainda a machuca até hoje.",
  ui_story_5051_50510201_15_dialog_content = "Você acredita que Lady Carleen falta maturidade?",
  ui_story_5051_50510201_16_dialog_content = "Pelo contrário, tudo isso está enraizado em erros tolos que cometi na juventude.",
  ui_story_5051_50510201_17_dialog_content = "Estou apenas colhendo o que plantei.",
  ui_story_5051_50510201_18_dialog_content = "Você coloca muita culpa em si mesmo.",
  ui_story_5051_50510201_19_dialog_content = "Somos apenas mortais, meu senhor. Tudo o que podemos fazer é nos esforçar para alcançar a grandeza com a pequena quantidade de tempo que nos é dada.",
  ui_story_5051_50510201_20_dialog_content = "Você só precisa olhar para o estado atual de Lumopolis para ver o que você conseguiu.",
  ui_story_5051_50510201_21_dialog_content = "Sem você, mesmo os melhores guias não teriam como apresentar a glória de Lumopolis aos seus muitos visitantes.",
  ui_story_5051_50510201_22_dialog_content = "Eu mesmo não poderia ter dito melhor, Ms. Blanc!",
  ui_story_5051_50510201_23_dialog_content = "Ou, a julgar pelo seu traje, devo chamá-la de venerável Sra. Rot?",
  ui_story_5051_50510201_24_dialog_content = "Olá, Duque Otto. O banquete de hoje é uma celebração do Senhor Schwartz e suas muitas conquistas.",
  ui_story_5051_50510201_25_dialog_content = "Meu papel é pequeno e não merece nenhum elogio. Você pode se dirigir a mim como quiser.",
  ui_story_5051_50510201_26_dialog_content = "Pequeno, você diz? Hahaha! Você tem muito senso de humor, Sra. Rot da Nightwatch.",
  ui_story_5051_50510201_27_dialog_content = "Perdoe-me por estar atrasado, meu senhor. Eu rezo para não interromper suas reminiscências?",
  ui_story_5051_50510201_28_dialog_content = "Não há necessidade de observar as formalidades habituais esta noite. Você só precisa aproveitar o banquete.",
  ui_story_5051_50510201_29_dialog_content = "Mas isso não serve de jeito nenhum, meu senhor. Afinal, esta noite comemora suas grandes contribuições para nossa feira Lumopolis.",
  ui_story_5051_50510201_30_dialog_content = "Uma pena que as pessoas mais próximas a você não vejam dessa forma.",
  ui_story_5051_50510201_31_dialog_content = "Isso deve ser o que significa estar \"solitário no topo da montanha\".",
  ui_story_5051_50510201_32_dialog_content = "Mas você também deve conhecer o sentimento, Otto.",
  ui_story_5051_50510201_33_dialog_content = "Afinal, você se sacrificou tanto ao longo dos anos pelo bem da família Troy e do Conselho Ancião.",
  ui_story_5051_50510201_34_dialog_content = "Você me lisonjeia, meu senhor. Minhas conquistas não são nada comparadas às suas.",
  ui_story_5051_50510201_35_dialog_content = "Meu filho fará um discurso após o término da apresentação atual. Ele ficaria honrado se você estivesse lá para ouvi-lo.",
  ui_story_5051_50510201_36_dialog_content = "Infelizmente, um convidado de honra solicitou uma audiência comigo.",
  ui_story_5051_50510201_37_dialog_content = "No entanto, tenho certeza de que o pequeno show de talentos de seu filho não deixará de ser apreciado pelos convidados desta noite.",
  ui_story_5051_50510201_38_dialog_content = "Por enquanto, minha presença é necessária em outro lugar.",
  ui_story_5051_50510201_39_dialog_content = "Meu senhor, um servo está aqui com o hóspede que pediu para vê-lo.",
  ui_story_5051_50510201_40_dialog_content = "Nós estávamos conversando sobre isso também. Por favor, aproveite o banquete, Otto.",
  ui_story_5051_50510201_41_dialog_content = "Muito bem, meu senhor.",
  ui_story_5051_50510201_42_dialog_content = "... É por isso que sempre digo que os dragões são uma raça tão mágica!",
  ui_story_5051_50510201_43_dialog_content = "Eles cabem na palma da sua mão quando são jovens, mas depois crescem e ficam do tamanho de um Colosso!",
  ui_story_5051_50510201_44_dialog_content = "Agora que penso nisso, dragões e colossos são meio parecidos. Eles poderiam estar relacionados de alguma forma?",
  ui_story_5051_50510201_45_dialog_content = "Aham, senhorita Jakine?",
  ui_story_5051_50510201_46_dialog_content = "Sim, o que é?",
  ui_story_5051_50510201_47_dialog_content = "Disseram-me que sua predecessora, Lady Boaz, era uma mestra em adivinhação.",
  ui_story_5051_50510201_48_dialog_content = "Sempre fui cativado pelas artes de adivinhação de Northland. Por acaso você tem algum conhecimento sobre o assunto?",
  ui_story_5051_50510201_49_dialog_content = "Claro que eu faço! Na verdade, sou mestre em...",
  ui_story_5051_50510201_50_dialog_content = "*Ahem* S-sim, eu me interesso um pouco pela adivinhação.",
  ui_story_5051_50510201_51_dialog_content = "Rainha Bethlehem me enviou aqui especificamente para reabastecer o <color=#FFB400>Cristal da Memória Eterna</color> com água do Lago Espelho.",
  ui_story_5051_50510201_52_dialog_content = "Acho que já ouvi falar desse objeto antes.",
  ui_story_5051_50510201_53_dialog_content = "Mas por que esse Cristal da Memória Eterna requer água do Lago Espelho?",
  ui_story_5051_50510201_54_dialog_content = "Tive a impressão de que era apenas um recipiente para armazenar Lumina...",
  ui_story_5051_50510201_55_dialog_content = "Saudações, senhorita Jakine. Finalmente encontrei você.",
  ui_story_5051_50510201_56_dialog_content = "Olá!",
  ui_story_5051_50510201_57_dialog_content = "<size=30>Psiu! Quem é essa senhora, Sr. Caleb?</size>",
  ui_story_5051_50510201_58_dialog_content = "Já faz muito tempo, Ms. Blanc.",
  ui_story_5051_50510201_59_dialog_content = "Já faz um bom tempo, sim. Acredito que esta é a primeira vez que vejo você no banquete do Dia da Família. Obrigado por nos agraciar com sua presença.",
  ui_story_5051_50510201_60_dialog_content = "Isso é Ms. Blanc. Pense nela como uma assistente pessoal do próprio City Lord.",
  ui_story_5051_50510201_61_dialog_content = "Certo...",
  ui_story_5051_50510201_62_dialog_content = "Perder Jakine, Senhor Schwartz está esperando por você na sala de recepção. Esse caminho por favor.",
  ui_story_5051_50510201_63_dialog_content = "H-Como vai você! Eu sou Jakine, enviado da Rainha Belém!",
  ui_story_5051_50510201_64_dialog_content = "Já se passaram mais de doze anos desde que um emissário do norte veio visitar Lumopolis!",
  ui_story_5051_50510201_65_dialog_content = "Por ordem de Sua Majestade, vim reabastecer o Cristal da Memória Eterna com <color=#FFB400>água do lago espelho</color>.",
  ui_story_5051_50510201_66_dialog_content = "Obrigado por vir aqui hoje, enviado de Northland.",
  ui_story_5051_50510201_67_dialog_content = "Sua Majestade já me informou dos detalhes. Em nome da Lumopolis, agradeço por ter viajado tão longe para cumprir sua missão.",
  ui_story_5051_50510201_68_dialog_content = "Tudo em um dia de trabalho! Afinal, é minha responsabilidade!",
  ui_story_5051_50510201_69_dialog_content = "Sra. Rot, você poderia nos trazer o Cristal da Memória Eterna?",
  ui_story_5051_50510201_70_dialog_content = "Como desejar.",
  ui_story_5051_50510201_71_dialog_content = "...",
  ui_story_5051_50510201_72_dialog_content = "Pelo que me lembro, pedi especificamente à Sra. Rot para receber o enviado de Northland hoje.",
  ui_story_5051_50510201_73_dialog_content = "Talvez você tenha feito amizade com o enviado durante o banquete, Caleb?",
  ui_story_5051_50510201_74_dialog_content = "Perdoe-me, meu senhor.",
  ui_story_5051_50510201_75_dialog_content = "Como membro da família Magnus, simplesmente pensei que tinha um dever a cumprir. Afinal, isso envolve um <color=#FFB400>relíquia da minha irmã</color>.",
  ui_story_5051_50510201_76_dialog_content = "Eu não tinha ideia de que você se oporia à minha presença assim.",
  ui_story_5051_50510201_77_dialog_content = "(Uma relíquia da irmã dele? A família Magnus? Do que esses caras estão falando?! E por que a atmosfera parece tão estranha de repente?!)",
  ui_story_5051_50510201_78_dialog_content = "(Estraguei tudo, PlayerName, Mia...)",
  ui_story_5051_50510201_X78_dialog_content = "(Eu não deveria ter ido sozinho para completar esta missão... Alguém venha me salvar!)",
  ui_story_5051_50510201_79_dialog_content = "Meu senhor, convidei o Sr. Caleb aqui hoje.",
  ui_story_5051_50510201_80_dialog_content = "Ele desejava buscar sua audiência sobre um determinado assunto. Como você estará bastante ocupado esta noite, achei melhor deixá-lo vir aqui e falar o que pensa.",
  ui_story_5051_50510201_81_dialog_content = "Como membro de sua família, ele merece ser priorizado, imagino.",
  ui_story_5051_50510201_82_dialog_content = "Sra. Rot... Às vezes, acho que você é boa demais no seu trabalho.",
  ui_story_5051_50510201_83_dialog_content = "Obrigado pelo seu elogio.",
  ui_story_5051_50510201_84_dialog_content = "Aqui está o Cristal da Memória Eterna. Obrigado mais uma vez por sua ajuda.",
  ui_story_5051_50510201_85_dialog_content = "Tudo bem, deixe comigo!",
  ui_story_5051_50510201_86_dialog_content = "(estou salvo! Oh, obrigado, Ms. Blanc!)",
  ui_story_5051_50510201_87_dialog_content = "Sr. Caleb, este vinho Umbraton nos foi dado por um certo convidado esta noite.",
  ui_story_5051_50510201_88_dialog_content = "Tem um efeito calmante muito especial. Por favor, tome um copo.",
  ui_story_5051_50510201_89_dialog_content = "... Agradeço.",
  ui_story_5051_50510201_90_dialog_content = "Se não me engano, Caleb, seu motivo de vir aqui hoje é o Cristal da Memória Eterna. Estou correcto?",
  ui_story_5051_50510201_91_dialog_content = "este especial <color=#FFB400>dispositivo de gravação</color> foi dado a mim e a Joshua pela Rainha do Norte como um presente.",
  ui_story_5051_50510201_92_dialog_content = "Doze anos atrás, foi minha esposa, sua irmã, quem o ativou por conta própria.",
  ui_story_5051_50510201_93_dialog_content = "Mas tudo o que contém são algumas memórias dispersas daquele ano.",
  ui_story_5051_50510201_94_dialog_content = "Eu simplesmente cuidei dele depois que ela faleceu, mas não tinha intenção de guardá-lo para mim.",
  ui_story_5051_50510201_95_dialog_content = "Se a Rainha o quiser de volta, eu não faria objeções.",
  ui_story_5051_50510201_96_dialog_content = "... As memórias de sua esposa e filhas realmente significam tão pouco para você?",
  ui_story_5051_50510201_97_dialog_content = "H-Sua Majestade nunca disse nada sobre retirá-lo, você sabe!",
  ui_story_5051_50510201_98_dialog_content = "Além disso, o mundo dentro do cristal é alimentado pelo Lumina da pessoa que o ativou. Rainha Bethlehem não teria utilidade para isso!",
  ui_story_5051_50510201_99_dialog_content = "O mundo dentro do cristal?",
  ui_story_5051_50510201_100_dialog_content = "Isso mesmo! O Cristal da Memória Eterna não é um dispositivo de gravação comum!",
  ui_story_5051_50510201_101_dialog_content = "Há um inteiramente <color=#FFB400>mundo real</color> preservado dentro dele!",
  ui_story_5051_50510201_102_dialog_content = "Mas como isso é possível?",
  ui_story_5051_50510201_103_dialog_content = "Acho que você não está familiarizado com isso, Sr. Caleb.",
  ui_story_5051_50510201_104_dialog_content = "Permita-me explicar como funciona!",
  ui_story_5051_50510201_105_dialog_content = "Primeiro, o Cristal da Memória Eterna requer uma quantidade suficiente de água do Lago Espelho para funcionar corretamente.",
  ui_story_5051_50510201_106_dialog_content = "Depois de pronto, o cristal deve ser ativado infundindo-o com o Lumina do usuário.",
  ui_story_5051_50510201_107_dialog_content = "Em seguida, o cristal começará a registrar tudo o que acontece no <color=#FFB400>um único dia</color>, dentro de um determinado raio.",
  ui_story_5051_50510201_108_dialog_content = "Está preservado no Cristal da Memória Eterna, sempre em loop em uma reencenação sem fim.",
  ui_story_5051_50510201_109_dialog_content = "Infundindo-o com Lumina mais uma vez, os usuários podem entrar no mundo do cristal e experimentar a memória por conta própria!",
  ui_story_5051_50510201_110_dialog_content = "E é basicamente assim que funciona o Cristal da Memória Eterna e seu universo de bolso.",
  ui_story_5051_50510201_111_dialog_content = "Mas há um problema! O cristal é extremamente frágil...",
  ui_story_5051_50510201_112_dialog_content = "Uma vez lá dentro, os usuários devem se manter escondidos e evitar interagir com qualquer pessoa ou coisa a todo custo.",
  ui_story_5051_50510201_113_dialog_content = "<size=42>Caso contrário, mesmo a menor das mudanças na história estabelecida pode resultar em uma catástrofe inimaginável!</size>",
  ui_story_5051_50510201_114_dialog_content = "Então é assim que os enigmáticos Luminatics de Northland são...",
  ui_story_5051_50510201_115_dialog_content = "<size=30>Quão terrivelmente complicado.</size>",
  ui_story_5051_50510201_116_dialog_content = "Ufa! Pronto, o cristal já está cheio de água e pronto!",
  ui_story_5051_50510201_117_dialog_content = "Aqui está, Senhor Schwartz.",
  ui_story_5051_50510201_118_dialog_content = "Você pode usá-lo sempre que quiser agora!",
  ui_story_5051_50510201_119_dialog_content = "Você tem minha gratidão, enviado.",
  ui_story_5051_50510201_120_dialog_content = "Mas infelizmente... A pessoa que o ativou não está mais conosco.",
  ui_story_5051_50510201_121_dialog_content = "Antes de ela nos deixar, ninguém estava disposto a revisitar o passado gravado no cristal.",
  ui_story_5051_50510201_122_dialog_content = "E agora que ela se foi, não tenho o direito de chafurdar em meu próprio remorso mais uma vez.",
  ui_story_5051_50510201_123_dialog_content = "Receio que ninguém seja capaz de ativá-lo novamente.",
  ui_story_5051_50510201_124_dialog_content = "Err...",
  ui_story_5051_50510201_125_dialog_content = "T-Tudo bem! Como praticante de adivinhação de Northland, tenho certeza de que posso encontrar outra maneira de usá-lo!",
  ui_story_5051_50510201_126_dialog_content = "Deixe-me ver... O encantamento é mais ou menos assim...",
  ui_story_5051_50510201_127_dialog_content = "...",
  ui_story_5051_50510201_128_dialog_content = "Deixe-me ver, o encantamento é mais ou menos assim...",
  ui_story_5051_50510201_129_dialog_content = "Joshua, não concordamos em aprender a usar o Cristal da Memória Eterna juntos?",
  ui_story_5051_50510201_130_dialog_content = "Eu sei o quanto você adora aprender, mas quando você se apressa em coisas assim, não posso deixar de me sentir um pouco para trás.",
  ui_story_5051_50510201_131_dialog_content = "Oh? Eu não tinha ideia de que poderia fazer você se sentir tão sozinho.",
  ui_story_5051_50510201_132_dialog_content = "Eu pensei que era o único que tinha que sofrer tal emoção.",
  ui_story_5051_50510201_133_dialog_content = "Me perdoe meu amor. Tenho estado tão ocupado com meu trabalho que negligenciei você e as meninas.",
  ui_story_5051_50510201_134_dialog_content = "Hehe. Só estou brincando com você.",
  ui_story_5051_50510201_135_dialog_content = "É somente graças ao seu esforço que temos a paz e a prosperidade necessárias para sentir todos os tipos de emoções.",
  ui_story_5051_50510201_136_dialog_content = "Alegria, emoção, amor... E solidão também.",
  ui_story_5051_50510201_137_dialog_content = "Mas agora, recebi este presente da Rainha do Norte.",
  ui_story_5051_50510201_138_dialog_content = "Se algum dia me sentir sozinho, sempre poderei encontrá-lo dentro deste Cristal de Memória Eterna.",
  ui_story_5051_50510201_139_dialog_content = "Joshua...",
  ui_story_5051_50510201_140_dialog_content = "Então, por favor, deixe-me ativá-lo?",
  ui_story_5051_50510201_141_dialog_content = "Muito bem, minha querida. Desde que te faça feliz.",
  ui_story_5051_50510201_142_dialog_content = "Já decidiu em que dia quer gravar?",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>da Veronica</color> aniversário? Ou talvez a primeira apresentação de Carleen? Ou talvez...",
  ui_story_5051_50510201_144_dialog_content = "É um segredo!",
  ui_story_5051_50510201_145_dialog_content = "Você não vai, por favor, apenas me diga? Prefiro não fazer papel de bobo quando você decidir ativá-lo.",
  ui_story_5051_50510201_146_dialog_content = "Céus, eu não sabia que o Senhor da Cidade de Lumopolis era capaz de fazer papel de bobo!",
  ui_story_5051_50510201_147_dialog_content = "Claro que estou... Lembra quando acidentalmente pisei no brinquedo de Carleen e quebrei?",
  ui_story_5051_50510201_148_dialog_content = "Não achei que ela se importasse muito na época, já que quase não reagiu quando isso aconteceu. Mal sabia eu que ela passou o resto do dia chorando em seu quarto...",
  ui_story_5051_50510201_149_dialog_content = "Ah sim, eu me lembro de você do lado de fora da porta dela com um brinquedo novo, sem ousar entrar. O olhar em seu rosto assustou mais do que alguns de nossos servos.",
  ui_story_5051_50510201_150_dialog_content = "Existem outras instâncias que vêm à mente?",
  ui_story_5051_50510201_151_dialog_content = "... Teve uma vez que deixei na sala de recepção a coroa de rosas que a Verônica me presenteou.",
  ui_story_5051_50510201_152_dialog_content = "Eu estava tão ocupado com uma convidada naquele dia que descuidadamente deixei seu presente na mesa, sem perceber que ela pensou que eu não tinha gostado e o jogou de lado...",
  ui_story_5051_50510201_153_dialog_content = "E então você ordenou aos jardineiros que plantassem um jardim inteiro de rosas só para ela.",
  ui_story_5051_50510201_154_dialog_content = "Infelizmente, a preocupação da nossa filha com a sua formação deixou-a sem tempo nem interesse em tecer coroas de flores nunca mais...",
  ui_story_5051_50510201_155_dialog_content = "(Suspiros)",
  ui_story_5051_50510201_156_dialog_content = "Você não fez papel de bobo naquela época, meu doce Daniel.",
  ui_story_5051_50510201_157_dialog_content = "Este mundo é vasto e complexo, e somos muito limitados nas coisas que podemos ver e fazer.",
  ui_story_5051_50510201_158_dialog_content = "É por isso que acredito que este Cristal da Memória Eterna é uma coisa tão maravilhosa... Ele nos oferece a chance de registrar esses momentos em nossas vidas e apreciá-los enquanto vivermos.",
  ui_story_5051_50510201_159_dialog_content = "As memórias podem ser tão pouco confiáveis, mas com este cristal, nosso verdadeiro eu será preservado por toda a eternidade.",
  ui_story_5051_50510201_160_dialog_content = "Bom, ruim, certo, errado... Chegará o dia em que nossa família se sentirá perdida e confusa.",
  ui_story_5051_50510201_161_dialog_content = "Quando esse dia chegar, este cristal nos mostrará o <color=#FFB400>respostas que precisamos</color>. Estou certo disso.",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50510201_163_dialog_content = "...",
  ui_story_5051_50510201_164_dialog_content = "Você aí, escondido nas sombras. Mostre-se.",
  ui_story_5051_50510201_165_dialog_content = "Eu-Sou eu, PlayerName! Desculpa por interromper! Hahaha...",
  ui_story_5051_50510201_166_dialog_content = "Deixe-me ver se entendi isso corretamente.",
  ui_story_5051_50510201_167_dialog_content = "Você queria presentear o Lorde da Cidade com seu presente, então você invadiu sua sala de recepção sem perguntar.",
  ui_story_5051_50510201_168_dialog_content = "Mas quando Senhor Schwartz e seus convidados entraram na sala, você instintivamente se escondeu em vez de cumprimentar ninguém.",
  ui_story_5051_50510201_169_dialog_content = "Desde então, você tem escutado atrás das cortinas.",
  ui_story_5051_50510201_170_dialog_content = "Isso é correto?",
  ui_story_5051_50510201_171_dialog_content = "Er, sim, isso é correto. Desculpe...",
  ui_story_5051_50510201_172_dialog_content = "(quer dizer, só fiz isso porque a primeira reação de Mia foi se esconder, então apenas segui...)",
  ui_story_5051_50510201_173_dialog_content = "(Provavelmente não deveríamos tê-la trazido aqui tão cedo... Ela não está em condições de conhecer novas pessoas agora.)",
  ui_story_5051_50510201_174_dialog_content = "Agradeço sua honestidade e boas intenções, jovem.",
  ui_story_5051_50510201_175_dialog_content = "Mas não é justo escutar.",
  ui_story_5051_50510201_176_dialog_content = "Não deixe isso acontecer de novo, entendeu?",
  ui_story_5051_50510201_177_dialog_content = "Entendido. Obrigado, senhor...",
  ui_story_5051_50510201_178_dialog_content = "Agora, então, eu tenho mais uma pergunta para você.",
  ui_story_5051_50510201_179_dialog_content = "A outra pessoa que está à espreita nas sombras também é sua amiga?",
  ui_story_5051_50510201_180_dialog_content = "Caso contrário, a Sra. Rot os descartará sem hesitação.",
  ui_story_5051_50510201_X177_dialog_content = "Bem, então, deixe-me fazer outra pergunta.",
  ui_story_5051_50510201_X178_dialog_content = "O rato escondido debaixo da mesa é um amigo seu?",
  ui_story_5051_50510201_X179_dialog_content = "Se não, vou enxotá-lo.",
  ui_story_5051_50510201_181_dialog_content = "Ahahaha! S-Ela é!",
  ui_story_5051_50510201_182_dialog_content = "Venha para fora, Mia. Não tenha medo, todas essas pessoas são boas.",
  ui_story_5051_50510201_183_dialog_content = "E-espere! Meu véu... Não consigo encontrar meu véu!",
  ui_story_5051_50510201_184_dialog_content = "Um nobre de Lumópolis? Mas ela parece...",
  ui_story_5051_50510201_185_dialog_content = "Ai...?",
  ui_story_5051_50510201_186_dialog_content = "...",
  ui_story_5051_50510201_187_dialog_content = "Esta é mais uma de suas surpresas para mim, Sra. Rot?",
  ui_story_5051_50510201_188_dialog_content = "Não importa, apenas limpe minha agenda antes que qualquer outra coisa aconteça.",
  ui_story_5051_50510201_189_dialog_content = "Lamento muito, meu senhor. Vou cancelar o resto dos seus compromissos do dia.",
  ui_story_5051_50510201_190_dialog_content = "Por favor faça.",
  ui_story_5051_50510201_191_dialog_content = "Então se eu usar este... e combiná-lo com este... Bingo!",
  ui_story_5051_50510201_192_dialog_content = "Acho que encontrei o encantamento exato de que precisamos agora!",
  ui_story_5051_50510201_193_dialog_content = "Isso não será necessário. Por favor, retorne ao banquete com PlayerName e divirtam-se.",
  ui_story_5051_50510201_194_dialog_content = "Nós três devemos falar em particular...",
  ui_story_5051_50510201_195_dialog_content = "Aham, Jakine, vamos primeiro—Jakine?",
  ui_story_5051_50510201_196_dialog_content = "Ad praeteritum! Ad praeteritum! Ad praeteritum!",
  ui_story_5051_50510201_197_dialog_content = "Revivamos os tempos dourados do passado!",
  ui_story_5051_50510201_198_dialog_content = "<size=45>Abrahadabra!</size>",
  ui_story_5051_50510201_199_dialog_content = "O que no...?",
  ui_story_5051_50510201_200_dialog_content = "<size=45>O-O que está acontecendo?!</size>",
  ui_story_5051_50510201_201_dialog_content = "Me ajude... PlayerName...",
  ui_story_5051_50510201_202_dialog_content = "Mia! Pegue minha mão!!",
  ui_story_5051_50510201_203_dialog_content = "Tá bom...!",
  ui_story_5051_50510201_204_dialog_content = "Ugh... Hã?",
  ui_story_5051_50510201_205_dialog_content = "Onde estou...?",
  ui_story_5051_50510201_206_dialog_content = "F-Graças a Deus, você finalmente acordou!",
  ui_story_5051_50510201_207_dialog_content = "Mia, Onde estamos?",
  ui_story_5051_50510201_208_dialog_content = "Eu também não sei... Mas precisamos correr! Os Eclipsitos estão chegando!",
  ui_story_5051_50510201_209_dialog_content = "—!!!",
  ui_story_5051_50510201_210_dialog_content = "Eclipses?!",
  ui_story_5051_50510201_211_dialog_content = "Por aqui, Mia! Pressa!",
  ui_story_5051_50510201_212_dialog_content = "M-Mas PlayerName, esse caminho também é—",
  ui_story_5051_50510201_213_dialog_content = "—!!!",
  ui_story_5051_50510201_214_dialog_content = "Estamos cercados!!",
  ui_story_5051_50510201_215_dialog_content = "B-Baba Yaga! Baba Yaga, socorro!!",
  ui_story_5051_50510201_216_dialog_content = "Baba Yaga? Por que você não está dizendo nada...?",
  ui_story_5051_50510201_217_dialog_content = "Droga... Faça o que fizer, Mia, não saia do meu lado!",
  ui_story_5051_50510201_218_dialog_content = "Traga-o, seus eclipsitas imundos!",
  ui_story_5051_50510201_219_dialog_content = "<size=45>Ahhhh!</size>",
  ui_story_5051_50510201_220_dialog_content = "Por favor, não...",
  ui_story_5051_50510201_221_dialog_content = "Não...",
  ui_story_5051_50510201_222_dialog_content = "<size=45>não se atreva a machucar PlayerName!!!</size>",
  ui_story_5051_50510201_223_dialog_content = "Grrr!?",
  ui_story_5051_50510201_224_dialog_content = "M-Mia...?",
  ui_story_5051_50510201_225_dialog_content = "Aff... aff...",
  ui_story_5051_50510201_226_dialog_content = "Eu... Acabei de usar... Luminatics?",
  ui_story_5051_50510201_227_dialog_content = "Eu não tinha ideia de que você poderia usar Luminatics também, Mia!",
  ui_story_5051_50510201_228_dialog_content = "Eu costumava ser capaz de... Mas isso foi há muito tempo. Desde então não consigo mais...",
  ui_story_5051_50510201_229_dialog_content = "—!!!",
  ui_story_5051_50510201_230_dialog_content = "Mais Eclipsites?! Quantos deles existem?",
  ui_story_5051_50510201_231_dialog_content = "Você ainda pode lutar?",
  ui_story_5051_50510201_232_dialog_content = "Eu não sei...",
  ui_story_5051_50510201_233_dialog_content = "Mas se eu não lutar, você estará em perigo.",
  ui_story_5051_50510201_234_dialog_content = "Eu tenho que proteger você!",
  ui_story_5051_50510201_235_dialog_content = "Você consegue, Mia!",
  ui_story_5051_50510201_236_dialog_content = "Contanto que você seja capaz de usar Luminatics, posso aumentar seu poder!",
  ui_story_5051_50510201_237_dialog_content = "Confie em mim e confie em si mesmo!",
  ui_story_5051_50510201_238_dialog_content = "Confiar em você... E em mim?",
  ui_story_5051_50510201_239_dialog_content = "Tudo bem! Eu farei o meu melhor!",
  ui_story_5051_50510301_1_dialog_content = "Vocês estão bem?",
  ui_story_5051_50510301_2_dialog_content = "Estou bem. Mesmo que eu ainda me sinta abalado...",
  ui_story_5051_50510301_3_dialog_content = "Acho que estou um pouco mais confiante agora!",
  ui_story_5051_50510301_4_dialog_content = "Você não se machucou em toda a luta, não é?",
  ui_story_5051_50510301_5_dialog_content = "De jeito nenhum, então não se preocupe comigo!",
  ui_story_5051_50510301_6_dialog_content = "Eu tenho que dizer, Mia, isso foi impressionante! Muitas pessoas não podem lutar contra tantos Eclipsites por conta própria.",
  ui_story_5051_50510301_7_dialog_content = "R-Sério? Mas foi tudo graças a você, eu acho.",
  ui_story_5051_50510301_8_dialog_content = "O poder do Último Caelestita é realmente algo...",
  ui_story_5051_50510301_9_dialog_content = "Falando nisso, não consigo sentir ninguém ao nosso redor desde que acordei.",
  ui_story_5051_50510301_10_dialog_content = "Onde diabos estamos? E para onde foram todos os outros?",
  ui_story_5051_50510301_11_dialog_content = "Olhe ali, ao longe! Isso é <color=#FFB400>Lumópolis</color>!",
  ui_story_5051_50510301_12_dialog_content = "Isso significa que estamos no <color=#FFB400>arredores de Lumópolis</color>?",
  ui_story_5051_50510301_13_dialog_content = "Como viemos parar aqui...?",
  ui_story_5051_50510301_14_dialog_content = "Poderia ser este o mundo dentro do <color=#FFB400>Cristal da Memória Eterna</color>?",
  ui_story_5051_50510301_15_dialog_content = "Eu acho que você provavelmente está certo!",
  ui_story_5051_50510301_16_dialog_content = "Ad praeteritum! Ad praeteritum! Ad praeteritum!",
  ui_story_5051_50510301_17_dialog_content = "Revivamos os tempos dourados do passado!",
  ui_story_5051_50510301_18_dialog_content = "Abrahadabra!",
  ui_story_5051_50510301_19_dialog_content = "Eu me lembro agora... eu acho Jakine realmente é um mestre de adivinhação, afinal.",
  ui_story_5051_50510301_20_dialog_content = "Mas mesmo assim, parece que ela se adiantou demais dessa vez.",
  ui_story_5051_50510301_21_dialog_content = "Sim...",
  ui_story_5051_50510301_22_dialog_content = "Lembro-me dela mencionando outra coisa também.",
  ui_story_5051_50510301_23_dialog_content = "\"Uma vez lá dentro, os usuários devem se manter escondidos e evitar interagir com qualquer um ou qualquer coisa a todo custo.\"",
  ui_story_5051_50510301_24_dialog_content = "\"Caso contrário, mesmo as menores mudanças na história estabelecida podem resultar em uma catástrofe inimaginável!\"",
  ui_story_5051_50510301_25_dialog_content = "Oh não... Acabamos de brigar com um bando de Eclipsites!",
  ui_story_5051_50510301_26_dialog_content = "Vamos ficar bem...?",
  ui_story_5051_50510301_27_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5051_50510301_28_dialog_content = "S-Alguém está com problemas!",
  ui_story_5051_50510301_29_dialog_content = "Quem é aquele...?",
  ui_story_5051_50510301_30_dialog_content = "Capitão! Existem muitos Eclipsites, não podemos aguentar muito mais tempo...",
  ui_story_5051_50510301_31_dialog_content = "Foco, homens! Mesmo que seus companheiros soldados caiam diante de seus olhos, não se atreva a largar suas armas!",
  ui_story_5051_50510301_32_dialog_content = "Porra tudo!!!",
  ui_story_5051_50510301_33_dialog_content = "Um veículo de carga defendido por soldados de Lumopolis... E eles estão sendo atacados por Eclipsites!",
  ui_story_5051_50510301_34_dialog_content = "Mas por que existem tantos Eclipsites fora de Lumopolis? Apenas o que está acontecendo?!",
  ui_story_5051_50510301_35_dialog_content = "N-Precisamos resgatá-los!",
  ui_story_5051_50510301_36_dialog_content = "Espere! Jakine disse que não podemos interferir em nada uma vez dentro do Cristal da Memória Eterna!",
  ui_story_5051_50510301_37_dialog_content = "Se enfrentarmos esses Eclipsites, não há como prever quais serão as consequências!",
  ui_story_5051_50510301_38_dialog_content = "Mas...",
  ui_story_5051_50510301_39_dialog_content = "Resista até ser arrastado pro seu túmulo!",
  ui_story_5051_50510301_40_dialog_content = "—?!",
  ui_story_5051_50510301_41_dialog_content = "Os soldados de Lumopolis estão seguros agora, senhor. Podemos retirar a qualquer momento.",
  ui_story_5051_50510301_42_dialog_content = "Ainda não entendo por que estamos resgatando os cães leais de Schwartz, considerando que ele não dá a mínima se vivemos ou morremos.",
  ui_story_5051_50510301_43_dialog_content = "Mesmo em um feriado como este, ele não nos oferecia nem um pedaço de comida ou um lugar para descansar. Ele simplesmente pegou nossos presentes e nos expulsou.",
  ui_story_5051_50510301_44_dialog_content = "Que tipo de City Lord é esse?",
  ui_story_5051_50510301_45_dialog_content = "Não deixe que pequenos deslizes obscureçam sua visão. Quando for a hora certa, a resposta será clara para você.",
  ui_story_5051_50510301_46_dialog_content = "Isso é <color=#FFB400>Tio Istvan</color>...!",
  ui_story_5051_50510301_47_dialog_content = "Espere, isso é Istvan?! Ele parece tão jovem!",
  ui_story_5051_50510301_48_dialog_content = "O quê...?",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>Rumble—Crash!</color>",
  ui_story_5051_50510301_50_dialog_content = "(Trovão? Vai chover no meio de um dia claro?)",
  ui_story_5051_50510301_51_dialog_content = "PlayerName! Olhe!!",
  ui_story_5051_50510301_52_dialog_content = "Não me diga que há mais Eclipsites?!",
  ui_story_5051_50510301_53_dialog_content = "Simplesmente não há fim para esses monstros!",
  ui_story_5051_50510302_1_dialog_content = "Ha... Ha... Ha...",
  ui_story_5051_50510302_2_dialog_content = "Espero que não haja mais deles. estou no meu limite...",
  ui_story_5051_50510302_3_dialog_content = "Princesa <color=#FFB400>Verônica</color>! Você está bem?",
  ui_story_5051_50510302_4_dialog_content = "Princesa Verônica! É realmente a princesa Veronica!",
  ui_story_5051_50510302_5_dialog_content = "Por que você estaria aqui, Alteza?!",
  ui_story_5051_50510302_6_dialog_content = "Eu, er, eu estou bem.",
  ui_story_5051_50510302_7_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5051_50510302_8_dialog_content = "Mas devo dizer que aquela demonstração de força e bravura não era nada típica de você.",
  ui_story_5051_50510302_9_dialog_content = "Não ousei assumir sua identidade antes. Por favor, perdoe minha ignorância, Alteza.",
  ui_story_5051_50510302_10_dialog_content = "P-Por favor, não diga isso!",
  ui_story_5051_50510302_11_dialog_content = "Hoje é apenas uma ocasião especial, só isso.",
  ui_story_5051_50510302_12_dialog_content = "(Huh? Por que você está olhando para mim, Mia?)",
  ui_story_5051_50510302_13_dialog_content = "Eu não poderia concordar mais, e é por isso que estou confuso por você estar aqui em primeiro lugar.",
  ui_story_5051_50510302_14_dialog_content = "Então, novamente... Não é minha função me preocupar com essas coisas. Por favor, tenha mais cuidado ao colocar os pés fora da cidade, Alteza.",
  ui_story_5051_50510302_15_dialog_content = "Obrigado pela sua preocupação.",
  ui_story_5051_50510302_16_dialog_content = "Senhor Schwartz e acabei de terminar nossa reunião há algum tempo. Estávamos tão ocupados que não tive tempo de conversar com Lady Joshua.",
  ui_story_5051_50510302_17_dialog_content = "Por favor, dê a ela minhas mais sinceras desculpas.",
  ui_story_5051_50510302_18_dialog_content = "E se for possível... Por favor, peça ao seu pai para me dar uma resposta assim que puder.",
  ui_story_5051_50510302_19_dialog_content = "Muito bem... Farei questão de entregar suas mensagens a eles. Obrigado novamente por toda a sua ajuda.",
  ui_story_5051_50510302_20_dialog_content = "Estou simplesmente fazendo o que é certo, Alteza. Não são necessários agradecimentos.",
  ui_story_5051_50510302_21_dialog_content = "(Então Mia realmente é uma princesa!)",
  ui_story_5051_50510302_22_dialog_content = "Perdoe-me, jovem.",
  ui_story_5051_50510302_23_dialog_content = "Eu?",
  ui_story_5051_50510302_24_dialog_content = "Sim você. Só posso supor que você é um amigo próximo de Sua Alteza, correto?",
  ui_story_5051_50510302_25_dialog_content = "Não é qualquer um que pode reivindicar a honra de ser protegido por ela, você sabe.",
  ui_story_5051_50510302_26_dialog_content = "Você deve confiar em seu próprio poder para ter sucesso na vida.",
  ui_story_5051_50510302_27_dialog_content = "Em vez de se esconder atrás de outra pessoa.",
  ui_story_5051_50510302_28_dialog_content = "T-Tá...",
  ui_story_5051_50510302_29_dialog_content = "Uh, perdoe-me, mas já nos encontramos em algum lugar antes?",
  ui_story_5051_50510302_30_dialog_content = "Hahaha! Eu não esperava ouvir isso como seu comentário de abertura, meu amigo.",
  ui_story_5051_50510302_31_dialog_content = "A resposta é não.",
  ui_story_5051_50510302_32_dialog_content = "Mas se você quiser se encontrar novamente, sinta-se à vontade para me visitar em Umbraton.",
  ui_story_5051_50510302_33_dialog_content = "Em breve, ele se tornará um império das sombras.",
  ui_story_5051_50510302_34_dialog_content = "As sombras cercam a todos nós, mas se você pode ou não sobreviver nelas depende de sua própria força.",
  ui_story_5051_50510302_35_dialog_content = "As sombras nos cercam a todos... Como você está certo.",
  ui_story_5051_50510302_36_dialog_content = "Tenho certeza que Umbraton se tornará um lugar muito melhor sob sua liderança, tio... quero dizer, Sr. Istvan.",
  ui_story_5051_50510302_37_dialog_content = "Estou honrado em receber tais palavras de elogio de você, milady.",
  ui_story_5051_50510302_38_dialog_content = "Está ficando tarde. Devíamos estar a caminho agora.",
  ui_story_5051_50510302_39_dialog_content = "Até o próximo encontro, princesa Veronica. Você também, meu jovem e interessante amigo.",
  ui_story_5051_50510302_40_dialog_content = "Tome cuidado... Você sabe, isso Istvan parece muito mais legal do que o que eu conheço.",
  ui_story_5051_50510302_41_dialog_content = "Não vou mentir, parece bastante intrigante.",
  ui_story_5051_50510302_42_dialog_content = "Isso mesmo, eu me lembro do tio Istvan sendo muito mais alegre no passado também.",
  ui_story_5051_50510302_43_dialog_content = "Mas com tudo o que aconteceu desde então... Não é surpresa que todos tenham mudado tanto.",
  ui_story_5051_50510302_44_dialog_content = "Então você realmente é a princesa Veronica, não é?",
  ui_story_5051_50510302_45_dialog_content = "Quando Istvan te chamou assim, você respondeu como se fosse a coisa mais normal do mundo. Foi completamente diferente de suas respostas tímidas habituais.",
  ui_story_5051_50510302_46_dialog_content = "S-Sério?",
  ui_story_5051_50510302_47_dialog_content = "Ainda não consegui juntar todas as minhas memórias. Só consigo me lembrar de pedacinho do passado agora.",
  ui_story_5051_50510302_48_dialog_content = "Mas por alguma razão, quando eu vi o eu mais jovem do tio Istvan...",
  ui_story_5051_50510302_49_dialog_content = "É como se meu corpo se lembrasse do discurso e etiqueta corretos antes que minha mente pudesse alcançá-los.",
  ui_story_5051_50510302_50_dialog_content = "Desculpe, eu sei que isso não faz muito sentido.",
  ui_story_5051_50510302_51_dialog_content = "Não se preocupe com isso! Viemos para encontrar respostas sobre o seu passado, e muito mais aconteceu do que esperávamos. É normal que você se sinta um pouco confuso.",
  ui_story_5051_50510302_52_dialog_content = "Você poderia me contar mais sobre a princesa Veronica em suas memórias, Mia?",
  ui_story_5051_50510302_53_dialog_content = "Claro, sem problemas.",
  ui_story_5051_50510302_54_dialog_content = "Verônica era uma <color=#FFB400>princesa</color> de Lumopolis, bem como a de Lord Schwartz <color=#FFB400>filha mais velha</color>.",
  ui_story_5051_50510302_55_dialog_content = "Mas muitos anos atrás, Lumopolis declarou ao resto do mundo que ela tinha <color=#FFB400>faleceu</color>...",
  ui_story_5051_50510302_56_dialog_content = "Faleceu? Mas por que?",
  ui_story_5051_50510302_57_dialog_content = "Porque ela tinha manchado o Schwartz reputação da família.",
  ui_story_5051_50510302_58_dialog_content = "Como resultado de sua desgraça, Verônica perdeu o direito de continuar vivendo.",
  ui_story_5051_50510302_59_dialog_content = "Reputação? Desgraça? Essas coisas são realmente importantes o suficiente para custar a vida de alguém?",
  ui_story_5051_50510302_60_dialog_content = "É assim que a nobreza opera. Para eles, nada é mais importante do que manter sua reputação...",
  ui_story_5051_50510302_61_dialog_content = "Você sabe sobre <color=#FFB400>Convocações de Lumina</color>, certo PlayerName?",
  ui_story_5051_50510302_62_dialog_content = "Além de Baba Yaga, lembro-me de ter outro amigo assustador chamado Hippoca.",
  ui_story_5051_50510302_63_dialog_content = "Ele era minha Invocação de Lumina. Quando criança, eu queria ficar mais forte do que qualquer outra coisa, então treinei e treinei o máximo que pude...",
  ui_story_5051_50510302_64_dialog_content = "E o resultado do meu treinamento foi Hippoca.",
  ui_story_5051_50510302_65_dialog_content = "Mas todos não gostavam de sua aparência. Uma aranha com cabeça de cavalo... Todos o chamavam de monstro.",
  ui_story_5051_50510302_66_dialog_content = "Mas quem mais o odiava... era meu pai. Ele sempre dizia que Hippoca trouxe críticas injustificadas à nossa família.",
  ui_story_5051_50510302_67_dialog_content = "Que Hippoca era um mau presságio e que nunca deveria ter existido... Em pouco tempo, comecei a temê-lo também.",
  ui_story_5051_50510302_68_dialog_content = "Hippoca era a manifestação de meus próprios poderes, mas eu o rejeitei por causa da desaprovação de todos.",
  ui_story_5051_50510302_69_dialog_content = "No final, perdi a capacidade de usar Luminatics.",
  ui_story_5051_50510302_70_dialog_content = "E Baba Yaga, que compartilha algumas semelhanças com Hippoca, herdou meus poderes perdidos.",
  ui_story_5051_50510302_71_dialog_content = "De certa forma, recebi exatamente o que merecia.",
  ui_story_5051_50510302_72_dialog_content = "Pobre princesa Veronica...",
  ui_story_5051_50510302_73_dialog_content = "Mas como todos aqui ainda te chamam por esse nome, isso significa...",
  ui_story_5051_50510302_74_dialog_content = "Sua Alteza! Como poderíamos recompensá-lo por salvar nossas vidas?",
  ui_story_5051_50510302_75_dialog_content = "I-Não foi nada, realmente.",
  ui_story_5051_50510302_76_dialog_content = "Estão todos bem?",
  ui_story_5051_50510302_77_dialog_content = "Fique tranquilo, Alteza. Graças a você, sofremos apenas ferimentos leves e estamos prontos para continuar a qualquer momento.",
  ui_story_5051_50510302_78_dialog_content = "Você e seu amigo são bem-vindos para cavalgar conosco de volta à cidade, se desejarem?",
  ui_story_5051_50510302_79_dialog_content = "Isso seria maravilhoso, obrigado.",
  ui_story_5051_50510302_80_dialog_content = "Uh, desculpe-me, mas você poderia me dizer em que ano estamos?",
  ui_story_5051_50510302_81_dialog_content = "Que ano? Isso é <color=#FFB400>Calendário matutino ano 1988</color>. Por que você pergunta?",
  ui_story_5051_50510302_82_dialog_content = "(1988? Então isso significa... Isso é <color=#FFB400>doze anos no passado</color>!)",
  ui_story_5051_50510302_83_dialog_content = "(Nesse caso, Eraveil já teria sido destruído.)",
  ui_story_5051_50510302_84_dialog_content = "(Isso significa que ainda não encontrarei nenhum de meus parentes dentro deste Cristal de Memória Eterna...)",
  ui_story_5051_50510302_85_dialog_content = "Algo está errado, PlayerName?",
  ui_story_5051_50510302_86_dialog_content = "Não é nada. Mia, você poderia vir aqui por um segundo?",
  ui_story_5051_50510302_87_dialog_content = "O-O que é?",
  ui_story_5051_50510302_88_dialog_content = "Parece que o mundo dentro do cristal é <color=#FFB400>Lumopolis de doze anos atrás</color>.",
  ui_story_5051_50510302_89_dialog_content = "Se meu palpite estiver certo, os outros que estavam na sala de recepção conosco também deveriam ter sido transportados para cá.",
  ui_story_5051_50510302_90_dialog_content = "Eu sei Jakine disse que não devemos interferir no mundo ao nosso redor.",
  ui_story_5051_50510302_91_dialog_content = "Mas acho que não temos escolha. Não temos mais como nos esconder aqui, e não consigo sentir os outros com minhas habilidades psíquicas.",
  ui_story_5051_50510302_92_dialog_content = "Devemos usar seu status de princesa para encontrá-los e procurar um caminho de volta.",
  ui_story_5051_50510302_93_dialog_content = "...",
  ui_story_5051_50510302_94_dialog_content = "O que foi, Mia?",
  ui_story_5051_50510302_95_dialog_content = "Hum, PlayerName?",
  ui_story_5051_50510302_96_dialog_content = "Tudo bem se eu fosse ver minha mãe uma última vez antes de partirmos?",
  ui_story_5051_50510302_97_dialog_content = "Quando eu estava me escondendo debaixo da mesa mais cedo, ouvi-os dizer que ela havia falecido enquanto eu estava fora.",
  ui_story_5051_50510302_98_dialog_content = "Eu queria voltar a Lumopolis para ver ela e minha irmãzinha. Eu tinha tanto que queria compartilhar com eles.",
  ui_story_5051_50510302_99_dialog_content = "Queria mostrar a eles que cresci e que sou mais corajosa do que antes, e contar a eles sobre os amigos que fiz fora da cidade.",
  ui_story_5051_50510302_100_dialog_content = "E... eu queria dizer a minha mãe que sinto falta dela todos os dias...",
  ui_story_5051_50510302_101_dialog_content = "Mas é muito tarde.",
  ui_story_5051_50510302_102_dialog_content = "... Sua mãe é a esposa do Senhor da Cidade.",
  ui_story_5051_50510302_103_dialog_content = "Se conseguirmos encontrá-la, tenho certeza que ela poderá nos ajudar a voltar ao mundo real!",
  ui_story_5051_50510302_104_dialog_content = "Fazer uma visita a ela seria do interesse de todos, certo?",
  ui_story_5051_50510302_105_dialog_content = "Uh, PlayerName? Parece que você está apenas distorcendo as coisas para trabalhar a nosso favor...",
  ui_story_5051_50510302_106_dialog_content = "Heheheh, mas faz sentido, não?",
  ui_story_5051_50510302_107_dialog_content = "Você pode agradecer a todos os nossos amigos no Colossus por me ensinar como fazer isso!",
  ui_story_5051_50510302_108_dialog_content = "O-Ok então, vou apenas seguir sua liderança.",
  ui_story_5051_50510302_109_dialog_content = "De alguma forma, parece que estou dando um mau exemplo para você, Mia...",
  ui_story_5051_50510302_110_dialog_content = "Perdoe-me, mas... você está pronto para ir? Estamos com um cronograma apertado.",
  ui_story_5051_50510302_111_dialog_content = "Ah, desculpe por isso! Estamos prontos para ir quando você estiver!",
  ui_story_5051_50510302_112_dialog_content = "Parece que sua equipe está com pressa. Você poderia nos dizer o que você está transportando?",
  ui_story_5051_50510302_113_dialog_content = "Não é nada particularmente delicado, apenas alguns itens especiais que precisam ser entregues com antecedência. Nomeadamente...",
  ui_story_5051_50510302_114_dialog_content = "Itens necessários para este ano <color=#FFB400>Schwartz Dia da família</color>.",
  ui_story_5051_50510302_115_dialog_content = "(Schwartz Dia da família? Isso é um pouco demais de coincidência.)",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_5051_50510302_117_dialog_content = "Mais trovão...",
  ui_story_5051_50510302_118_dialog_content = "Tem algum problema?",
  ui_story_5051_50510302_119_dialog_content = "Não, nada. Devemos ir antes que comece a chover!",
  ui_story_5051_50510302_120_dialog_content = "Chuva? Não sabia que ia chover hoje. De qualquer forma, partiremos imediatamente.",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>... Sch...</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>... Schwartz...</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "...",
  ui_story_5051_50510402_2_dialog_content = "Hmph... Então há Eclipsites à espreita em lugares como este também.",
  ui_story_5051_50510402_3_dialog_content = "Desde quando Lumopolis se tornou um terreno fértil para esses monstros miseráveis?",
  ui_story_5051_50510402_4_dialog_content = "Ufa! Estou salvo!",
  ui_story_5051_50510402_5_dialog_content = "Obrigado, Sr. Caleb! Se não fosse por você ter aparecido bem na hora, eu teria sido ceia para aqueles Eclipsites...",
  ui_story_5051_50510402_6_dialog_content = "Não, espere, faça aquele almoço! Ainda é dia, afinal.",
  ui_story_5051_50510402_7_dialog_content = "Também estou um pouco confuso sobre isso.",
  ui_story_5051_50510402_8_dialog_content = "Era claramente noite quando ainda estávamos no palácio, Srta. Jakine.",
  ui_story_5051_50510402_9_dialog_content = "Mas agora é dia e nos encontramos no meio de uma floresta.",
  ui_story_5051_50510402_10_dialog_content = "Será que fomos transportados para o Cristal da Memória Eterna?",
  ui_story_5051_50510402_11_dialog_content = "Isso mesmo! Embora, para ser totalmente honesto, não pensei que juntar um monte de encantamentos funcionaria tão bem!",
  ui_story_5051_50510402_12_dialog_content = "Talvez eu seja um gênio, afinal...",
  ui_story_5051_50510402_13_dialog_content = "(Ah sim, só um gênio poderia ter feito algo assim...)",
  ui_story_5051_50510402_14_dialog_content = "A julgar pelas estruturas à distância, parece que estamos em algum lugar nos arredores de Lower Lumopolis.",
  ui_story_5051_50510402_15_dialog_content = "Quanto ao caixote, que você acabou de esmagar ao se sentar nele...",
  ui_story_5051_50510402_16_dialog_content = "O rótulo indica que foi preparado especificamente para Schwartz Dia da família.",
  ui_story_5051_50510402_17_dialog_content = "Sim, e me deu um susto agora!",
  ui_story_5051_50510402_18_dialog_content = "Parecia resistente o suficiente, mas quebrou assim que coloquei meu peso sobre ele!",
  ui_story_5051_50510402_19_dialog_content = "Como eu poderia saber que um monte de Eclipsites iria acabar?!",
  ui_story_5051_50510402_20_dialog_content = "Apenas o que está acontecendo por aqui? Não me diga que o pessoal de Lumopolis gosta de manter essas coisas como animais de estimação?!",
  ui_story_5051_50510402_21_dialog_content = "Posso garantir que meu povo não tem absolutamente nenhum interesse em criar bestas violentas e irracionais como essas.",
  ui_story_5051_50510402_22_dialog_content = "Eclipsites preparados apenas para Schwartz Dia da Família... Entendo. Deve ser Lumopolis de doze anos atrás.",
  ui_story_5051_50510402_23_dialog_content = "Esconder caixotes de Eclipsites em um transporte cheio de mercadorias para o Schwartz família... Um movimento ousado por parte dos culpados por trás deste ataque.",
  ui_story_5051_50510402_24_dialog_content = "Espere... Isso significa que os Eclipsitas conseguiram invadir Lumópolis doze anos atrás?",
  ui_story_5051_50510402_25_dialog_content = "Isso mesmo. Embora eu não saiba ao certo como o resto do mundo vê nosso bastião no céu...",
  ui_story_5051_50510402_26_dialog_content = "Na realidade, não é tão impenetrável quanto parece.",
  ui_story_5051_50510402_27_dialog_content = "Ah, Sr. Caleb...",
  ui_story_5051_50510402_28_dialog_content = "Por acaso você viu mais alguém antes de nos encontrarmos?",
  ui_story_5051_50510402_29_dialog_content = "Não. Na verdade, eu tinha acabado de acordar quando nossos caminhos se cruzaram.",
  ui_story_5051_50510402_30_dialog_content = "Oh. Hahaha... Bem, o encantamento era para nos teletransportar todos para o mesmo lugar.",
  ui_story_5051_50510402_31_dialog_content = "Além disso, os Eclipsites aqui não deveriam ter sido capazes de nos notar.",
  ui_story_5051_50510402_32_dialog_content = "Afinal, parece que cometi um pequenino erro!",
  ui_story_5051_50510402_33_dialog_content = "... Perder Jakine, Sinto que devo perguntar-lhe uma coisa.",
  ui_story_5051_50510402_34_dialog_content = "A-Aham! Mas não se preocupe! Eu vou assumir total responsabilidade e garantir que todos voltem sãos e salvos!",
  ui_story_5051_50510402_35_dialog_content = "Não era isso que eu ia perguntar.",
  ui_story_5051_50510402_36_dialog_content = "O Lumina da pessoa que ativou este Cristal da Memória Eterna... Está em algum lugar aqui?",
  ui_story_5051_50510402_37_dialog_content = "Sim, claro que é!",
  ui_story_5051_50510402_38_dialog_content = "Por acaso você sabe onde, exatamente?",
  ui_story_5051_50510402_39_dialog_content = "V-você quer saber onde é? Deixe-me ver...",
  ui_story_5051_50510402_40_dialog_content = "\"O Cristal da Memória Eterna deve ser ativado com o Lumina de seu dono. É a fonte de poder que mantém o mundo dentro do cristal.\"",
  ui_story_5051_50510402_41_dialog_content = "<size=30>Isso é realmente tudo?!</size>",
  ui_story_5051_50510402_42_dialog_content = "A-Aham! Na minha opinião profissional, o Lumina usado para alimentar este mundo inteiro provavelmente está alojado em algum lugar extremamente importante!",
  ui_story_5051_50510402_43_dialog_content = "E o lugar mais importante em que consigo pensar...",
  ui_story_5051_50510402_44_dialog_content = "— é o Cristal da Memória Eterna dentro deste mundo!",
  ui_story_5051_50510402_45_dialog_content = "Acho que isso faz sentido...",
  ui_story_5051_50510402_46_dialog_content = "Eu tenho outra pergunta. Se Lumina é o que sustenta este mundo, então, naturalmente, ela teria que acabar algum dia, não é?",
  ui_story_5051_50510402_47_dialog_content = "Já se passaram doze anos desde que este cristal foi ativado. Quanto tempo mais tem?",
  ui_story_5051_50510402_48_dialog_content = "Ah, não precisa se preocupar com isso!",
  ui_story_5051_50510402_49_dialog_content = "Contanto que um cristal seja reabastecido com água do Lago Mirror uma vez a cada doze anos, sua Lumina não desaparecerá por muito, muito tempo!",
  ui_story_5051_50510402_50_dialog_content = "No entanto, adulterar a ordem das coisas no mundo de um cristal pode facilmente acelerar seu consumo de Lumina.",
  ui_story_5051_50510402_51_dialog_content = "Em casos extremos, uma única ação pode fazer com que esgote toda a sua Lumina em um instante.",
  ui_story_5051_50510402_52_dialog_content = "Se isso acontecer, não posso garantir que sobreviveremos!",
  ui_story_5051_50510402_53_dialog_content = "É isso que você quis dizer com \"catástrofe inimaginável\"?",
  ui_story_5051_50510402_54_dialog_content = "Sim, mais ou menos. Naturalmente, também pode haver outras consequências não intencionais...",
  ui_story_5051_50510402_55_dialog_content = "É por isso que precisamos encontrar os outros imediatamente!",
  ui_story_5051_50510402_56_dialog_content = "Não podemos ficar muito tempo em lugares onde não podemos nos esconder.",
  ui_story_5051_50510402_57_dialog_content = "Você está absolutamente certa, e é por isso que estou deixando esta importante tarefa em suas mãos \"capazes\", senhorita Jakine.",
  ui_story_5051_50510402_58_dialog_content = "Tenho outros assuntos para tratar. Boa sorte.",
  ui_story_5051_50510402_59_dialog_content = "Huh?! Espere, você não pode simplesmente despejar isso em mim e ir embora assim!",
  ui_story_5051_50510402_60_dialog_content = "Além disso, não acabei de dizer que temos que ter cuidado? Mudar até mesmo a menor coisa neste mundo pode significar um desastre para todos nós!",
  ui_story_5051_50510402_61_dialog_content = "Você fez, e eu não tenho nenhuma intenção de quebrar as regras. Os outros, no entanto, requerem sua supervisão rigorosa.",
  ui_story_5051_50510402_62_dialog_content = "Ainda resta um pouco de Lumina neste mundo. Prefiro continuar assim até estarmos seguros.",
  ui_story_5051_50510402_63_dialog_content = "Ugh, você não está ouvindo? Você mesmo disse: aqui é Lumopolis! O que você vai fazer se encontrar seu eu do passado?!",
  ui_story_5051_50510402_64_dialog_content = "Não se preocupe com isso. Neste dia, eu estava escoltando minha sobrinha para Umbraton, junto com vários de nossos cavaleiros. Eu não estava nem perto da cidade.",
  ui_story_5051_50510402_65_dialog_content = "Certamente o alcance do Cristal da Memória Eterna não chega tão longe?",
  ui_story_5051_50510402_66_dialog_content = "Bem, isso também é um fato...",
  ui_story_5051_50510402_67_dialog_content = "Pretendo entrar na cidade disfarçado de hóspede. Irei procurá-lo assim que tiver a chance de ver alguém.",
  ui_story_5051_50510402_68_dialog_content = "Então você está disposto a arriscar todas as nossas vidas só para ver essa pessoa?",
  ui_story_5051_50510402_69_dialog_content = "Precisamente. Embora nunca possamos realmente voltar ao passado, com que frequência temos a chance de recuperar o que foi perdido?",
  ui_story_5051_50510402_70_dialog_content = "Por favor, reúna os outros o mais rápido que puder, senhorita Jakine. Até a próxima.",
  ui_story_5051_50510402_71_dialog_content = "Espere! Você nem me disse onde devemos nos encontrar mais tarde!",
  ui_story_5051_50510402_72_dialog_content = "Ótimo, ele já se foi...",
  ui_story_5051_50510402_73_dialog_content = "O que aconteceu com aquela pessoa toda refinada e cavalheiresca? Foi tudo apenas um ato?",
  ui_story_5051_50510402_74_dialog_content = "Como ele pode ser tão egoísta e imprudente em um momento como este?!",
  ui_story_5051_50510402_75_dialog_content = "Ahhh - estou tão bravo que poderia cuspir!",
  ui_story_5051_50510402_76_dialog_content = "Suspiro... \"A chance de recuperar o que foi perdido\", hein?",
  ui_story_5051_50510402_77_dialog_content = "Eu me pergunto se eu vou ter esse tipo de chance também?",
  ui_story_5051_50510402_78_dialog_content = "Mãe... Doze anos atrás, você veio a Lumopolis para entregar este Cristal da Memória Eterna ao Lorde da Cidade, e depois voltou direto para Northland.",
  ui_story_5051_50510402_79_dialog_content = "Papai sempre disse que nunca poderia te entender. Deixar sua família para trás para praticar a adivinhação, fugir para as montanhas sem se despedir.",
  ui_story_5051_50510402_80_dialog_content = "Mas Sua Majestade diz que você é um gênio e ascendeu além de nossas limitações mundanas... Nesse aspecto, acho que não somos nada parecidos.",
  ui_story_5051_50510402_81_dialog_content = "Eu me pergunto o que você diria se nos víssemos aqui?",
  ui_story_5051_50510402_82_dialog_content = "... Oh, o que estou pensando?!",
  ui_story_5051_50510402_83_dialog_content = "Foco, Jakine! Você está aqui como enviado de Northland, lembra?",
  ui_story_5051_50510402_84_dialog_content = "Você não pode confiar em ninguém além de você mesmo agora! É seu trabalho tirar todos daqui com segurança!",
  ui_story_5051_50510402_85_dialog_content = "*inalar exalar*",
  ui_story_5051_50510402_86_dialog_content = "Tudo bem! enviado de Northland Jakine está pronto para rolar!",
  ui_story_5051_50510501_1_dialog_content = "(Não há muitos lugares onde Schwartz poderia ter escondido o Cristal da Memória Eterna. Se eu estiver certo, deve estar em algum lugar da casa dele.)",
  ui_story_5051_50510501_2_dialog_content = "(O banquete do Dia da Família deste ano foi muito maior em escala, então a maioria dos guardas foi postada lá para ajudar a manter a ordem.)",
  ui_story_5051_50510501_3_dialog_content = "(Assim que a cerimônia do feriado começar, devo conseguir entrar sorrateiramente por uma das áreas menos protegidas.)",
  ui_story_5051_50510501_4_dialog_content = "(Até lá, só preciso manter a discrição e esperar pacientemente.)",
  ui_story_5051_50510501_5_dialog_content = "(O jardim ali deve estar bem vazio...)",
  ui_story_5051_50510501_6_dialog_content = "(Íris... Um símbolo de boas novas, assim como de saudade.)",
  ui_story_5051_50510501_7_dialog_content = "(Lembro que minha irmã plantou isso apenas para sua filha mais velha.)",
  ui_story_5051_50510501_8_dialog_content = "... Eu sei que seu tempo está quase acabando, pequeninos.",
  ui_story_5051_50510501_9_dialog_content = "Mas você não poderia, por favor, manter suas flores por mais alguns dias?",
  ui_story_5051_50510501_10_dialog_content = "Minha filha estará em casa em breve. Eu adoraria se ela tivesse a chance de ver sua beleza.",
  ui_story_5051_50510501_11_dialog_content = "Ela costumava gostar tanto de flores. Tenho certeza de que ela sorriria novamente ao vê-lo.",
  ui_story_5051_50510501_12_dialog_content = "É... É mesmo você...?",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>Joshua</color>...?",
  ui_story_5051_50510501_14_dialog_content = "Oh!",
  ui_story_5051_50510501_15_dialog_content = "Olá, senhor.",
  ui_story_5051_50510501_16_dialog_content = "O que o traz ao meu jardim nesta linda tarde?",
  ui_story_5051_50510501_17_dialog_content = "Er, me perdoe por perguntar, mas...",
  ui_story_5051_50510501_18_dialog_content = "Já nos encontramos?",
  ui_story_5051_50510501_19_dialog_content = "... Receio que não. Eu sou apenas um nobre de baixo escalão, indigno de tal honra.",
  ui_story_5051_50510501_20_dialog_content = "Mesmo assim, é um prazer conhecê-la, Lady Joshua.",
  ui_story_5051_50510501_21_dialog_content = "É mesmo?",
  ui_story_5051_50510501_22_dialog_content = "Eu poderia jurar... Não importa, meus olhos devem estar me enganando.",
  ui_story_5051_50510501_23_dialog_content = "(Joshua...)",
  ui_story_5051_50510501_24_dialog_content = "(Eu estava apenas mentindo para aquela cartomante de Northland sobre ter visto alguém.)",
  ui_story_5051_50510501_25_dialog_content = "(Na verdade, nunca esperei vê-lo aqui.)",
  ui_story_5051_50510501_26_dialog_content = "(Depois de doze anos, finalmente tenho a chance de falar com você novamente.)",
  ui_story_5051_50510501_27_dialog_content = "(E, no entanto, só posso fazê-lo fingindo ser um estranho...)",
  ui_story_5051_50510501_28_dialog_content = "(Eu vim a este mundo para recuperar a Lumina que minha irmã deixou para trás.)",
  ui_story_5051_50510501_29_dialog_content = "(Isso tudo é apenas uma ilusão criada pelos truques secretos de Northland. Não posso deixar que isso me distraia do meu objetivo.)",
  ui_story_5051_50510501_30_dialog_content = "(Preciso acabar com essa farsa, de uma vez por todas...!)",
  ui_story_5051_50510501_31_dialog_content = "Você está bem? Você parece estar com dor...",
  ui_story_5051_50510501_32_dialog_content = "Me desculpe.",
  ui_story_5051_50510501_33_dialog_content = "Estou apenas incrédulo em minha própria sorte, por ter sido abençoado com a chance de conhecê-lo.",
  ui_story_5051_50510501_34_dialog_content = "Nossa, isso é uma mentira bastante lisonjeira.",
  ui_story_5051_50510501_35_dialog_content = "As lágrimas nos cantos dos olhos dizem o contrário. Você está doendo em algum lugar, por acaso? Ou talvez sua dor resida em seu coração?",
  ui_story_5051_50510501_36_dialog_content = "Você não deveria aguentar tudo sozinha, sabe.",
  ui_story_5051_50510501_37_dialog_content = "...",
  ui_story_5051_50510501_38_dialog_content = "Eu disse que estou bem!",
  ui_story_5051_50510501_39_dialog_content = "Eu só tenho algo no meu olho!",
  ui_story_5051_50510501_40_dialog_content = "O que eles sabem de qualquer maneira... Todos naquela academia são idiotas! Os professores, os alunos, todos eles!",
  ui_story_5051_50510501_41_dialog_content = "Sempre dizendo coisas como: \"Você pode ser esperto, Caleb, mas sem seus pais, você se tornou altivo e arrogante!\"",
  ui_story_5051_50510501_42_dialog_content = "<size=30>E daí se eu não tiver mais meus pais? A única pessoa que eu preciso é minha irmã...</size>",
  ui_story_5051_50510501_43_dialog_content = "Um dia, vou mudar tudo neste lugar! Apenas espere!",
  ui_story_5051_50510501_44_dialog_content = "Eu acredito em você, Calebe.",
  ui_story_5051_50510501_45_dialog_content = "Você nunca foi de se gabar. Eu sei que você pode realizar qualquer coisa que você definir em sua mente.",
  ui_story_5051_50510501_46_dialog_content = "Você realmente acredita em mim?",
  ui_story_5051_50510501_47_dialog_content = "Claro que eu faço.",
  ui_story_5051_50510501_48_dialog_content = "Obrigado... Diga-me uma coisa, Joshua. Se algum dia chegar o dia em que ninguém mais terá que se preocupar com comida ou segurança...",
  ui_story_5051_50510501_49_dialog_content = "Isso significa que você não terá mais que continuar ajudando Daniel?",
  ui_story_5051_50510501_50_dialog_content = "Hmm... Embora seja verdade que nossas vidas seriam muito mais simples se isso acontecesse, tenho o dever de estar com ele. Afinal, ele é meu marido.",
  ui_story_5051_50510501_51_dialog_content = "...",
  ui_story_5051_50510501_52_dialog_content = "Mas, se esse dia chegar, prometo ajudá-lo em todas as suas pesquisas e participar de cada uma de suas apresentações. Como isso soa?",
  ui_story_5051_50510501_53_dialog_content = "Sério?",
  ui_story_5051_50510501_54_dialog_content = "Uhum.",
  ui_story_5051_50510501_55_dialog_content = "Então... Então vou apresentar minha pesquisa em todo o mundo!",
  ui_story_5051_50510501_56_dialog_content = "Você costumava dizer que queria viajar o mundo o tempo todo, mas não fala sobre isso desde que se casou.",
  ui_story_5051_50510501_57_dialog_content = "Por isso, farei o possível para realizar o seu sonho.",
  ui_story_5051_50510501_58_dialog_content = "Nossa, parece que fui enganado de novo. O que vou fazer com você, Caleb?",
  ui_story_5051_50510501_59_dialog_content = "Você já prometeu que viria a todas as minhas apresentações! Não volte atrás em sua palavra agora!",
  ui_story_5051_50510501_60_dialog_content = "Eu sei eu sei. É um acordo, então.",
  ui_story_5051_50510501_61_dialog_content = "Eu... eu só tenho algo no meu olho.",
  ui_story_5051_50510501_62_dialog_content = "Eu não acho. Basta olhar para você, franzindo o nariz para encobrir sua tristeza.",
  ui_story_5051_50510501_63_dialog_content = "Você se parece com meu irmão mais novo...",
  ui_story_5051_50510501_64_dialog_content = "Ele possui um intelecto muito além de sua idade, mas não é diferente de uma criança doce em muitos aspectos.",
  ui_story_5051_50510501_65_dialog_content = "Por exemplo, toda vez que ele chora, ele mente sobre ter algo em seu olho.",
  ui_story_5051_50510501_66_dialog_content = "... Ah, mas onde estão minhas maneiras?",
  ui_story_5051_50510501_67_dialog_content = "Por favor, perdoe-me por falar tão casualmente com você, senhor. É que você me lembrou muito meu irmão.",
  ui_story_5051_50510501_68_dialog_content = "Eu deveria estar envergonhado por ter tratado você de forma tão desrespeitosa.",
  ui_story_5051_50510501_69_dialog_content = "Th-Não precisa se desculpar...",
  ui_story_5051_50510501_70_dialog_content = "Ainda assim, parece tão estranho. Vocês dois são tão diferentes em idade...",
  ui_story_5051_50510501_71_dialog_content = "E ainda assim, de alguma forma, posso sentir a presença dele em você.",
  ui_story_5051_50510501_72_dialog_content = "Independentemente disso, gostaria de reparar minha grosseria agora. Por favor, junte-se a nós como convidado de honra para o nosso banquete esta noite.",
  ui_story_5051_50510501_73_dialog_content = "Se alguém questionar sua presença em nossa mesa, basta mencionar meu nome.",
  ui_story_5051_50510501_74_dialog_content = "E se você se encontrar em algum problema, você sempre pode vir até mim.",
  ui_story_5051_50510501_75_dialog_content = "Ninguém deve suportar sozinho qualquer tipo de sofrimento.",
  ui_story_5051_50510501_76_dialog_content = "Obrigado por sua graciosa oferta, mas sinto que devo recusar. Eu vim aqui a negócios e não tinha intenção de comparecer ao banquete em primeiro lugar.",
  ui_story_5051_50510501_77_dialog_content = "É que essas flores trouxeram algumas boas lembranças à mente, e eu não pude deixar de ficar por um tempo. Perdoe-me por incomodá-lo, Alteza.",
  ui_story_5051_50510501_78_dialog_content = "Com sua licença, devo ir agora... Tome cuidado, Lady Joshua.",
  ui_story_5051_50510501_79_dialog_content = "Oh, você parece estar com muita pressa...",
  ui_story_5051_50510501_80_dialog_content = "May Eu pelo menos sei o seu nome?",
  ui_story_5051_50510501_81_dialog_content = "Embora as pessoas sejam diferentes neste mundo...",
  ui_story_5051_50510501_82_dialog_content = "Lumópolis é sempre a mesma.",
  ui_story_5051_50510501_83_dialog_content = "É verdade. Santidade e estabilidade são as marcas de Lumopolis, assim como a fonte da fé de seu povo.",
  ui_story_5051_50510501_84_dialog_content = "É por isso que as pessoas se sacrificaram tanto ao longo dos anos para proteger sua pureza... No final, ver sua majestade no céu faz tudo valer a pena.",
  ui_story_5051_50510501_85_dialog_content = "Por favor, apresente seus passes de entrada. Isso significa você, garoto!",
  ui_story_5051_50510501_86_dialog_content = "Ah, eu...",
  ui_story_5051_50510501_87_dialog_content = "Desculpe, ele é meu amigo.",
  ui_story_5051_50510501_88_dialog_content = "P-Princesa Veronica?!",
  ui_story_5051_50510501_89_dialog_content = "Por favor, perdoe minha ignorância, Alteza! Vá em frente!",
  ui_story_5051_50510501_90_dialog_content = "Não é nenhum problema. Obrigado por vigiar nossa bela cidade.",
  ui_story_5051_50510501_91_dialog_content = "I-É minha honra!",
  ui_story_5051_50510501_92_dialog_content = "Ufa! Ter uma princesa por perto com certeza vem a calhar!",
  ui_story_5051_50510501_93_dialog_content = "A última vez que fui retido nos portões, também tive que usar o nome de Carleen para passar...",
  ui_story_5051_50510501_94_dialog_content = "Está bem, PlayerName. Você é uma boa pessoa, por isso todos estão sempre dispostos a te ajudar.",
  ui_story_5051_50510501_95_dialog_content = "R-Sério? Heheh, não posso deixar de me sentir um pouco envergonhado...",
  ui_story_5051_50510501_96_dialog_content = "Ah, isso me lembra! Espere um segundo!",
  ui_story_5051_50510501_97_dialog_content = "Perdoe-me, mas você viu nossos amigos passarem pelos portões hoje? Um deles é um senhor mais velho de aparência séria com cabelos brancos e um tapa-olho, o outro é um jovem nobre com cabelos loiros e olhos violeta...",
  ui_story_5051_50510501_98_dialog_content = "Ah, e havia um mestre de adivinhação ruivo de Northland com eles também! Você sabe se eles estão em Lumopolis?",
  ui_story_5051_50510501_99_dialog_content = "Eu não vi os dois primeiros, desculpe.",
  ui_story_5051_50510501_100_dialog_content = "Mas uma enviada de Northland chegou ontem, e ela parece se encaixar na sua descrição.",
  ui_story_5051_50510501_101_dialog_content = "(Um enviado de Northland? Deve ser o predecessor de Jakine.)",
  ui_story_5051_50510501_102_dialog_content = "Entendido. Obrigado pelo seu tempo!",
  ui_story_5051_50510501_103_dialog_content = "Está tudo bem, PlayerName?",
  ui_story_5051_50510501_104_dialog_content = "Acabei de perguntar ao guarda se ele viu os outros, mas parece que não.",
  ui_story_5051_50510501_105_dialog_content = "Acho que teremos que encontrá-los nós mesmos.",
  ui_story_5051_50510501_106_dialog_content = "—!!!",
  ui_story_5051_50510501_107_dialog_content = "Eclipsitos! Como eles entraram na carga?!",
  ui_story_5051_50510501_108_dialog_content = "Tem Eclipsites aqui também?!",
  ui_story_5051_50510501_109_dialog_content = "D-Não se preocupe, eu cuido deles...!",
  ui_story_5051_50510502_1_dialog_content = "Qual é a situação?",
  ui_story_5051_50510502_2_dialog_content = "Capitão <color=#FFB400>mímica</color>! Vários Eclipsites estavam escondidos em uma remessa recém-recebida e nos emboscaram ao serem descobertos!",
  ui_story_5051_50510502_3_dialog_content = "O vendedor responsável pela remessa já foi levado para interrogatório. Nenhuma vítima foi relatada.",
  ui_story_5051_50510502_4_dialog_content = "E no dia do banquete do Dia da Família, de todos os dias.",
  ui_story_5051_50510502_5_dialog_content = "Mande entregar os suspeitos para mim. Por cometerem um crime tão hediondo, eu mesmo os escoltarei ao Tribunal de Justiça.",
  ui_story_5051_50510502_6_dialog_content = "Sim, senhor!",
  ui_story_5051_50510502_7_dialog_content = "E os Eclipsitos? Todos eles foram eliminados?",
  ui_story_5051_50510502_8_dialog_content = "Sim senhor! Nem um único conseguiu escapar!",
  ui_story_5051_50510502_9_dialog_content = "E foi tudo graças à princesa Veronica, nada menos!",
  ui_story_5051_50510502_10_dialog_content = "Princesa Veronica foi absolutamente incrível!",
  ui_story_5051_50510502_11_dialog_content = "Mas eu pensei princesa Carleen estava o guerreiro entre os dois?",
  ui_story_5051_50510502_12_dialog_content = "Não não não! Essa era a princesa Veronica agora há pouco, sem dúvida!",
  ui_story_5051_50510502_13_dialog_content = "Eu não tinha ideia de que ela também era tão talentosa. O Schwartz família é realmente abençoada por ter filhos tão talentosos...",
  ui_story_5051_50510502_14_dialog_content = "<size=30>Uh, PlayerName? Todo mundo fica olhando... Isso está começando a me assustar.</size>",
  ui_story_5051_50510502_15_dialog_content = "Isso porque você é o herói de todos, Mia!",
  ui_story_5051_50510502_16_dialog_content = "Você limpou o chão com aqueles Eclipsites como se tivesse feito isso toda a sua vida!",
  ui_story_5051_50510502_17_dialog_content = "Eu era... realmente tão impressionante?",
  ui_story_5051_50510502_18_dialog_content = "Claro que você estava!",
  ui_story_5051_50510502_19_dialog_content = "O-Oh, ok... Obrigado...",
  ui_story_5051_50510502_20_dialog_content = "Bom trabalho a todos. Já pode deixar o suspeito conosco.",
  ui_story_5051_50510502_21_dialog_content = "Entendido. Obrigado pela ajuda.",
  ui_story_5051_50510502_22_dialog_content = "(Espere um segundo...)",
  ui_story_5051_50510502_23_dialog_content = "(É aquele <color=#FFB400>Sharona</color>?!)",
  ui_story_5051_50510502_24_dialog_content = "Você aí! Quem é você e por que está me olhando assim?",
  ui_story_5051_50510502_25_dialog_content = "Se precisar de ajuda, basta pedir. Posso ser apenas um cavaleiro reserva, mas tenho o dever de prestar minha ajuda, mesmo assim.",
  ui_story_5051_50510502_26_dialog_content = "Se você não tem mais negócios aqui, então eu sugiro que você vá agora.",
  ui_story_5051_50510502_27_dialog_content = "(Merda, ela me viu! Precisamos sair daqui antes que interfira muito com o passado!)",
  ui_story_5051_50510502_28_dialog_content = "(Ainda assim, se isso foi há doze anos, isso não significa Sharona tem apenas quatorze anos? Acho que ela sempre foi tão séria, hein.)",
  ui_story_5051_50510502_29_dialog_content = "I-Não é nada, desculpe por isso. Seus olhos pareciam meio familiares, só isso.",
  ui_story_5051_50510502_30_dialog_content = "Meus olhos, você diz? Que clichê.",
  ui_story_5051_50510502_31_dialog_content = "Você deve guardar esse tipo de conversa para alguém que realmente queira ouvi-la.",
  ui_story_5051_50510502_32_dialog_content = "Haha... Mais uma vez, desculpe incomodá-lo.",
  ui_story_5051_50510502_33_dialog_content = "Se nossos caminhos se cruzarem novamente, talvez eu tenha mais tempo para ouvir suas divagações malucas.",
  ui_story_5051_50510502_34_dialog_content = "Sinta-se à vontade para continuar esperando que esse dia chegue, estranho.",
  ui_story_5051_50510502_35_dialog_content = "Não se preocupe, sei que um dia nos encontraremos novamente!",
  ui_story_5051_50510502_36_dialog_content = "(Afinal, eu sou um bom amigo do futuro você!)",
  ui_story_5051_50510502_37_dialog_content = "Hmph. Lunático...",
  ui_story_5051_50510502_38_dialog_content = "Ei, veja isso, Sharona Puxou conversa na patrulha dela!",
  ui_story_5051_50510502_39_dialog_content = "Ela é apenas uma adolescente, é normal.",
  ui_story_5051_50510502_40_dialog_content = "Você tem razão. Ela costuma ser tão precoce que dói vê-la tão tensa.",
  ui_story_5051_50510502_41_dialog_content = "Suspiro, eu adoraria escapar para ver o desfile...",
  ui_story_5051_50510502_42_dialog_content = "<size=45>Cavaleiros!</size>",
  ui_story_5051_50510502_43_dialog_content = "Hoje é um momento alegre de celebração para toda a nossa cidade. Como membros da prestigiada família Kartima, foi-nos confiada a segurança do nosso pessoal.",
  ui_story_5051_50510502_44_dialog_content = "Como tal, devem portar-se com dignidade e profissionalismo na execução das vossas encomendas!",
  ui_story_5051_50510502_45_dialog_content = "...",
  ui_story_5051_50510502_46_dialog_content = "(Hahaha... Mesmo depois de todos esses anos, parece que Sharona não mudou nada.)",
  ui_story_5051_50510502_47_dialog_content = "Hum, PlayerName? O Sr. Mime diz que pode nos acompanhar para ver minha mãe.",
  ui_story_5051_50510502_48_dialog_content = "N-Não devemos mais perder nosso tempo conversando com aquela garota. Vamos.",
  ui_story_5051_50510502_49_dialog_content = "(Opa, acho que deixei a atmosfera festiva levar a melhor sobre mim...)",
  ui_story_5051_50510502_50_dialog_content = "(Ainda estamos em sério perigo. Não posso continuar baixando minha guarda assim.)",
  ui_story_5051_50510502_51_dialog_content = "Desculpe, eu estava sendo descuidado agora. Farei o possível para não falar com mais ninguém se não for necessário.",
  ui_story_5051_50510502_52_dialog_content = "Isso não foi o que eu quis dizer. É só... Ugh, eu realmente não sei como descrever esse sentimento.",
  ui_story_5051_50510502_53_dialog_content = "Meu peito está apertado e meu coração... meio que dói um pouco.",
  ui_story_5051_50510502_54_dialog_content = "Oh não, você está bem?! Ah, se eu pudesse usar meus poderes agora!",
  ui_story_5051_50510502_55_dialog_content = "Então eu poderia olhar em sua mente e ver se você está bem...",
  ui_story_5051_50510502_56_dialog_content = "N-De jeito nenhum! Por favor, não olhe dentro da minha mente agora...!",
  ui_story_5051_50510502_57_dialog_content = "Oh, PlayerName! Por quão inteligente você é, você pode ser muito denso às vezes!",
  ui_story_5051_50510502_58_dialog_content = "Isso é ótimo. Oh, eu tenho um favor a pedir aos Lumo Knights. Eu volto já!",
  ui_story_5051_50510502_59_dialog_content = "Huh? PlayerName?",
  ui_story_5051_50510502_60_dialog_content = "Olá! Sr. Mime, presumo?",
  ui_story_5051_50510502_61_dialog_content = "O único e o mesmo. Você precisa de algo?",
  ui_story_5051_50510502_62_dialog_content = "Estou procurando meus três amigos. Somos todos convidados da princesa Verônica, mas nos separamos no caminho para cá.",
  ui_story_5051_50510502_63_dialog_content = "Seria possível para você e seus cavaleiros nos ajudar a encontrá-los? Aqui está uma descrição de como eles são...",
  ui_story_5051_50510502_64_dialog_content = "Muito bem, faremos o que pudermos. Eu ainda tenho que me apresentar ao City Lord, então se você me der licença.",
  ui_story_5051_50510502_65_dialog_content = "Obrigado, Sr. Mime.",
  ui_story_5051_50510502_66_dialog_content = "Uh, quando você vir meu pai mais tarde, você pode não mencionar meu amigo e o que aconteceu...?",
  ui_story_5051_50510502_67_dialog_content = "Se isso é tudo que você me pede, então não vejo problema em fazer o que você deseja.",
  ui_story_5051_50510502_68_dialog_content = "No entanto, meus cavaleiros ainda são responsáveis por patrulhar a cidade durante o feriado. Em troca, devo pedir que você e seus amigos evitem causar problemas hoje.",
  ui_story_5051_50510502_69_dialog_content = "Eu entendo. Prometo que nos comportaremos da melhor maneira.",
  ui_story_5051_50510502_70_dialog_content = "Você está pronto, Mia?",
  ui_story_5051_50510502_71_dialog_content = "Sim! Só me certifiquei de que o Sr. Mime não nos mencionasse ao meu pai em seu relatório.",
  ui_story_5051_50510502_72_dialog_content = "Afinal, eu deveria estar com muitos problemas hoje. Se ele descobrisse que eu estava de volta à cidade, ficaria furioso...",
  ui_story_5051_50510502_73_dialog_content = "Verônica?",
  ui_story_5051_50510502_74_dialog_content = "Mãe...?",
  ui_story_5051_50510502_75_dialog_content = "Mãe!",
  ui_story_5051_50510502_76_dialog_content = "Ai minha menininha! Qual é o problema?",
  ui_story_5051_50510502_77_dialog_content = "Mãe... É mesmo você! Oh, eu sinto tanto a sua falta, mãe...",
  ui_story_5051_50510502_78_dialog_content = "Eu tambem meu querido. Mas não se preocupe, estou aqui agora.",
  ui_story_5051_50510502_79_dialog_content = "Deixe-me dar uma olhada em você. Os Lumo Knights te machucaram durante seu treinamento?",
  ui_story_5051_50510502_80_dialog_content = "Ou talvez... Você brigou com um de seus amigos?",
  ui_story_5051_50510502_81_dialog_content = "(Ela está olhando diretamente para mim! A mãe de Mia acha que eu fiz isso com ela! Não, não, você entendeu tudo errado! Não fui eu!!!)",
  ui_story_5051_50510502_82_dialog_content = "Nenhuma mãe, PlayerName nunca faria algo assim. Ele me trouxe aqui para te ver...",
  ui_story_5051_50510502_83_dialog_content = "Eu vejo. Parece que você fez um grande amigo, meu amor.",
  ui_story_5051_50510502_84_dialog_content = "Hum? O que aconteceu com seus joelhos, Veronica? Quais são esses padrões...?",
  ui_story_5051_50510502_85_dialog_content = "Estou bem, mãe! Realmente! Eu tenho...",
  ui_story_5051_50510502_86_dialog_content = "Eu fiquei muito mais corajoso do que antes.",
  ui_story_5051_50510502_87_dialog_content = "Então agora... agora você não precisa se preocupar comigo!",
  ui_story_5051_50510502_88_dialog_content = "É assim mesmo? Essa sua carinha triste não convence muito, sabe.",
  ui_story_5051_50510502_89_dialog_content = "Venha, vamos lavar seu rosto enquanto você me conta como está corajosa agora.",
  ui_story_5051_50510601_1_dialog_content = "(As senhoras entraram...)",
  ui_story_5051_50510601_2_dialog_content = "(A mãe de Mia sorriu para mim quando eles saíram, provavelmente sugerindo que eu esperasse aqui.)",
  ui_story_5051_50510601_3_dialog_content = "(O que é isso mesmo? \"Nunca espie uma dama se preparando\"? Então, tenho que esperar.)",
  ui_story_5051_50510601_4_dialog_content = "(Eu conheci Istvan e Sharona ao longo do caminho, e agora a mãe de Mia...)",
  ui_story_5051_50510601_5_dialog_content = "(Todos eles conversaram conosco como se fossem a pessoa real.)",
  ui_story_5051_50510601_6_dialog_content = "(O Cristal da Memória Eterna é simplesmente maravilhoso...)",
  ui_story_5051_50510601_7_dialog_content = "(Mas nunca foi projetado para interagirmos com eles.)",
  ui_story_5051_50510601_8_dialog_content = "(Portanto, contatos como esse devem estar sobrecarregando os limites do cristal.)",
  ui_story_5051_50510601_9_dialog_content = "(Suspiro, é difícil avaliar se a situação é boa ou ruim. Espero que encontremos Jakine e outros em breve...)",
  ui_story_5051_50510601_10_dialog_content = "Você aí.",
  ui_story_5051_50510601_11_dialog_content = "Esta é a propriedade privada do Schwartz família.",
  ui_story_5051_50510601_12_dialog_content = "Como você conseguiu se esgueirar aqui?",
  ui_story_5051_50510601_13_dialog_content = "Huh? Quem está aí?",
  ui_story_5051_50510601_14_dialog_content = "Olhe para baixo, tolo insolente! Carleen está falando com você!",
  ui_story_5051_50510601_15_dialog_content = "<size=45>Carleen?!</size>",
  ui_story_5051_50510601_16_dialog_content = "Você ousa se dirigir a mim pelo nome?",
  ui_story_5051_50510601_17_dialog_content = "Por mais que eu não goste de ostentar a nobreza de alguém, por esse motivo, menosprezar-me é o mesmo que menosprezar a Casa. Schwartz!",
  ui_story_5051_50510601_18_dialog_content = "Esgueirando-se em nossa terra em Schwartz Dia da família...",
  ui_story_5051_50510601_19_dialog_content = "... e exibindo tal grosseria e manchando um membro. Você vai sofrer as consequências!",
  ui_story_5051_50510601_20_dialog_content = "Espera, fui pego desprevenido!",
  ui_story_5051_50510601_21_dialog_content = "Por favor, deixe-me explicar, princesa Carleen!",
  ui_story_5051_50510601_22_dialog_content = "Adivinha quem?",
  ui_story_5051_50510601_23_dialog_content = "<size=45>Uau!</size>",
  ui_story_5051_50510601_24_dialog_content = "O-o que?!",
  ui_story_5051_50510601_25_dialog_content = "Você ainda traz um cúmplice, intruso desprezível?!",
  ui_story_5051_50510601_26_dialog_content = "Huh? Sim...",
  ui_story_5051_50510601_27_dialog_content = "Isso mesmo, estamos trabalhando juntos para pegar você, pequenino Carleen!",
  ui_story_5051_50510601_28_dialog_content = "D-Desprezível! Onde está minha lança? Ei, solte, não consigo encontrar minha renda!",
  ui_story_5051_50510601_29_dialog_content = "Espere um segundo ... você parece familiar, você é Veronica?",
  ui_story_5051_50510601_30_dialog_content = "Ah-ha! Não, definitivamente não sou a Veronica!",
  ui_story_5051_50510601_31_dialog_content = "Por favor, não tente me enganar com um disfarce vocal tão ruim! Eu não sou mais uma criança!",
  ui_story_5051_50510601_32_dialog_content = "Tem certeza, pequena Carleen?",
  ui_story_5051_50510601_33_dialog_content = "Heh, apesar de uma maturidade além de sua idade, Carleen ainda entrará em pânico quando seus olhos estiverem cobertos.",
  ui_story_5051_50510601_34_dialog_content = "Mãe? Você também está aqui, mãe? Por favor, peça a Veronica para me liberar!",
  ui_story_5051_50510601_35_dialog_content = "Oh? Por que você me chama de mãe de novo? Eu adoraria ouvir você me chamar de mamãe ou não vou te ajudar.",
  ui_story_5051_50510601_36_dialog_content = "P-Por quê?!",
  ui_story_5051_50510601_37_dialog_content = "Isso é o que você ganha por ser mau com o hóspede, Carleen.",
  ui_story_5051_50510601_38_dialog_content = "Você está sendo tão desagradável com alguém que conhece pela primeira vez - isso não é muito legal.",
  ui_story_5051_50510601_39_dialog_content = "É tudo culpa sua, intruso sem vergonha! O que você fez para enganar minha irmã e minha mãe?!",
  ui_story_5051_50510601_40_dialog_content = "Nada, eu não fiz nada!",
  ui_story_5051_50510601_41_dialog_content = "Heehee, eu me pergunto quanto tempo você pode aguentar.",
  ui_story_5051_50510601_42_dialog_content = "Boo-hoo - me desculpe por ter sido maldoso. Deixe-me fora do gancho, por favor!",
  ui_story_5051_50510601_43_dialog_content = "Heehee, eu não provoquei Carleen assim por muito tempo. Estou sem fôlego de tanto rir...",
  ui_story_5051_50510601_44_dialog_content = "Hmph... Má Verônica...",
  ui_story_5051_50510601_45_dialog_content = "Pronto, Verônica. Você fica mais fofo quando ri.",
  ui_story_5051_50510601_46_dialog_content = "Mas Carleen ainda está mal-humorado... Devo fazer cócegas em você?",
  ui_story_5051_50510601_47_dialog_content = "N-Não, não precisa!",
  ui_story_5051_50510601_48_dialog_content = "Assim deve ser a família. Agora só se o Daniel estiver aqui também...",
  ui_story_5051_50510601_49_dialog_content = "Desculpe o incómodo.",
  ui_story_5051_50510601_50_dialog_content = "Eu ouvi que Veronica ligou para você PlayerName. May Eu me dirijo a você da mesma forma?",
  ui_story_5051_50510601_51_dialog_content = "Sem problemas, me chame do que quiser.",
  ui_story_5051_50510601_52_dialog_content = "Semelhante a como você se dirigiu a Veronica como Mia?",
  ui_story_5051_50510601_53_dialog_content = "O que? Uh...",
  ui_story_5051_50510601_54_dialog_content = "(Sua mãe ouviu a conversa entre Mia e eu?!)",
  ui_story_5051_50510601_X54_dialog_content = "Bem, mãe, na verdade... PlayerName é um amigo que fiz em Umbraton...",
  ui_story_5051_50510601_56_dialog_content = "Tudo bem, eu também usava um pseudônimo quando era jovem.",
  ui_story_5051_50510601_57_dialog_content = "Eu entendo. Sempre há espaço para segredos inofensivos, não importa quem seja.",
  ui_story_5051_50510601_58_dialog_content = "Obrigado, mãe...",
  ui_story_5051_50510601_59_dialog_content = "Entendo. Tão pequeno Mia vimos nosso amigo aqui como um bravo cavaleiro de armadura brilhante.",
  ui_story_5051_50510601_60_dialog_content = "Cuja presença é suficiente para devolver uma princesa perdida para casa, estou certo?",
  ui_story_5051_50510601_61_dialog_content = "Ai, mãe...",
  ui_story_5051_50510601_62_dialog_content = "Então você é a guarda real da minha irmã? Mas você tem certeza de que pode protegê-la com seu corpo magro e covarde?",
  ui_story_5051_50510601_63_dialog_content = "Você entendeu errado, pequeno Carleen. Não um guarda real, mas possivelmente o Príncipe Encantado!",
  ui_story_5051_50510601_64_dialog_content = "Mãe! PlayerName é apenas um amigo que conheci em Umbraton!",
  ui_story_5051_50510601_65_dialog_content = "Uma pessoa meiga, paciente que tem me ajudado muito, é isso...",
  ui_story_5051_50510601_66_dialog_content = "Segredos inofensivos? eu não entendo...",
  ui_story_5051_50510601_67_dialog_content = "Entregue seus segredos, intruso desprezível!",
  ui_story_5051_50510601_68_dialog_content = "Ei, meu nome é PlayerName...",
  ui_story_5051_50510601_69_dialog_content = "(Ela bate no meu pé...!)",
  ui_story_5051_50510601_70_dialog_content = "(este mais jovem Carleen também é séria e precoce, mas seu rosto é mais animado e mais espirituoso em geral.)",
  ui_story_5051_50510601_71_dialog_content = "(Sua mãe faleceu, sua irmã desapareceu e o relacionamento com seu pai... Ela passou por muita tristeza.)",
  ui_story_5051_50510601_72_dialog_content = "(Sem tudo isso, Carleen provavelmente sorriria mais.)",
  ui_story_5051_50510601_73_dialog_content = "(E talvez ela ainda bata no meu pé quando está com raiva.)",
  ui_story_5051_50510601_74_dialog_content = "Por que você está me encarando? Você deseja outro golpe?",
  ui_story_5051_50510601_75_dialog_content = "Não, de jeito nenhum. Por favor, poupe-me, princesa Carleen.",
  ui_story_5051_50510601_76_dialog_content = "Desculpe, Carleen sai tão direto apenas porque ela não sabe como se expressar adequadamente. Ela não significa nenhuma malícia.",
  ui_story_5051_50510601_77_dialog_content = "Você é capaz de recuperar memórias completas de sua família, Mi... Veronica?",
  ui_story_5051_50510601_78_dialog_content = "Sim. Depois de se reunir com a mãe e Carleen, as memórias voltaram à tona.",
  ui_story_5051_50510601_79_dialog_content = "Carleen e eu adorava balançar no jardim juntos...",
  ui_story_5051_50510601_80_dialog_content = "Nunca nos cansaremos de jogar Guess Who?",
  ui_story_5051_50510601_81_dialog_content = "As memórias, as emoções, a alegria... Afinal, são todas reais...",
  ui_story_5051_50510601_82_dialog_content = "Sério? Isso é maravilhoso!",
  ui_story_5051_50510601_83_dialog_content = "(Mas Mia ainda não mencionou seu pai, e foi bastante estranho quando eles se encontraram na sala de recepção.)",
  ui_story_5051_50510601_84_dialog_content = "(Será que ela tem um relacionamento morno com ele como Carleen?)",
  ui_story_5051_50510601_85_dialog_content = "Posso oferecer-lhe um lanche ou uma bebida? Está disponível no corredor.",
  ui_story_5051_50510601_86_dialog_content = "Vamos, Veronica, vamos fazer um lanche.",
  ui_story_5051_50510601_87_dialog_content = "Oh, não me puxe com tanta força...",
  ui_story_5051_50510601_88_dialog_content = "Não fique aí parado, PlayerName, venha conosco.",
  ui_story_5051_50510601_89_dialog_content = "Haha... É raro toda a família estar junta e eu não devo me intrometer.",
  ui_story_5051_50510601_90_dialog_content = "Está tudo bem, criança.",
  ui_story_5051_50510601_91_dialog_content = "Estou muito familiarizado com esse olhar em seus olhos.",
  ui_story_5051_50510601_92_dialog_content = "Pode parecer determinado, mas também está manchado com os olhares de uma criança perdida.",
  ui_story_5051_50510601_93_dialog_content = "Você não viveu em dificuldades em Umbraton, viveu?",
  ui_story_5051_50510601_94_dialog_content = "Não! Na verdade, não sou de Umbraton. Eu sou...",
  ui_story_5051_50510601_95_dialog_content = "(Não, não posso dizer a verdade. Caelestite é uma sociedade fechada, muito poucos forasteiros sabiam alguma coisa sobre nós.)",
  ui_story_5051_50510601_96_dialog_content = "(Portanto, mencionar que sou um celestita apenas enfatizaria ainda mais o cristal.)",
  ui_story_5051_50510601_97_dialog_content = "Eu sou apenas o seu Joe Average sem nome.",
  ui_story_5051_50510601_98_dialog_content = "Não tenho família, então gosto de viajar e fazer novos amigos.",
  ui_story_5051_50510601_99_dialog_content = "Viagem? Eu também gosto de viajar. Uma pena não ter oportunidade agora.",
  ui_story_5051_50510601_100_dialog_content = "Você está feliz com sua vida agora, criança?",
  ui_story_5051_50510601_101_dialog_content = "Sim, me sinto muito feliz.",
  ui_story_5051_50510601_102_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5051_50510601_103_dialog_content = "Você é amigo de Veronica e uma criança gentil.",
  ui_story_5051_50510601_104_dialog_content = "Sinta-se à vontade para se sentir em casa durante a sua estadia aqui.",
  ui_story_5051_50510601_105_dialog_content = "Obrigado minha senhora...",
  ui_story_5051_50510601_106_dialog_content = "Meu nome é Joshua e você pode me chamar assim.",
  ui_story_5051_50510601_107_dialog_content = "Sim. Bem, acho melhor chamá-la de Lady Joshua.",
  ui_story_5051_50510601_108_dialog_content = "Você foi em uma missão secreta em Umbraton com Lumo Knights, Veronica?",
  ui_story_5051_50510601_109_dialog_content = "Que tipo de missão é essa? E como você e Lumo Knights lutam? Você pode me falar sobre isso?",
  ui_story_5051_50510601_110_dialog_content = "Bom...",
  ui_story_5051_50510601_111_dialog_content = "Sim, Veronica, você pode me explicar?",
  ui_story_5051_50510601_112_dialog_content = "<size=45>F-Pai!</size>",
  ui_story_5051_50510601_113_dialog_content = "Eu não faria objeção se você tivesse as proezas de um guerreiro para se voluntariar para uma batalha.",
  ui_story_5051_50510601_114_dialog_content = "Mas você abandonou seu posto novamente e voltou para casa para participar da festa.",
  ui_story_5051_50510601_115_dialog_content = "Como você vai expiar a farsa, principalmente no dia da comemoração?",
  ui_story_5051_50510601_116_dialog_content = "...",
  ui_story_5051_50510601_117_dialog_content = "Lembrei-me de Veronica, querida.",
  ui_story_5051_50510601_118_dialog_content = "Hoje é o dia de todos os membros da Casa Schwartz reunir, então ela não deveria estar aqui conosco?",
  ui_story_5051_50510601_119_dialog_content = "Joshua, como você disse, é o House Schwartz, não uma família.",
  ui_story_5051_50510601_120_dialog_content = "Casa Schwartz nunca teve a precedência de uma criança mimada e nunca terá.",
  ui_story_5051_50510601_121_dialog_content = "Sim, somos uma casa, mas muito mais uma família.",
  ui_story_5051_50510601_122_dialog_content = "Como podemos manter uma casa se não podemos nem mesmo manter o coração das pessoas mais próximas de nós?",
  ui_story_5051_50510601_123_dialog_content = "(É aquele Schwartz?)",
  ui_story_5051_50510601_124_dialog_content = "(Ele não é menos impressionante no futuro, mas definitivamente envelheceu com o passar dos anos e é totalmente diferente disso.)",
  ui_story_5051_50510601_125_dialog_content = "(A tensão é tão densa e Mia não parece que ela quer estar aqui... E meus poderes psíquicos decidem agora me abandonar!)",
  ui_story_5051_50510601_126_dialog_content = "Licença.",
  ui_story_5051_50510601_127_dialog_content = "(Ms. Blanc! Com o mesmo vestido que vi antes! Então ela também trabalhava para o City Lord doze anos atrás.)",
  ui_story_5051_50510601_128_dialog_content = "Quem é você?",
  ui_story_5051_50510601_129_dialog_content = "Meu? Eu sou amigo da Verônica...",
  ui_story_5051_50510601_130_dialog_content = "Amigo?",
  ui_story_5051_50510601_131_dialog_content = "Daniel.",
  ui_story_5051_50510601_132_dialog_content = "Multar. Trate a pessoa como um convidado de honra, Sra. Rot.",
  ui_story_5051_50510601_133_dialog_content = "Tá bom.",
  ui_story_5051_50510601_134_dialog_content = "O Conselho Ancião ainda aguarda sua presença, meu senhor.",
  ui_story_5051_50510601_135_dialog_content = "Já que você trouxe Veronica de volta, Joshua, cuide dela.",
  ui_story_5051_50510601_136_dialog_content = "Não permita que ela e sua amiga criem qualquer outro problema.",
  ui_story_5051_50510601_137_dialog_content = "Sem problemas, eu cuidarei dessas crianças.",
  ui_story_5051_50510601_138_dialog_content = "Então, que tal você parar de ser tão mau, você mesmo?",
  ui_story_5051_50510601_139_dialog_content = "Tudo bem...",
  ui_story_5051_50510601_140_dialog_content = "O desfile está prestes a começar. Prepare as crianças.",
  ui_story_5051_50510601_141_dialog_content = "Suspirar...",
  ui_story_5051_50510601_142_dialog_content = "Você está se sentindo bem, Verônica?",
  ui_story_5051_50510601_143_dialog_content = "Seu pai não está com raiva de você, ele só tem muito em sua mesa hoje.",
  ui_story_5051_50510601_144_dialog_content = "Eu... Eu...",
  ui_story_5051_50510601_145_dialog_content = "Agora está tudo bem, meu filho...",
  ui_story_5051_50510601_146_dialog_content = "Verônica...",
  ui_story_5051_50510601_147_dialog_content = "Há tempo antes do desfile, minha senhora. Você ainda tem a chance de conversar com sua família, deixe o resto comigo.",
  ui_story_5051_50510601_148_dialog_content = "Obrigado, Sra. Rot.",
  ui_story_5051_50510601_149_dialog_content = "Apenas fazendo o meu trabalho.",
  ui_story_5051_50510601_150_dialog_content = "Quanto a você, por favor, venha comigo para se acostumar com o processo de desfile e se preparar para os próximos eventos.",
  ui_story_5051_50510601_151_dialog_content = "Fique tranquilo, Lady Joshua é perita em confortar os outros. A princesa Veronica está em boas mãos.",
  ui_story_5051_50510601_152_dialog_content = "Tudo bem... Obrigado, Ms. Blanc.",
  ui_story_5051_50510601_153_dialog_content = "Ms. Blanc? Eu não esperava que alguém me chamasse por esse nome aqui.",
  ui_story_5051_50510601_154_dialog_content = "May Eu pergunto como você sabia desse nome?",
  ui_story_5051_50510601_155_dialog_content = "(Então Ms. Blanc não passou por isso doze anos atrás?)",
  ui_story_5051_50510601_156_dialog_content = "(Pensando bem, o City Lord no mundo real a chamava de Sra. Rot também.)",
  ui_story_5051_50510601_157_dialog_content = "(Esse deve ser o nome quando ela está trabalhando para o City Lord ... Então, como vou passar por isso?)",
  ui_story_5051_50510601_158_dialog_content = "Está bem. Assim como eu tenho meus segredos para guardar, você tem os seus. Isso é justo.",
  ui_story_5051_50510601_159_dialog_content = "Você é um convidado de honra confiado pessoalmente a mim pelo Senhor da Cidade, portanto é meu dever garantir que seu dia seja agradável.",
  ui_story_5051_50510601_160_dialog_content = "No entanto, espero que você me chame de Sra. Rot nesse meio tempo para agilizar minhas obrigações.",
  ui_story_5051_50510601_161_dialog_content = "Claro, Sra. Rot, não vou criar problemas para você.",
  ui_story_5051_50510601_162_dialog_content = "Obrigado pela sua compreensão. Esse caminho por favor.",
  ui_story_5051_50510701_1_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50510701_2_dialog_content = "Por favor, diga-me onde está a pessoa em mente agora?",
  ui_story_5051_50510701_3_dialog_content = "<size=45>Abrahadabra!</size>",
  ui_story_5051_50510701_4_dialog_content = "Ah, à frente!",
  ui_story_5051_50510701_5_dialog_content = "Ouvi dizer que outra unidade de cavaleiros foi transferida para Umbraton.",
  ui_story_5051_50510701_6_dialog_content = "O que? O que eles estão fazendo em Umbraton?",
  ui_story_5051_50510701_7_dialog_content = "Lutando contra a invasão do Eclipsite, eu acho. Umbraton está sob a defesa de Lumopolis, afinal.",
  ui_story_5051_50510701_8_dialog_content = "Então por que não vamos?",
  ui_story_5051_50510701_9_dialog_content = "Você é estúpido? Nós somos os cavaleiros de <color=#FFB400>Cartima</color>. Não podemos ir para um lixão como esse!",
  ui_story_5051_50510701_10_dialog_content = "Shh, fala baixo! não deixe Sharona nos pegar relaxando novamente.",
  ui_story_5051_50510701_11_dialog_content = "Kartima ainda é o melhor. Estamos em pé de igualdade com o Lorde da Cidade.",
  ui_story_5051_50510701_12_dialog_content = "Entendo...",
  ui_story_5051_50510701_13_dialog_content = "Entendo...",
  ui_story_5051_50510701_14_dialog_content = "Ei, quem é você?",
  ui_story_5051_50510701_15_dialog_content = "Pessoa suspeita! Rápido, pegue ela!",
  ui_story_5051_50510701_16_dialog_content = "Desculpe, lugar errado. Tchau!",
  ui_story_5051_50510701_17_dialog_content = "Abrahadabra!",
  ui_story_5051_50510701_18_dialog_content = "Onde eu estou agora?",
  ui_story_5051_50510701_19_dialog_content = "Irridon consegui o primeiro lugar no semestre novamente...",
  ui_story_5051_50510701_20_dialog_content = "Irridon além de bonita e boa aluna, ela também goza de prestígio perante os instrutores de Dawn Academia.",
  ui_story_5051_50510701_21_dialog_content = "Estou verde de inveja.",
  ui_story_5051_50510701_22_dialog_content = "Talvez ela até pule notas e vá direto para a formatura mais tarde.",
  ui_story_5051_50510701_23_dialog_content = "Ela é perfeita demais.",
  ui_story_5051_50510701_24_dialog_content = "Irridon? Quem é aquele?",
  ui_story_5051_50510701_25_dialog_content = "Quem é aquela garota com roupas estranhas? Seu cabelo ruivo é arrebatador, no entanto.",
  ui_story_5051_50510701_26_dialog_content = "Que tipo de traje é esse? Terei que denunciá-la ao Tribunal de Justiça!",
  ui_story_5051_50510701_27_dialog_content = "Ops, lugar errado de novo, desculpe!",
  ui_story_5051_50510701_28_dialog_content = "Abra... hadabra...",
  ui_story_5051_50510701_29_dialog_content = "Isso é... um restaurante?",
  ui_story_5051_50510701_30_dialog_content = "Mas não vejo ninguém aqui.",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>Rosnar-</color>",
  ui_story_5051_50510701_32_dialog_content = "Então, bola de cristal, você me trouxe aqui porque sabia que eu estava com fome, certo?",
  ui_story_5051_50510701_33_dialog_content = "Mas é mais urgente encontrar todos! Sem contar que não adianta comer no cristal!",
  ui_story_5051_50510701_34_dialog_content = "Mais uma vez!",
  ui_story_5051_50510701_35_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50510701_36_dialog_content = "Por favor, diga-me onde está a pessoa em mente agora?",
  ui_story_5051_50510701_37_dialog_content = "Abrahadabra!",
  ui_story_5051_50510701_38_dialog_content = "<size=45>Hahahahaha!</size>",
  ui_story_5051_50510701_39_dialog_content = "Q-Quem está aí?! Sua risada é muito alta e você me assustou!",
  ui_story_5051_50510701_40_dialog_content = "Suas habilidades de adivinhação são *soluços* idiotas, garota.",
  ui_story_5051_50510701_41_dialog_content = "Como você ousa chamar minha adivinhação de coxo!",
  ui_story_5051_50510701_42_dialog_content = "Aprendi com minha mãe, e ela era a melhor mestra de adivinhação de todos os tempos!",
  ui_story_5051_50510701_43_dialog_content = "Não me diga que você nunca ouviu falar <color=#FFB400>boaz</color> do Norte!",
  ui_story_5051_50510701_44_dialog_content = "Boras? Isso soa familiar... *soluço*",
  ui_story_5051_50510701_45_dialog_content = "E daí! Coxo ainda é coxo. Você deveria apenas admitir isso!",
  ui_story_5051_50510701_46_dialog_content = "Que rude! Eu vou te mostrar-!",
  ui_story_5051_50510701_47_dialog_content = "*soluço* Você fala alto para alguém que não pode fazer o backup.",
  ui_story_5051_50510701_48_dialog_content = "Que tal vermos qual adivinhação é mais precisa?",
  ui_story_5051_50510701_49_dialog_content = "Você está ligado!",
  ui_story_5051_50510701_50_dialog_content = "Por favor, paguem seu cheque, senhoras.",
  ui_story_5051_50510701_51_dialog_content = "Huh? Uh, eu não tenho dinheiro comigo... *soluço*",
  ui_story_5051_50510701_52_dialog_content = "E você?",
  ui_story_5051_50510701_53_dialog_content = "Meu? Eu não a conheço, por que devo pagar?",
  ui_story_5051_50510701_54_dialog_content = "Se não puder pagar, espere aqui que os guardas o levem.",
  ui_story_5051_50510701_55_dialog_content = "O que? De jeito nenhum, eu tenho coisas importantes para fazer!",
  ui_story_5051_50510701_56_dialog_content = "Você diz algo! Você começou tudo isso!",
  ui_story_5051_50510701_57_dialog_content = "Ufa...",
  ui_story_5051_50510701_58_dialog_content = "Ela cochilou...",
  ui_story_5051_50510701_59_dialog_content = "Pague ou vá com os guardas, você escolhe.",
  ui_story_5051_50510701_60_dialog_content = "Tudo bem... Quanto é?",
  ui_story_5051_50510701_61_dialog_content = "127.938 Nightium.",
  ui_story_5051_50510701_62_dialog_content = "<size=45>Quanto?!</size>",
  ui_story_5051_50510701_63_dialog_content = "Esta senhora absorveu muitas das nossas melhores reservas, e um desconto de férias já está incluído.",
  ui_story_5051_50510701_64_dialog_content = "Maldições... Meu orçamento de viagem... Meu cache...",
  ui_story_5051_50510701_65_dialog_content = "(Mas tudo isso no Cristal da Memória Eterna provavelmente não é real, então eu ainda devo ter meu dinheiro depois que eu sair, certo?)",
  ui_story_5051_50510701_66_dialog_content = "Aqui você vai...",
  ui_story_5051_50510701_67_dialog_content = "Obrigado.",
  ui_story_5051_50510701_68_dialog_content = "Ei, acabei de pagar por você. Agora você não tem mais desculpas.",
  ui_story_5051_50510701_69_dialog_content = "Vou lutar pela honra da minha mãe hoje!",
  ui_story_5051_50510701_70_dialog_content = "Ei, onde ela está...?",
  ui_story_5051_50510701_71_dialog_content = "Aqui... *soluço*",
  ui_story_5051_50510701_72_dialog_content = "Para!",
  ui_story_5051_50510701_73_dialog_content = "Não tente fugir no meio da multidão!",
  ui_story_5051_50510701_74_dialog_content = "Tudo bem, aqui está...",
  ui_story_5051_50510701_75_dialog_content = "Entendi!",
  ui_story_5051_50510701_76_dialog_content = "Não só fui forçado a pagar por você, agora você tentou fugir...",
  ui_story_5051_50510701_77_dialog_content = "Vamos ver para onde você pode correr agora?",
  ui_story_5051_50510701_78_dialog_content = "Por que eu deveria correr? Olha, o que você está olhando está ali.",
  ui_story_5051_50510701_79_dialog_content = "Aquele que estou procurando...?",
  ui_story_5051_50510701_80_dialog_content = "Olha, o desfile está vindo para cá!",
  ui_story_5051_50510701_81_dialog_content = "Vê como o Lorde da Cidade é impressionante?",
  ui_story_5051_50510701_82_dialog_content = "e princesa Carleen e a princesa Veronica também estão com ele!",
  ui_story_5051_50510701_83_dialog_content = "Lady Joshua...!",
  ui_story_5051_50510701_84_dialog_content = "viva a casa Schwartz!",
  ui_story_5051_50510701_85_dialog_content = "Olhe para cima, Veronica, todos estão cumprimentando você.",
  ui_story_5051_50510701_86_dialog_content = "Sim certo.",
  ui_story_5051_50510701_87_dialog_content = "Relaxe, aqui, segure minha mão.",
  ui_story_5051_50510701_88_dialog_content = "(Mia ainda parece bastante nervoso.)",
  ui_story_5051_50510701_89_dialog_content = "(O desfile vai continuar por um tempo. Ela vai aguentar...?)",
  ui_story_5051_50510701_90_dialog_content = "(nunca imaginei Schwartz O Dia da Família seria uma grande celebração naquela época.)",
  ui_story_5051_50510701_91_dialog_content = "(Embora o banquete tenha sido bastante extravagante, ainda não se comparava a esta celebração doze anos atrás.)",
  ui_story_5051_50510701_92_dialog_content = "(O que aconteceu durante os doze anos para mudar isso?)",
  ui_story_5051_50510701_93_dialog_content = "(Além disso, os Eclipsites que encontrei no portão hoje certamente não foram transportados por acidente.)",
  ui_story_5051_50510701_94_dialog_content = "(Alguém estava aproveitando a festividade para contrabandear Eclipsites para Lumopolis.)",
  ui_story_5051_50510701_95_dialog_content = "(Os Lumo Knights podem lidar com isso? Ou será um grande desastre no final?)",
  ui_story_5051_50510701_96_dialog_content = "(Bem, espero que não coloque ninguém em perigo.)",
  ui_story_5051_50510701_97_dialog_content = "(Hmm, por que tenho a sensação de que alguém está me observando?)",
  ui_story_5051_50510701_98_dialog_content = "(Não pode ser, por que me assistir quando estou apenas no passeio?)",
  ui_story_5051_50510701_99_dialog_content = "(E a Sra. Rot me avisou para não vagar e estragar o desfile.)",
  ui_story_5051_50510701_100_dialog_content = "(Pare de se perguntar!)",
  ui_story_5051_50510701_101_dialog_content = "Ei, PlayerName! Mia!",
  ui_story_5051_50510701_102_dialog_content = "Hmm, a multidão está muito barulhenta para eles me ouvirem!",
  ui_story_5051_50510701_103_dialog_content = "Ah - pare de desperdiçar esforços.",
  ui_story_5051_50510701_104_dialog_content = "Mesmo que eles pudessem ouvi-lo, eles não poderiam simplesmente deixar o desfile para você!",
  ui_story_5051_50510701_105_dialog_content = "Acho que sim...",
  ui_story_5051_50510701_106_dialog_content = "Diga, como você sabia que eram eles que eu estava procurando?",
  ui_story_5051_50510701_107_dialog_content = "E como você sabia que eles estariam aqui?",
  ui_story_5051_50510701_108_dialog_content = "Você não me desafiou para um concurso de adivinhação?",
  ui_story_5051_50510701_109_dialog_content = "Acabei de ganhar!",
  ui_story_5051_50510701_110_dialog_content = "...",
  ui_story_5051_50510701_111_dialog_content = "<size=45>Incrível!</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>Por favor, aceite-me como seu pupilo!</size>",
  ui_story_5051_50510701_113_dialog_content = "Uau, não tão alto. Você está me dando dor de cabeça...",
  ui_story_5051_50510701_114_dialog_content = "Eu não aceito alunos. Só estou aqui para uns biscates e para ganhar dinheiro com a bebida.",
  ui_story_5051_50510701_115_dialog_content = "Hoje à noite... amanhã, ou talvez depois disso? De qualquer forma, vou embora assim que tiver o suficiente para beber.",
  ui_story_5051_50510701_116_dialog_content = "Então, por favor, pelo menos me diga seu nome!",
  ui_story_5051_50510701_117_dialog_content = "(Para que eu possa localizá-lo depois de sair deste cristal!)",
  ui_story_5051_50510701_118_dialog_content = "Tudo bem, já que você saltou para a refeição...",
  ui_story_5051_50510701_119_dialog_content = "Meu nome é Boaz.",
  ui_story_5051_50510701_120_dialog_content = "Hã?",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>Mãe</color>?",
  ui_story_5051_50510701_122_dialog_content = "Minha gratidão vai para todas as pessoas de Lumopolis reunidas aqui hoje para celebrar esta ocasião especial.",
  ui_story_5051_50510701_123_dialog_content = "a casa Schwartz é a jóia da coroa da cidade, bem como a fundação.",
  ui_story_5051_50510701_124_dialog_content = "Nós o defendemos com as lâminas afiadas que você forjou para nós.",
  ui_story_5051_50510701_125_dialog_content = "Hoje, estamos aqui para enaltecer as virtudes da Casa Schwartz assim como os dos cidadãos de Lumopolis!",
  ui_story_5051_50510701_126_dialog_content = "Declaro o início de Schwartz Comemoração do Dia da Família!",
  ui_story_5051_50510701_127_dialog_content = "Agora, vamos começar a cerimônia de confronto!",
  ui_story_5051_50510701_128_dialog_content = "Maravilhoso discurso de abertura, meu senhor!",
  ui_story_5051_50510701_129_dialog_content = "...",
  ui_story_5051_50510701_130_dialog_content = "Essa prosperidade que você está vendo agora é a representação da proeza de Lumopolis.",
  ui_story_5051_50510701_131_dialog_content = "casa única Schwartz é apropriado para tal glória.",
  ui_story_5051_50510701_132_dialog_content = "Há relatos da princesa Veronica derrotando os Eclipsitas tentando se infiltrar na cidade hoje cedo.",
  ui_story_5051_50510701_133_dialog_content = "Ela pode ser uma cavaleira estagiária, mas isso já é tão impressionante quanto uma cavaleira oficial.",
  ui_story_5051_50510701_134_dialog_content = "Ouvi dizer que, quando os guardas correram para o local, praticamente não havia mais nada dos Eclipsites.",
  ui_story_5051_50510701_135_dialog_content = "Se bem me lembro, os Kartimas são responsáveis pela segurança do feriado, não é? Eu não posso acreditar...",
  ui_story_5051_50510701_136_dialog_content = "É insignificante e não vale a pena trazer à tona.",
  ui_story_5051_50510701_137_dialog_content = "Acho que Veronica entendeu isso também, por isso ela não buscou elogios de mim.",
  ui_story_5051_50510701_138_dialog_content = "...",
  ui_story_5051_50510701_139_dialog_content = "É muito mais do que insignificante.",
  ui_story_5051_50510701_140_dialog_content = "A história se espalhou pela cidade.",
  ui_story_5051_50510701_141_dialog_content = "\"A princesa Veronica é mais do que parece, resolvendo uma crise sozinha e sem esforço.\"",
  ui_story_5051_50510701_142_dialog_content = "Eu imagino que todo mundo adoraria ver o quão brilhante ela luta.",
  ui_story_5051_50510701_143_dialog_content = "Defender a justiça quando há erros a serem corrigidos é uma virtude louvável.",
  ui_story_5051_50510701_144_dialog_content = "Mas ela não deve desenvolver o hábito de se exibir tão jovem.",
  ui_story_5051_50510701_145_dialog_content = "Entregar-se à fachada não a levará a lugar nenhum.",
  ui_story_5051_50510701_146_dialog_content = "Por favor, não a dispense assim!",
  ui_story_5051_50510701_147_dialog_content = "A princesa Veronica manteve um perfil discreto com quase nenhuma fanfarra.",
  ui_story_5051_50510701_148_dialog_content = "Em comparação, a princesa Carleen tem sido apresentado como um governante pródigo desde a infância.",
  ui_story_5051_50510701_149_dialog_content = "Princesa Carleen continuará a se destacar nos anos seguintes, enquanto o prestígio e a autoridade de ser a mais velha para a Princesa Verônica só irão...",
  ui_story_5051_50510701_150_dialog_content = "O assunto da sucessão não cabe a nós criticar, Duque Troy!",
  ui_story_5051_50510701_151_dialog_content = "O City Lord provou ser perspicaz e valoriza o talento.",
  ui_story_5051_50510701_152_dialog_content = "Deve haver pensamentos suficientes por trás de chamar a princesa da linha de frente.",
  ui_story_5051_50510701_153_dialog_content = "Sim, você está certo, colocando alguém na posição de sucesso! Acredito que a princesa Veronica ficará melhor na cidade.",
  ui_story_5051_50510701_154_dialog_content = "Por favor, perdoe minha insolência, meu senhor.",
  ui_story_5051_50510701_155_dialog_content = "Pai, eu...",
  ui_story_5051_50510701_156_dialog_content = "Vá se arrumar, Verônica.",
  ui_story_5051_50510701_157_dialog_content = "O que, prepare-se?",
  ui_story_5051_50510701_158_dialog_content = "De acordo com a programação, você é o próximo.",
  ui_story_5051_50510701_159_dialog_content = "Não deixe as pessoas esperando.",
  ui_story_5051_50510701_160_dialog_content = "Sim, ok...!",
  ui_story_5051_50510701_161_dialog_content = "Vocês dois estão comigo há anos e parecem saber exatamente como eu penso.",
  ui_story_5051_50510701_162_dialog_content = "Eu tinha planejado salvar Veronica para o final e mostrar o poder da nova geração da House. Schwartz.",
  ui_story_5051_50510701_163_dialog_content = "Eu só não esperava que vocês dois vissem através disso.",
  ui_story_5051_50510701_164_dialog_content = "Foi apenas uma observação casual de minha parte, meu senhor.",
  ui_story_5051_50510701_165_dialog_content = "Estou muito ansioso para o primeiro passeio da princesa Veronica.",
  ui_story_5051_50510701_166_dialog_content = "Você realmente vai fazer isso, Mia?",
  ui_story_5051_50510701_167_dialog_content = "...",
  ui_story_5051_50510701_168_dialog_content = "Eu acredito que esta é uma boa oportunidade para correr.",
  ui_story_5051_50510701_169_dialog_content = "Deveríamos apenas ver Lady Joshua, mas a presença do Lorde da Cidade nos obrigou a vir aqui.",
  ui_story_5051_50510701_X169_dialog_content = "Perdemos a chance de pedir a Lady Joshua que nos ajudasse a encontrar nossos amigos, mas não devemos continuar nos envolvendo mais profundamente.",
  ui_story_5051_50510701_170_dialog_content = "V-Você está certo... é hora de partirmos...",
  ui_story_5051_50510701_171_dialog_content = "A pessoa lá em cima é apenas uma ilusão e não meu pai... Tudo bem recusar... Ele não vai ficar com raiva...",
  ui_story_5051_50510701_X171_dialog_content = "Eu tenho reiterado muitas vezes, Verônica, que você não precisa treinar para o combate, pois você não tem talento nesse domínio.",
  ui_story_5051_50510701_X172_dialog_content = "Por que você tem vergonha de cumprimentar os outros, Veronica? Você tem dez anos e não é mais uma criança.",
  ui_story_5051_50510701_X173_dialog_content = "Junte-se aos Cavaleiros Lumo? Não estou esperando que você se destaque, Verônica, só que você não preocupe sua mãe!",
  ui_story_5051_50510701_172_dialog_content = "Mia...?",
  ui_story_5051_50510701_173_dialog_content = "(Por que é Mia tremendo agora? Ela tem medo de contrariar as ordens do pai?)",
  ui_story_5051_50510701_174_dialog_content = "(Se for esse o caso, só vai deixá-la mais estressada se eu forçá-la a sair.)",
  ui_story_5051_50510701_175_dialog_content = "(E ela só melhorou ultimamente!)",
  ui_story_5051_50510701_176_dialog_content = "Ok...",
  ui_story_5051_50510701_177_dialog_content = "Você quer se juntar ao duelo, Mia?",
  ui_story_5051_50510701_178_dialog_content = "M-Eu? Estou bem de qualquer maneira... Você acha que eu deveria, PlayerName?",
  ui_story_5051_50510701_179_dialog_content = "Se a luta o impede de tremer, você deveria.",
  ui_story_5051_50510701_180_dialog_content = "O que? Oh não, minha condição...",
  ui_story_5051_50510701_181_dialog_content = "Sua mão está tão fria, Mia.",
  ui_story_5051_50510701_182_dialog_content = "Sim, desde que estou neste corpo, tenho sentido muito frio.",
  ui_story_5051_50510701_183_dialog_content = "Sua mão é muito quente, PlayerName.",
  ui_story_5051_50510701_184_dialog_content = "E posso sentir conforto e segurança no calor...",
  ui_story_5051_50510701_185_dialog_content = "Obrigado, não tenho mais medo.",
  ui_story_5051_50510701_X180_dialog_content = "Desculpe ser um fardo para você.",
  ui_story_5051_50510701_X181_dialog_content = "Não, Mia, prometi levar você ao banquete e ver sua família, então sou responsável por cuidar de você.",
  ui_story_5051_50510701_X182_dialog_content = "Se lutar pode aliviar suas preocupações, você deveria fazê-lo!",
  ui_story_5051_50510701_X183_dialog_content = "Todas as consequências são sobre mim!",
  ui_story_5051_50510701_X184_dialog_content = "(Ainda podemos correr atrás da luta, se nada mais!)",
  ui_story_5051_50510701_X185_dialog_content = "Eu sei que você é uma pessoa gentil, PlayerName... Mas por que você está fazendo isso ...",
  ui_story_5051_50510701_X186_dialog_content = "Porque somos amigos.",
  ui_story_5051_50510701_X187_dialog_content = "Que amigos?",
  ui_story_5051_50510701_X188_dialog_content = "É natural que os amigos se apóiem e se façam felizes.",
  ui_story_5051_50510701_X189_dialog_content = "...",
  ui_story_5051_50510701_X190_dialog_content = "Ei, você achou estranho?",
  ui_story_5051_50510701_X191_dialog_content = "Heehee, um pouco...",
  ui_story_5051_50510701_X192_dialog_content = "O que há de estranho nisso?",
  ui_story_5051_50510701_X193_dialog_content = "Porque ninguém me tratou como amigo além de Baba Yaga.",
  ui_story_5051_50510701_X194_dialog_content = "Todos me viam como Vossa Alteza ou Pobre Mia...",
  ui_story_5051_50510701_X195_dialog_content = "Posso realmente entrar na luta, PlayerName?",
  ui_story_5051_50510701_X196_dialog_content = "Sim você pode!",
  ui_story_5051_50510701_X197_dialog_content = "Obrigado, não vou decepcioná-lo.",
  ui_story_5051_50510701_X198_dialog_content = "Oh, o duelo também atrairá a atenção de todos.",
  ui_story_5051_50510701_X199_dialog_content = "Você pode procurar na multidão por meu pai e outros enquanto isso, PlayerName.",
  ui_story_5051_50510701_X200_dialog_content = "Para que possamos encontrar todos, mesmo sem a ajuda da minha mãe.",
  ui_story_5051_50510701_X201_dialog_content = "A julgar por isso, é uma boa decisão lutar...",
  ui_story_5051_50510701_X202_dialog_content = "Isso mesmo, Mia! Acho que meu tolo otimismo está passando para você!",
  ui_story_5051_50510701_X203_dialog_content = "Desta forma, Alteza, o duelo está prestes a começar.",
  ui_story_5051_50510701_X204_dialog_content = "Claro, estou indo.",
  ui_story_5051_50510701_X205_dialog_content = "Vou embora, então...!",
  ui_story_5051_50510701_X206_dialog_content = "Você vai, Mia!",
  ui_story_5051_50510701_186_dialog_content = "Ir, Mia! E se você realmente não pode ganhar...",
  ui_story_5051_50510701_187_dialog_content = "Se acontecer de você ficar aquém, eu vou dar um mergulho.",
  ui_story_5051_50510701_188_dialog_content = "O que? E você é...",
  ui_story_5051_50510701_189_dialog_content = "Saudações, princesa Veronica, sou seu oponente.",
  ui_story_5051_50510701_190_dialog_content = "O Senhor da Cidade me transmitiu instruções para treinar com você, garantindo sua total segurança.",
  ui_story_5051_50510701_191_dialog_content = "Por favor, escolha uma espada cerimonial aqui. Essas armas de treinamento garantirão que você não se machuque acidentalmente.",
  ui_story_5051_50510701_192_dialog_content = "Além disso, como evento de abertura do Schwartz Dia da Família, você não deve cair na derrota.",
  ui_story_5051_50510701_193_dialog_content = "Tudo o que você precisa fazer é trabalhar comigo e me derrubar quando for a hora certa.",
  ui_story_5051_50510701_194_dialog_content = "Trabalhar com você e derrubá-lo quando for a hora certa?",
  ui_story_5051_50510701_195_dialog_content = "Quer dizer que não será uma partida de verdade?",
  ui_story_5051_50510701_196_dialog_content = "Apenas um show como uma peça de teatro?",
  ui_story_5051_50510701_197_dialog_content = "Eu tenho reiterado muitas vezes, Verônica, que você não precisa treinar para o combate, pois você não tem talento nesse domínio.",
  ui_story_5051_50510701_198_dialog_content = "Por que você tem vergonha de cumprimentar os outros, Veronica? Você tem dez anos e não é mais uma criança.",
  ui_story_5051_50510701_199_dialog_content = "Junte-se aos Cavaleiros Lumo? Não estou esperando que você se destaque, Verônica, só que você não preocupe sua mãe!",
  ui_story_5051_50510701_200_dialog_content = "Sair dessa, Mia!",
  ui_story_5051_50510701_201_dialog_content = "PlayerName...",
  ui_story_5051_50510701_202_dialog_content = "Você não precisa do ramo de oliveira de seu pai para se provar, Mia.",
  ui_story_5051_50510701_203_dialog_content = "O City Lord tem grande autoridade, mas isso não significa que ele pode comandar sua vida por você.",
  ui_story_5051_50510701_204_dialog_content = "Não sei que tipo de pensamentos passaram pela sua cabeça...",
  ui_story_5051_50510701_205_dialog_content = "Mas eu sei que você não é a pessoa que era há doze anos!",
  ui_story_5051_50510701_206_dialog_content = "Eu...",
  ui_story_5051_50510701_207_dialog_content = "Tenho certeza que você odeia o fato desta vitória ser predeterminada.",
  ui_story_5051_50510701_208_dialog_content = "Então prove a todos que você pode vencer sozinho.",
  ui_story_5051_50510701_209_dialog_content = "Mas meu adversário...",
  ui_story_5051_50510701_210_dialog_content = "Se ele não está disposto a lutar com você de verdade, faça-o!",
  ui_story_5051_50510701_211_dialog_content = "Fazer ele? Empurrá-lo para ir com tudo? Mas eu consigo isso?",
  ui_story_5051_50510701_212_dialog_content = "Claro! Eles não disseram que a história de você acabar com os Eclipsitas antes mesmo dos cavaleiros aparecerem já estava por toda a cidade?",
  ui_story_5051_50510701_213_dialog_content = "Então, como um guarda mediano pode ser páreo para você!",
  ui_story_5051_50510701_214_dialog_content = "Aham, uh, eu ainda estou aqui...",
  ui_story_5051_50510701_215_dialog_content = "Opa, desculpe...",
  ui_story_5051_50510701_216_dialog_content = "Já que você ouviu tudo isso, acho que vamos deixar claro.",
  ui_story_5051_50510701_217_dialog_content = "Você está pronto, Mia?",
  ui_story_5051_50510701_218_dialog_content = "Você acredita tanto em mim, PlayerName... É a primeira vez que alguém acredita tanto em mim!",
  ui_story_5051_50510701_219_dialog_content = "Tô pronto!",
  ui_story_5051_50510701_220_dialog_content = "Bem então-",
  ui_story_5051_50510701_221_dialog_content = "\"White Night Up High. Valente guerreiro, eu o desafio para um duelo!\"",
  ui_story_5051_50510701_222_dialog_content = "\"Pegue uma espada ou perca sua honra.\"",
  ui_story_5051_50510701_223_dialog_content = "\"Você deve aceitar meu desafio, constitui uma declaração de não arrependimento, mesmo em caso de morte!\"",
  ui_story_5051_50510701_224_dialog_content = "Uh, a morte não está indo longe demais...?",
  ui_story_5051_50510701_225_dialog_content = "Sim, por favor, poupe-me de uma consequência pela qual não posso arcar com a responsabilidade...",
  ui_story_5051_50510701_226_dialog_content = "B-Bem, estou apenas repetindo as falas dos romances...",
  ui_story_5051_50510701_227_dialog_content = "Suspiro... Tudo bem, eu prometo que não vou cair ou me render facilmente.",
  ui_story_5051_50510701_228_dialog_content = "Mas se você não pode me derrotar, ainda vou ceder conforme instruído, já que estou apenas fazendo um trabalho.",
  ui_story_5051_50510701_229_dialog_content = "Isso será ótimo. Obrigado!",
  ui_story_5051_50510701_230_dialog_content = "Então, a espada cerimonial...",
  ui_story_5051_50510701_231_dialog_content = "Você deveria pegar isso, Mia.",
  ui_story_5051_50510701_232_dialog_content = "Certo. Por favor, não se machuque.",
  ui_story_5051_50510701_233_dialog_content = "Eu pensei que Mia pode te machucar!",
  ui_story_5051_50510701_234_dialog_content = "O-o quê?",
  ui_story_5051_50510701_235_dialog_content = "Isso é verdade.",
  ui_story_5051_50510701_236_dialog_content = "Você continua dizendo o nome Mia...",
  ui_story_5051_50510701_237_dialog_content = "Essa garota travessa diante de mim é realmente a dócil princesa Verônica?",
  ui_story_5051_50510701_238_dialog_content = "O-por que, claro! Mia é apenas...",
  ui_story_5051_50510701_239_dialog_content = "Mia é apenas um apelido entre nós!",
  ui_story_5051_50510701_240_dialog_content = "Ah, certo...",
  ui_story_5051_50510701_241_dialog_content = "Já estava na hora. Vejo você em campo em breve, Alteza.",
  ui_story_5051_50510701_242_dialog_content = "OK. Apenas certifique-se de não segurar nada até o fim!",
  ui_story_5051_50510701_243_dialog_content = "Eu devo...",
  ui_story_5051_50510701_244_dialog_content = "(Não fui enviado apenas para fazer um trabalho? Por que sinto que acabei de ver um drama adolescente?)",
  ui_story_5051_50510802_1_dialog_content = "(Eu posso ouvir a multidão rugindo mesmo daqui.)",
  ui_story_5051_50510802_2_dialog_content = "(Acho que a comemoração já começou.)",
  ui_story_5051_50510802_3_dialog_content = "(Hora de roubar o Cristal da Memória Eterna...)",
  ui_story_5051_50510802_4_dialog_content = "Ei, você aí, pare.",
  ui_story_5051_50510802_5_dialog_content = "(Como é que ainda tem um guarda aqui?)",
  ui_story_5051_50510802_6_dialog_content = "Devo pedir-lhe para limpar a sua identidade.",
  ui_story_5051_50510802_7_dialog_content = "Minha identidade? Eu sou Sir Caleb Magnus! Não preciso provar quem sou!",
  ui_story_5051_50510802_8_dialog_content = "Senhor Caleb Magnus...?!",
  ui_story_5051_50510802_9_dialog_content = "Não, ele visitou Lady Joshua há alguns dias.",
  ui_story_5051_50510802_10_dialog_content = "Vocês compartilham alguma semelhança, mas o cabelo dele é muito mais curto e ele tem uma constituição diferente!",
  ui_story_5051_50510802_11_dialog_content = "Renda-se, intruso, ou eu irei...",
  ui_story_5051_50510802_12_dialog_content = "Calma, antes de chamar a atenção de outros soldados!",
  ui_story_5051_50510802_13_dialog_content = "(Esta é a segunda vez que algo inesperado acontece. Que dia difícil.)",
  ui_story_5051_50510802_14_dialog_content = "(Devo pegar o cristal antes de ficar sem Lumina...)",
  ui_story_5051_50510802_15_dialog_content = "Eu comprei bebidas!",
  ui_story_5051_50510802_16_dialog_content = "Ah, aí está você.",
  ui_story_5051_50510802_17_dialog_content = "Ei, por que é para ressaca?",
  ui_story_5051_50510802_18_dialog_content = "Bem, você ainda está engessado e não fala direito comigo...",
  ui_story_5051_50510802_19_dialog_content = "Isso é porque você acabou de me atacar com os olhos marejados e me jogou ranho por toda parte.",
  ui_story_5051_50510802_20_dialog_content = "Eu não me importo, eu quero bebida!",
  ui_story_5051_50510802_21_dialog_content = "Bem bem. Eu comprei isso também. Aqui.",
  ui_story_5051_50510802_22_dialog_content = "*Gulp* Sim, boa bebida! Tem um bom chute nisso!",
  ui_story_5051_50510802_23_dialog_content = "Então, pronto para me contar mais sobre adivinhação?",
  ui_story_5051_50510802_24_dialog_content = "Claro, o que você quer ouvir?",
  ui_story_5051_50510802_25_dialog_content = "Quanto você sabe sobre o feitiço para entrar no Cristal da Memória Eterna?",
  ui_story_5051_50510802_26_dialog_content = "Por que aqueles que entraram não apenas não eram invisíveis, mas se espalharam pelo mundo?",
  ui_story_5051_50510802_27_dialog_content = "Cristal... Memórias Eternas...?",
  ui_story_5051_50510802_28_dialog_content = "Não é algo que você deva saber, garotinha.",
  ui_story_5051_50510802_29_dialog_content = "Quem é você, de verdade?",
  ui_story_5051_50510802_30_dialog_content = "Eu não te disse que eu sou Jakine, sua filha?!",
  ui_story_5051_50510802_31_dialog_content = "Jakine? Você está brincando?",
  ui_story_5051_50510802_32_dialog_content = "É verdade que quase não vou para casa, mas é impossível para Jakine que não conseguia nem andar...",
  ui_story_5051_50510802_33_dialog_content = "Estar tão alto em um piscar de olhos!",
  ui_story_5051_50510802_34_dialog_content = "Sou eu que acho tudo isso uma piada!",
  ui_story_5051_50510802_35_dialog_content = "Mas mãe, você não é uma vidente misteriosa, incrível e transcendente?",
  ui_story_5051_50510802_36_dialog_content = "Por que você é um grande bêbado?",
  ui_story_5051_50510802_37_dialog_content = "Quem você está chamando de grande bêbado?!",
  ui_story_5051_50510802_38_dialog_content = "Chame-me de *soluço* uma mulher tão inescrutável quanto o vento norte - Boaz!",
  ui_story_5051_50510802_39_dialog_content = "O que isso tem a ver com alguma coisa?",
  ui_story_5051_50510802_40_dialog_content = "Eu não deveria te dizer isso, mas você é tudo que eu tenho agora.",
  ui_story_5051_50510802_41_dialog_content = "Eu só vou dizer isso uma vez, então ouça bem!",
  ui_story_5051_50510802_42_dialog_content = "Hã?",
  ui_story_5051_50510802_43_dialog_content = "Minha mãe é Boaz, e esse é você.",
  ui_story_5051_50510802_44_dialog_content = "Você criou o Cristal da Memória Eterna, no qual estamos neste exato momento.",
  ui_story_5051_50510802_45_dialog_content = "Daqui a doze anos, o ativador do Cristal faleceu.",
  ui_story_5051_50510802_46_dialog_content = "Para entrar neste mundo, compus um feitiço de acordo com as notas que você deixou para trás.",
  ui_story_5051_50510802_47_dialog_content = "Mas assim que cheguei aqui, não só não fui camuflado, como também me separei dos meus amigos...",
  ui_story_5051_50510802_48_dialog_content = "Então o que eu faço agora?",
  ui_story_5051_50510802_49_dialog_content = "Entendo...",
  ui_story_5051_50510802_50_dialog_content = "Então você entendeu?",
  ui_story_5051_50510802_51_dialog_content = "Vejo que sua mãe e eu não apenas compartilhamos o mesmo nome, mas ela também plagiou meu trabalho!",
  ui_story_5051_50510802_52_dialog_content = "Meu nome deveria trazer sorte para as pessoas, mas sua mãe... não é bem assim.",
  ui_story_5051_50510802_53_dialog_content = "Por que você-",
  ui_story_5051_50510802_54_dialog_content = "Beba como quiser, seu bêbado!",
  ui_story_5051_50510802_55_dialog_content = "A bebida fez você esquecer tudo, até eu e o papai! Não volte para casa nunca mais!",
  ui_story_5051_50510802_56_dialog_content = "Não fale com veneno, garota.",
  ui_story_5051_50510802_57_dialog_content = "Você disse que fez um feitiço para entrar no cristal das anotações da sua mãe?",
  ui_story_5051_50510802_58_dialog_content = "Quem você está tentando enganar? Mesmo eu não poderia fazer isso!",
  ui_story_5051_50510802_59_dialog_content = "Qualquer um que pudesse seria um gênio sem precedentes!",
  ui_story_5051_50510802_60_dialog_content = "G-Gênio...?",
  ui_story_5051_50510802_61_dialog_content = "Eu sou um gênio sem precedentes?",
  ui_story_5051_50510802_62_dialog_content = "Hahaha, se eu fosse sua mãe ficaria feliz pra caramba!",
  ui_story_5051_50510802_63_dialog_content = "Hehe... Você faria?",
  ui_story_5051_50510802_64_dialog_content = "Espere, esse não é o ponto!",
  ui_story_5051_50510802_65_dialog_content = "Quero saber o que eu faço agora?!",
  ui_story_5051_50510802_66_dialog_content = "Ok, recite o feitiço que você fez para mim.",
  ui_story_5051_50510802_67_dialog_content = "Claro.",
  ui_story_5051_50510802_68_dialog_content = "Ad praeteritum! Ad praeteritum! Ad praeteritum!",
  ui_story_5051_50510802_69_dialog_content = "Revivamos os tempos dourados do passado!",
  ui_story_5051_50510802_70_dialog_content = "Abrahadabra!",
  ui_story_5051_50510802_71_dialog_content = "É isso.",
  ui_story_5051_50510802_72_dialog_content = "Bem, você pronunciou errado.",
  ui_story_5051_50510802_73_dialog_content = "Hã?",
  ui_story_5051_50510802_74_dialog_content = "Não \"Abrahadabra\", é \"Abracadabra\".",
  ui_story_5051_50510802_75_dialog_content = "Qual o problema com você? Tão descuidado!",
  ui_story_5051_50510802_76_dialog_content = "Mas é assim nas notas! Ver!",
  ui_story_5051_50510802_77_dialog_content = "Deixe-me ver... Que caligrafia confusa.",
  ui_story_5051_50510802_78_dialog_content = "Olha aqui, até saiu da margem. Não é à toa que você leu errado.",
  ui_story_5051_50510802_79_dialog_content = "Ela escreveu sob a influência?",
  ui_story_5051_50510802_80_dialog_content = "Você é quem escreveu!",
  ui_story_5051_50510802_81_dialog_content = "Hahahaha!",
  ui_story_5051_50510802_82_dialog_content = "Este feitiço não é de todo ruim!",
  ui_story_5051_50510802_83_dialog_content = "Mas você ainda tem muitos detalhes para observar quando realmente o lança.",
  ui_story_5051_50510802_84_dialog_content = "Você deu as mãos quando entrou?",
  ui_story_5051_50510802_85_dialog_content = "Não...",
  ui_story_5051_50510802_86_dialog_content = "Não é à toa que vocês não foram teletransportados juntos.",
  ui_story_5051_50510802_87_dialog_content = "Eu disse a todos para não mudarem este mundo de forma alguma, no entanto.",
  ui_story_5051_50510802_88_dialog_content = "Então isso não deve ser um problema, certo?",
  ui_story_5051_50510802_89_dialog_content = "Ah, não, não, não...",
  ui_story_5051_50510802_90_dialog_content = "Se você não estivesse camuflado, até sua respiração poderia mudar o mundo.",
  ui_story_5051_50510802_91_dialog_content = "O quê?",
  ui_story_5051_50510802_92_dialog_content = "Se você foi notado aqui, tudo fará ajustes ao seu redor.",
  ui_story_5051_50510802_93_dialog_content = "Até que enfim...",
  ui_story_5051_50510802_94_dialog_content = "Até que enfim o quê?",
  ui_story_5051_50510802_95_dialog_content = "Você se torna parte deste mundo e <color=#FFB400>nunca pode sair</color>.",
  ui_story_5051_50510802_96_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5051_50510802_97_dialog_content = "Não tão alto, não tão alto...",
  ui_story_5051_50510802_98_dialog_content = "Ainda podemos conseguir? Quanto tempo nos resta?",
  ui_story_5051_50510802_99_dialog_content = "Bem, o cristal pode armazenar até cerca de um dia...",
  ui_story_5051_50510802_100_dialog_content = "Então, desde que o dia não termine, você deve ficar bem! Talvez.",
  ui_story_5051_50510802_101_dialog_content = "Ainda podemos conseguir! Tenho que me encontrar com todo mundo e dar o fora daqui!",
  ui_story_5051_50510802_102_dialog_content = "Obrigado, mãe! Tchau, e um dia eu te levo para casa!",
  ui_story_5051_50510802_103_dialog_content = "Ei, espere, onde você está indo?",
  ui_story_5051_50510802_104_dialog_content = "O que você está fazendo? Eu não tenho dinheiro para te comprar bebida agora!",
  ui_story_5051_50510802_105_dialog_content = "Você está tentando encontrá-los por uma manhã inteira, certo?",
  ui_story_5051_50510802_106_dialog_content = "E você não teria encontrado ninguém sem a minha ajuda.",
  ui_story_5051_50510802_107_dialog_content = "Certo.",
  ui_story_5051_50510802_108_dialog_content = "Então, como sua mãe e eu temos o mesmo nome, vou te dar outro empurrãozinho.",
  ui_story_5051_50510802_109_dialog_content = "Vou mostrar-lhe a técnica adequada.",
  ui_story_5051_50510802_110_dialog_content = "Sério?!",
  ui_story_5051_50510802_111_dialog_content = "Sim com certeza. Devemos começar antes que eu mude de ideia.",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>Da...</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>um...</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>Daniel...</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>Verônica... Carleen...</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>Daniel... Verônica... Carleen...</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>Daniel! Verônica! Carleen!</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5051_50510901_9_dialog_content = "O quê?!",
  ui_story_5051_50510901_10_dialog_content = "PlayerName, você está bem?",
  ui_story_5051_50510901_11_dialog_content = "Por que você parece doente de repente?",
  ui_story_5051_50510901_12_dialog_content = "N-Nada. O trovão me fez pular, só isso.",
  ui_story_5051_50510901_13_dialog_content = "Trovão?",
  ui_story_5051_50510901_14_dialog_content = "Eu ouvi um esta manhã, mas este era mais alto do que aquele.",
  ui_story_5051_50510901_15_dialog_content = "Talvez uma tempestade esteja chegando.",
  ui_story_5051_50510901_16_dialog_content = "Como é que eu não ouvi nenhum trovão?",
  ui_story_5051_50510901_17_dialog_content = "O que? Não foi alto o suficiente para você ouvir?",
  ui_story_5051_50510901_18_dialog_content = "Mesmo que tivesse, não teria medo.",
  ui_story_5051_50510901_19_dialog_content = "Ei, haha, Carleen... Princesa Carleen realmente é uma criança corajosa.",
  ui_story_5051_50510901_20_dialog_content = "Eu não sou mais uma criança!",
  ui_story_5051_50510901_21_dialog_content = "...",
  ui_story_5051_50510901_22_dialog_content = "Carleen?",
  ui_story_5051_50510901_23_dialog_content = "(Ela correu de volta para Lady Joshua novamente.)",
  ui_story_5051_50510901_24_dialog_content = "(O olhar em seus olhos permaneceu o mesmo de agora.)",
  ui_story_5051_50510901_25_dialog_content = "É assim princesa Carleen é. Ela pode guardar rancor se você a tratar como uma criança.",
  ui_story_5051_50510901_26_dialog_content = "No entanto, você pode ser a primeira pessoa em quem ela se interessou.",
  ui_story_5051_50510901_27_dialog_content = "Interesse?",
  ui_story_5051_50510901_28_dialog_content = "Você não percebeu que Sua Alteza está observando você há muito tempo?",
  ui_story_5051_50510901_29_dialog_content = "Ela ainda está me avisando...?",
  ui_story_5051_50510901_30_dialog_content = "Uh, Mia... Veronica ainda está lutando contra o soldado, tenho que torcer por ela!",
  ui_story_5051_50510901_31_dialog_content = "Isso é o que eu posso fazer!",
  ui_story_5051_50510901_32_dialog_content = "Ugh... Tosse, tosse.",
  ui_story_5051_50510901_33_dialog_content = "A princesa Veronica ainda não aplicou força total, mas está superando seu oponente.",
  ui_story_5051_50510901_34_dialog_content = "Faz apenas alguns dias e ela fez um progresso impressionante.",
  ui_story_5051_50510901_35_dialog_content = "Estou curioso sobre o que você fez pela princesa Veronica, PlayerName.",
  ui_story_5051_50510901_36_dialog_content = "(Mia quase nunca acreditou em si mesma ao longo do caminho.)",
  ui_story_5051_50510901_37_dialog_content = "(Então ela nunca teve a reputação de uma boa lutadora para ninguém no passado?)",
  ui_story_5051_50510901_38_dialog_content = "O tratamento silencioso? Acho que é mais um daqueles segredos que não devo saber.",
  ui_story_5051_50510901_39_dialog_content = "Na verdade, não é nenhum segredo.",
  ui_story_5051_50510901_40_dialog_content = "Veronica sempre foi formidável. Ela simplesmente nunca percebeu isso no passado.",
  ui_story_5051_50510901_41_dialog_content = "Ah?",
  ui_story_5051_50510901_42_dialog_content = "Essa foi por pouco! A princesa Veronica quase atingiu aquele guarda.",
  ui_story_5051_50510901_43_dialog_content = "Eu posso ver as faíscas das lâminas daqui... Que duelo genuíno!",
  ui_story_5051_50510901_44_dialog_content = "Só vamos torcer por você de agora em diante, princesa Veronica!",
  ui_story_5051_50510901_45_dialog_content = "Viva!",
  ui_story_5051_50510901_46_dialog_content = "A princesa Veronica recebeu aplausos e elogios com suas habilidades de luta com espadas.",
  ui_story_5051_50510901_47_dialog_content = "Falando nisso, você confundiu os aplausos com trovões?",
  ui_story_5051_50510901_48_dialog_content = "Sério?",
  ui_story_5051_50510901_49_dialog_content = "(Ei, espere!)",
  ui_story_5051_50510901_50_dialog_content = "(Por que sinto um arrepio na espinha?)",
  ui_story_5051_50510901_51_dialog_content = "(Alguém está me observando!)",
  ui_story_5051_50510901_52_dialog_content = "(Não é Carleen, o Lorde da Cidade, ou Lady Joshua, ambos obcecados pela luta de sua filha.)",
  ui_story_5051_50510901_53_dialog_content = "(Não me diga que essa vibração é...)",
  ui_story_5051_50510901_54_dialog_content = "Aonde você tá indo, PlayerName?",
  ui_story_5051_50510901_55_dialog_content = "Eu, uh, gostaria de usar o banheiro.",
  ui_story_5051_50510901_56_dialog_content = "Permita-me mostrar o caminho.",
  ui_story_5051_50510901_57_dialog_content = "Eu posso me controlar, obrigado!",
  ui_story_5051_50510901_58_dialog_content = "PlayerName com certeza corre rápido.",
  ui_story_5051_50510901_59_dialog_content = "Este amigo da princesa Veronica certamente é intrigante.",
  ui_story_5051_50510901_60_dialog_content = "A fonte deve estar aqui em algum lugar...",
  ui_story_5051_50510901_61_dialog_content = "Aham.",
  ui_story_5051_50510901_62_dialog_content = "Foi você, Senhor da Cidade!",
  ui_story_5051_50510901_63_dialog_content = "Você é muito perspicaz, PlayerName.",
  ui_story_5051_50510901_64_dialog_content = "Como você chegou aqui?",
  ui_story_5051_50510901_65_dialog_content = "Os jovens adoram comemorações, então pensei em encontrar você aqui.",
  ui_story_5051_50510901_66_dialog_content = "Eu só não imaginei que você se encontraria <color=#FFB400>a versão deste mundo de mim</color> tão cedo.",
  ui_story_5051_50510901_67_dialog_content = "Isso é porque...",
  ui_story_5051_50510901_68_dialog_content = "Eu já deveria saber que estamos envolvidos na história registrada pelo Cristal da Memória Eterna.",
  ui_story_5051_50510901_69_dialog_content = "Somos vistos pelo mundo do qual deveríamos estar ocultos.",
  ui_story_5051_50510901_70_dialog_content = "Isso também está me incomodando... O que deu errado exatamente?",
  ui_story_5051_50510901_71_dialog_content = "Acredito que seja tarde demais para especular sobre isso agora, jovem.",
  ui_story_5051_50510901_72_dialog_content = "Aconteceu. O que é urgente é tentar evitar todos os riscos potenciais na busca de uma solução.",
  ui_story_5051_50510901_73_dialog_content = "Jakine disse para não tentar mudar a história no Cristal ou enfrentar consequências potencialmente graves.",
  ui_story_5051_50510901_74_dialog_content = "Para manter as coisas em ordem neste mundo, devemos nos manter discretos.",
  ui_story_5051_50510901_75_dialog_content = "Mia e eu tive que vir até a cidade para encontrar os outros...",
  ui_story_5051_50510901_76_dialog_content = "...",
  ui_story_5051_50510901_77_dialog_content = "Por que você está carrancudo, Senhor da Cidade?",
  ui_story_5051_50510901_78_dialog_content = "Fez Mia conhecê-los?",
  ui_story_5051_50510901_79_dialog_content = "Eles como em...?",
  ui_story_5051_50510901_80_dialog_content = "Você sabe a quem estou me referindo.",
  ui_story_5051_50510901_81_dialog_content = "Aham. Se você quer dizer Lady Joshua, jovem Carleen, e o Senhor deste mundo Schwartz...",
  ui_story_5051_50510901_82_dialog_content = "Sim, eles se conheceram e aceitaram Mia, mesmo chamando-a de Veronica.",
  ui_story_5051_50510901_83_dialog_content = "A aparência de Mia de fato permaneceu a mesma de antes.",
  ui_story_5051_50510901_84_dialog_content = "Então... Você está admitindo isso?",
  ui_story_5051_50510901_85_dialog_content = "Que Mia é a princesa Veronica, sua filha?",
  ui_story_5051_50510901_86_dialog_content = "Nossa ação perturbou este reino.",
  ui_story_5051_50510901_87_dialog_content = "E você... Por que você colocou em perigo Mia permitindo que ela duelasse com o guarda?",
  ui_story_5051_50510901_88_dialog_content = "Você já considerou as ramificações se ela se machucar?",
  ui_story_5051_50510901_89_dialog_content = "Como filha do Senhor da Cidade de Lumopolis, Mia foi escondido em Umbraton.",
  ui_story_5051_50510901_90_dialog_content = "Seu pai já considerou as ramificações se Mia se machucou em Umbraton?",
  ui_story_5051_50510901_91_dialog_content = "Lembre-se disso, jovem.",
  ui_story_5051_50510901_92_dialog_content = "Se você não conhece todas as facetas de uma história, não julgue prematuramente.",
  ui_story_5051_50510901_93_dialog_content = "Desculpe. Confesso, não faço ideia do que aconteceu entre vocês.",
  ui_story_5051_50510901_94_dialog_content = "Mas acho que você também não percebeu o verdadeiro potencial de Mia.",
  ui_story_5051_50510901_95_dialog_content = "O quê?",
  ui_story_5051_50510901_96_dialog_content = "Boa jogada!",
  ui_story_5051_50510901_97_dialog_content = "Princesa Verônica! Princesa Verônica! Princesa Verônica!",
  ui_story_5051_50510901_98_dialog_content = "Olha, a luta de espadas de Mia ganhou o reconhecimento e aplausos do povo.",
  ui_story_5051_50510901_99_dialog_content = "O Mia Eu costumava saber que nunca poderia lutar.",
  ui_story_5051_50510901_100_dialog_content = "Mas ela se tornou muito formidável em combate agora...",
  ui_story_5051_50510901_101_dialog_content = "Mia queria aproveitar esta oportunidade para mostrar a seu pai que ela poderia realizar mais.",
  ui_story_5051_50510901_102_dialog_content = "No entanto, agora não é o momento certo.",
  ui_story_5051_50510901_103_dialog_content = "Devemos terminar esta partida para Mia rapidamente, PlayerName.",
  ui_story_5051_50510901_104_dialog_content = "Por que? Eu não entendo. Mia está prestes a vencer.",
  ui_story_5051_50510901_105_dialog_content = "Você ainda não acredita nela?",
  ui_story_5051_50510901_106_dialog_content = "Você sabe o que aconteceu na cerimônia naquele ano, PlayerName?",
  ui_story_5051_50510901_107_dialog_content = "Hã?",
  ui_story_5051_50510901_108_dialog_content = "Estou prestes a dar tudo o que tenho agora, princesa Veronica!",
  ui_story_5051_50510901_109_dialog_content = "Entendi. Por favor, não guarde nada.",
  ui_story_5051_50510901_110_dialog_content = "Olá!",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50510901_112_dialog_content = "O que... Você até bloqueou isso?",
  ui_story_5051_50510901_113_dialog_content = "Eu tive sorte.",
  ui_story_5051_50510901_114_dialog_content = "(Ele colocou tanto por trás do golpe que eu mal consegui rechaçá-lo.)",
  ui_story_5051_50510901_115_dialog_content = "(Imagino se PlayerName vi isso?)",
  ui_story_5051_50510901_116_dialog_content = "(Ei, onde está PlayerName?)",
  ui_story_5051_50510901_117_dialog_content = "(Peguei! Mas a pessoa ao lado...)",
  ui_story_5051_50510901_118_dialog_content = "Cuidado, Verônica!",
  ui_story_5051_50510901_119_dialog_content = "Olá!",
  ui_story_5051_50510901_120_dialog_content = "(E agora? Eu acho que não consigo aguentar essa.)",
  ui_story_5051_50510901_121_dialog_content = "(Fugir? N-De jeito nenhum, não quando o pai está olhando...)",
  ui_story_5051_50510901_122_dialog_content = "(Ainda tenho tempo para carregar para um contra-ataque!)",
  ui_story_5051_50510901_123_dialog_content = "ela vai liberar <color=#FFB400>aquela coisa</color>?",
  ui_story_5051_50510901_124_dialog_content = "Verônica...",
  ui_story_5051_50510901_125_dialog_content = "(Não, como posso esquecer o fato de que meu pai não quer que eu invoque Hippoca...)",
  ui_story_5051_50510901_126_dialog_content = "(Mas e a energia que eu já carreguei? Vai acabar machucando a guarda.)",
  ui_story_5051_50510901_127_dialog_content = "(O que fazer, o que fazer?)",
  ui_story_5051_50510901_128_dialog_content = "(O que são aquelas caixas ali? Talvez elas possam suportar a força!)",
  ui_story_5051_50510901_129_dialog_content = "O que está acontecendo, por que Mia correndo para o lado?",
  ui_story_5051_50510901_130_dialog_content = "Mais um segundo e ela teria convocado com sua Lumina!",
  ui_story_5051_50510901_131_dialog_content = "...",
  ui_story_5051_50510901_132_dialog_content = "Nunca invoque esse monstro em público de agora em diante, Veronica.",
  ui_story_5051_50510901_133_dialog_content = "Hippoca não é um monstro.",
  ui_story_5051_50510901_134_dialog_content = "Você nomeou aquela aranha com cabeça de cavalo?",
  ui_story_5051_50510901_135_dialog_content = "Não Carleen tem um cavalo também?",
  ui_story_5051_50510901_136_dialog_content = "Você não tem talento para lutar, Veronica. Não discuta mais sobre isso.",
  ui_story_5051_50510901_137_dialog_content = "Suspirar...",
  ui_story_5051_50510901_138_dialog_content = "Parece que ela ainda se lembra disso.",
  ui_story_5051_50510901_139_dialog_content = "Mia está batendo nessas caixas!",
  ui_story_5051_50510901_140_dialog_content = "Quê?!",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_143_dialog_content = "Eclipsitos? Existem Eclipsitos!",
  ui_story_5051_50510901_144_dialog_content = "Por que tantos Eclipsites estão escondidos nessas caixas de fundo?",
  ui_story_5051_50510901_145_dialog_content = "Correr! Correr!",
  ui_story_5051_50510901_146_dialog_content = "Ah, o que está acontecendo aqui?",
  ui_story_5051_50510901_147_dialog_content = "É por minha causa?",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>Ahhhh!</anim>",
  ui_story_5051_50510901_149_dialog_content = "Eu sabia que não deveria tentar me exibir aqui...",
  ui_story_5051_50510901_150_dialog_content = "Isso é o que aconteceria quando eu tentasse.",
  ui_story_5051_50510901_151_dialog_content = "Nunca acaba bem...",
  ui_story_5051_50510901_152_dialog_content = "Junte-se aos Cavaleiros Lumo? Não estou esperando que você se destaque, Verônica, só que você não preocupe sua mãe!",
  ui_story_5051_50510901_153_dialog_content = "Por favor, não nos siga para a batalha, Alteza. Apenas fique onde é seguro!",
  ui_story_5051_50510901_154_dialog_content = "O que há de errado, Verônica?",
  ui_story_5051_50510901_155_dialog_content = "Não!",
  ui_story_5051_50510901_156_dialog_content = "É tudo por minha causa que...",
  ui_story_5051_50510901_157_dialog_content = "Atenção! Passo para trás!",
  ui_story_5051_50510901_158_dialog_content = "Hã?",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>Grahhhhhh!</anim>",
  ui_story_5051_50510901_160_dialog_content = "A Lâmina do Soberano!",
  ui_story_5051_50510901_161_dialog_content = "Pai? T-O verdadeiro pai?",
  ui_story_5051_50510901_162_dialog_content = "Você tá bem, Mia?",
  ui_story_5051_50510901_163_dialog_content = "Estou bem, PlayerName, só ficou um pouco distraído.",
  ui_story_5051_50510901_164_dialog_content = "Tem certeza que está bem?",
  ui_story_5051_50510901_165_dialog_content = "Estou bem!",
  ui_story_5051_50510901_166_dialog_content = "Muito bem, vamos carregar.",
  ui_story_5051_50510901_167_dialog_content = "É a primeira vez que luta ao meu lado, padre.",
  ui_story_5051_50510901_168_dialog_content = "E...",
  ui_story_5051_50510901_169_dialog_content = "Se você gostaria de convocar Hippoca, vá em frente.",
  ui_story_5051_50510901_170_dialog_content = "Pai?",
  ui_story_5051_50510901_171_dialog_content = "Pronto?",
  ui_story_5051_50510901_172_dialog_content = "Certo.",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>Por outro lado</color>",
  ui_story_5051_50510901_174_dialog_content = "Esses monstros pretos... São Eclipsites?!",
  ui_story_5051_50510901_175_dialog_content = "Eu também posso nos proteger, mãe!",
  ui_story_5051_50510901_176_dialog_content = "Eu acredito que você tem a habilidade, Carleen, mas agora não é o momento, ok?",
  ui_story_5051_50510901_177_dialog_content = "... Tá bem.",
  ui_story_5051_50510901_178_dialog_content = "A Sra. Rot cobrirá a retirada de você e de Carleen, Joshua. Vá agora!",
  ui_story_5051_50510901_179_dialog_content = "Danilo, eu posso...",
  ui_story_5051_50510901_180_dialog_content = "Não se preocupe, Josué.",
  ui_story_5051_50510901_181_dialog_content = "Trarei Veronica de volta sã e salva.",
  ui_story_5051_50510901_182_dialog_content = "Quero ver vocês dois em casa ilesos.",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_184_dialog_content = "Uma barra de soberano!",
  ui_story_5051_50510901_185_dialog_content = "Vejo que essas criaturas se espalharam para cá agora.",
  ui_story_5051_50510901_186_dialog_content = "Bem, você está apenas pedindo por isso.",
  ui_story_5051_50511001_1_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50511001_2_dialog_content = "Por favor, diga-me onde está o Lorde da Cidade em que estou pensando agora?",
  ui_story_5051_50511001_3_dialog_content = "<size=42>Abracadabra!</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_5051_50511001_5_dialog_content = "Uau, esta é a primeira vez que minha bola de cristal respondeu tão intensamente!",
  ui_story_5051_50511001_6_dialog_content = "Acho que nunca disse o encantamento final corretamente antes...",
  ui_story_5051_50511001_7_dialog_content = "Mas estou muito curiosa...",
  ui_story_5051_50511001_8_dialog_content = "Por que \"Abracadabra\" tem que ir sempre no final?",
  ui_story_5051_50511001_9_dialog_content = "\"Abracadabra\" carrega algum significado especial?",
  ui_story_5051_50511001_10_dialog_content = "Huh? Ah, o que é isso de novo...",
  ui_story_5051_50511001_11_dialog_content = "Sim, eu me lembro agora!",
  ui_story_5051_50511001_12_dialog_content = "\"Eu vou te destruir se você não obedecer!\"",
  ui_story_5051_50511001_13_dialog_content = "O quê?!",
  ui_story_5051_50511001_14_dialog_content = "Hahahaha, você parecia tão assustado! Isto é divertido!",
  ui_story_5051_50511001_15_dialog_content = "Você está zombando de mim?",
  ui_story_5051_50511001_16_dialog_content = "<size=30>Eu imaginei a bondade da minha mãe quando eu era criança sozinha?</size>",
  ui_story_5051_50511001_17_dialog_content = "Pare de resmungar! Você vai perder a mensagem se não falar logo com aquela bola de cristal.",
  ui_story_5051_50511001_18_dialog_content = "Ah, quase esqueci!",
  ui_story_5051_50511001_19_dialog_content = "A bola de cristal diz...",
  ui_story_5051_50511001_20_dialog_content = "Senhor Schwartz é onde PlayerName e Mia são?",
  ui_story_5051_50511001_21_dialog_content = "Então eles já se encontraram.",
  ui_story_5051_50511001_22_dialog_content = "Isso significa que perdi todo esse tempo com você!",
  ui_story_5051_50511001_23_dialog_content = "Como isso pode ser uma perda de tempo?",
  ui_story_5051_50511001_24_dialog_content = "Eu te ensinei meus segredos para você!",
  ui_story_5051_50511001_25_dialog_content = "Ah sim, você está certo!",
  ui_story_5051_50511001_26_dialog_content = "E esta é a primeira vez que descubro o paradeiro de alguém com precisão!",
  ui_story_5051_50511001_27_dialog_content = "Mas...",
  ui_story_5051_50511001_28_dialog_content = "Você pode me dizer o que \"Abracadabra\" realmente significa agora?",
  ui_story_5051_50511001_29_dialog_content = "Ai, isso dói, estou com dor de cabeça!",
  ui_story_5051_50511001_30_dialog_content = "Preciso de mais alguns drinques para me acalmar e me lembrar.",
  ui_story_5051_50511001_31_dialog_content = "Puxando isso de novo?",
  ui_story_5051_50511001_32_dialog_content = "Deve ser bom aqui, certo?",
  ui_story_5051_50511001_33_dialog_content = "Devemos avançar um pouco mais para estarmos seguros. Mantem!",
  ui_story_5051_50511001_34_dialog_content = "Ei, por que todo mundo está fugindo da praça?",
  ui_story_5051_50511001_35_dialog_content = "Fique calmo, não tropece e caia!",
  ui_story_5051_50511001_36_dialog_content = "Com licença-",
  ui_story_5051_50511001_37_dialog_content = "O quê?",
  ui_story_5051_50511001_38_dialog_content = "Uau, você parece mais jovem do que eu!",
  ui_story_5051_50511001_39_dialog_content = "Em que posso ajudar?",
  ui_story_5051_50511001_40_dialog_content = "Oh, só estou imaginando o que aconteceu na praça.",
  ui_story_5051_50511001_41_dialog_content = "Nada específico ainda, mas recebi ordens para liderar uma evacuação.",
  ui_story_5051_50511001_42_dialog_content = "Mas as pessoas que procuro ainda estão lá!",
  ui_story_5051_50511001_43_dialog_content = "Espere um minuto, sua aparência...",
  ui_story_5051_50511001_44_dialog_content = "Oh, todo mundo me disse que eu parecia com minha mãe... Uh, quero dizer, Boaz.",
  ui_story_5051_50511001_45_dialog_content = "Cabelo ruivo comprido e olhos verdes... Você é Jakine?",
  ui_story_5051_50511001_46_dialog_content = "Como você sabe meu nome?",
  ui_story_5051_50511001_47_dialog_content = "Espere, espere, espere, não me diga que eu trouxe você aqui por engano também!",
  ui_story_5051_50511001_48_dialog_content = "Perdoe-me, eu não entendo o que você está falando.",
  ui_story_5051_50511001_49_dialog_content = "No entanto, o amigo da princesa Veronica, PlayerName, nos pediu para cuidar de você e outros dois senhores.",
  ui_story_5051_50511001_50_dialog_content = "Sim, estou tentando encontrar PlayerName também!",
  ui_story_5051_50511001_51_dialog_content = "Mas o cara provavelmente ainda está na praça central.",
  ui_story_5051_50511001_52_dialog_content = "Venha comigo agora. Quando tudo se acalmar, eu te levo para PlayerName.",
  ui_story_5051_50511001_53_dialog_content = "Aprecio os pensamentos, mas...",
  ui_story_5051_50511001_54_dialog_content = "Estou ficando sem tempo e tenho que me encontrar com todos!",
  ui_story_5051_50511001_55_dialog_content = "Então você vai cortar caminho através das massas de Eclipsites, com uma senhora devastada a reboque?",
  ui_story_5051_50511001_56_dialog_content = "Eclipsitas?",
  ui_story_5051_50511001_57_dialog_content = "Não, você está perdido!",
  ui_story_5051_50511001_58_dialog_content = "Bem, isso é bastante problemático.",
  ui_story_5051_50511001_59_dialog_content = "Você pode assistir esta senhora, então?",
  ui_story_5051_50511001_60_dialog_content = "Você vai tentar encontrá-los sozinho?",
  ui_story_5051_50511001_61_dialog_content = "Não me julgue pela minha aparência. Eclipsites não são nada para mim.",
  ui_story_5051_50511001_62_dialog_content = "Você acha que pode me deixar para trás depois do que aprendeu comigo?",
  ui_story_5051_50511001_63_dialog_content = "Você acha que eu, Boaz, tenho medo de Eclipsites?",
  ui_story_5051_50511001_64_dialog_content = "Obrigado por me ensinar o encantamento certo.",
  ui_story_5051_50511001_65_dialog_content = "Embora estejamos juntos apenas brevemente, eu realmente aprecio o tempo, e se possível...",
  ui_story_5051_50511001_66_dialog_content = "Eu não gostaria de te deixar agora.",
  ui_story_5051_50511001_67_dialog_content = "Mas eu simplesmente não posso abandonar meus amigos!",
  ui_story_5051_50511001_68_dialog_content = "Eles não estariam nessa confusão se não fosse por mim.",
  ui_story_5051_50511001_69_dialog_content = "Eu não entendo uma única palavra. Apenas me leve com você, você deve!",
  ui_story_5051_50511001_70_dialog_content = "Você não quer que eu te ensine mais? E eu ainda preciso de mais bebida!",
  ui_story_5051_50511001_71_dialog_content = "...",
  ui_story_5051_50511001_72_dialog_content = "Eu respeito você por pensar em seus amigos nesta situação, Jakine.",
  ui_story_5051_50511001_73_dialog_content = "Para ser sincero, gostaria de ajudar na batalha na praça.",
  ui_story_5051_50511001_74_dialog_content = "Se você insistir em ir, eu posso te levar.",
  ui_story_5051_50511001_75_dialog_content = "Sério?",
  ui_story_5051_50511001_76_dialog_content = "Siga-me, vou limpar os Eclipsites para você!",
  ui_story_5051_50511002_1_dialog_content = "Como se parece?",
  ui_story_5051_50511002_2_dialog_content = "A vizinhança deve estar livre de Eclipsites agora.",
  ui_story_5051_50511002_3_dialog_content = "Excelente.",
  ui_story_5051_50511002_4_dialog_content = "Há um atalho ali para sair rapidamente das áreas invadidas.",
  ui_story_5051_50511002_5_dialog_content = "Vocês dois, sigam-me.",
  ui_story_5051_50511002_6_dialog_content = "Estamos saindo agora?",
  ui_story_5051_50511002_7_dialog_content = "Você já lutou o suficiente e precisa descansar.",
  ui_story_5051_50511002_8_dialog_content = "Mas...",
  ui_story_5051_50511002_9_dialog_content = "Sem desculpas.",
  ui_story_5051_50511002_10_dialog_content = "Não podemos desperdiçar muito tempo ou energia aqui.",
  ui_story_5051_50511002_11_dialog_content = "Eu quero ajudar a limpar os Eclipsites...",
  ui_story_5051_50511002_12_dialog_content = "<size=45>Pare de se preocupar com isso, corra e pronto!</size>",
  ui_story_5051_50511002_13_dialog_content = "Hã?",
  ui_story_5051_50511002_14_dialog_content = "Você não tem talento para lutar, Veronica. Não discuta mais sobre isso.",
  ui_story_5051_50511002_15_dialog_content = "Hum...",
  ui_story_5051_50511002_X15_dialog_content = "(Mia tem o mesmo comportamento de antes do duelo.)",
  ui_story_5051_50511002_X16_dialog_content = "(Ela é lembrada de algo desagradável no passado novamente?)",
  ui_story_5051_50511002_16_dialog_content = "O que está em sua mente, Mia?",
  ui_story_5051_50511002_17_dialog_content = "S-Desculpe!",
  ui_story_5051_50511002_18_dialog_content = "É tudo culpa minha...",
  ui_story_5051_50511002_19_dialog_content = "você acabou de enlouquecer Mia com o que você disse, City Lord?",
  ui_story_5051_50511002_20_dialog_content = "Ela melhorou recentemente e isso provavelmente foi demais para ela.",
  ui_story_5051_50511002_21_dialog_content = "...",
  ui_story_5051_50511002_22_dialog_content = "Eu ainda não consigo corresponder às expectativas do meu pai.",
  ui_story_5051_50511002_23_dialog_content = "Eu não mereço ser filho dele, eu não mereço...",
  ui_story_5051_50511002_X21_dialog_content = "Admito que não deveria me meter nos assuntos de sua família.",
  ui_story_5051_50511002_X22_dialog_content = "Mas não é normal uma criança ter tanto medo do próprio pai!",
  ui_story_5051_50511002_24_dialog_content = "porque é Mia tão apavorado com você?",
  ui_story_5051_50511002_25_dialog_content = "Será porque...",
  ui_story_5051_50511002_26_dialog_content = "você abandonou Mia em Umbraton e a negligenciou por todos esses anos?",
  ui_story_5051_50511002_27_dialog_content = "Eu nunca a abandonei nem por um dia!",
  ui_story_5051_50511002_28_dialog_content = "Você não precisa saber os detalhes.",
  ui_story_5051_50511002_X28_dialog_content = "Você não tem o direito de julgar minha família.",
  ui_story_5051_50511002_X29_dialog_content = "Por favor, não seja tão mau para PlayerName, Pai...",
  ui_story_5051_50511002_X30_dialog_content = "Calma, eu sei o que estou fazendo.",
  ui_story_5051_50511002_X31_dialog_content = "Não, você não pode ser tão mau para PlayerName...!",
  ui_story_5051_50511002_X32_dialog_content = "Mia...?",
  ui_story_5051_50511002_X33_dialog_content = "Senhor de Lumopolis, Guardião da Casa... Você tem muitos títulos impressionantes.",
  ui_story_5051_50511002_X34_dialog_content = "Mas todos eles só me sufocam.",
  ui_story_5051_50511002_X35_dialog_content = "Talvez os outros o vejam como majestoso e sublime.",
  ui_story_5051_50511002_X36_dialog_content = "Mas para mim, você sempre é mau e sempre machuca aqueles ao seu redor...",
  ui_story_5051_50511002_X37_dialog_content = "...",
  ui_story_5051_50511002_29_dialog_content = "Admito que não deveria me meter nos assuntos de sua família.",
  ui_story_5051_50511002_30_dialog_content = "Mas eu acho Mia precisa de uma resposta mais do que eu!",
  ui_story_5051_50511002_31_dialog_content = "...",
  ui_story_5051_50511002_32_dialog_content = "A culpa é toda minha, sou um fardo para todos...",
  ui_story_5051_50511002_33_dialog_content = "Escute-me, Mia, Isso definitivamente não é verdade!",
  ui_story_5051_50511002_34_dialog_content = "Você não precisa me consolar. Eu sou um azar que põe todos em perigo.",
  ui_story_5051_50511002_35_dialog_content = "Se eu não tivesse quebrado aquelas caixas, os Eclipsites não teriam saído...",
  ui_story_5051_50511002_36_dialog_content = "Não, os conspiradores os esconderam lá dentro, não tem nada a ver com você!",
  ui_story_5051_50511002_37_dialog_content = "Pelo contrário, você tem ajudado, Mia!",
  ui_story_5051_50511002_38_dialog_content = "Eu tenho ajudado?",
  ui_story_5051_50511002_39_dialog_content = "Foi você quem me salvou dos Eclipsites fora da cidade.",
  ui_story_5051_50511002_40_dialog_content = "Também foi você quem afastou os Eclipsitas que tentavam se infiltrar na cidade pelo portão.",
  ui_story_5051_50511002_41_dialog_content = "E agora mesmo, você salvou muitas pessoas inocentes desses monstros.",
  ui_story_5051_50511002_42_dialog_content = "Isso tudo não prova o quão capaz você é, Mia?",
  ui_story_5051_50511002_43_dialog_content = "São apenas coincidências... Tive sorte.",
  ui_story_5051_50511002_44_dialog_content = "Mia... O que posso dizer para você acreditar em mim?",
  ui_story_5051_50511002_45_dialog_content = "Você é muito mais sábio do que eu, Senhor da Cidade.",
  ui_story_5051_50511002_46_dialog_content = "Então você deve ter mais a dizer para Mia, certo?",
  ui_story_5051_50511002_47_dialog_content = "...",
  ui_story_5051_50511002_X38_dialog_content = "I-Isso é o que eu realmente penso.",
  ui_story_5051_50511002_X39_dialog_content = "Se isso te deixa com raiva, venha para mim, não meu amigo...!",
  ui_story_5051_50511002_48_dialog_content = "Hum...",
  ui_story_5051_50511002_49_dialog_content = "Você está assustado?",
  ui_story_5051_50511002_50_dialog_content = "Eu... não vou dizer que estou com medo.",
  ui_story_5051_50511002_51_dialog_content = "Como seu filho mais velho, devo fazer o possível para não decepcioná-lo.",
  ui_story_5051_50511002_52_dialog_content = "Seja a música e a arte que amo, ou a experiência política e de luta que me falta...",
  ui_story_5051_50511002_53_dialog_content = "Devo me destacar em tudo.",
  ui_story_5051_50511002_54_dialog_content = "Você se destacou o suficiente, meu filho.",
  ui_story_5051_50511002_55_dialog_content = "Mas ainda não consegui tirar nenhum peso de seus ombros.",
  ui_story_5051_50511002_56_dialog_content = "Eu me lembro agora, eu me lembro de tudo agora.",
  ui_story_5051_50511002_57_dialog_content = "Certa vez, reuni coragem para me juntar aos cavaleiros, mas fui rapidamente ferido por Eclipsites.",
  ui_story_5051_50511002_58_dialog_content = "Foi mamãe quem me salvou então, certo?",
  ui_story_5051_50511002_59_dialog_content = "Eu não consegui nada além de criar mais problemas.",
  ui_story_5051_50511002_60_dialog_content = "E não foi isso que acabei de fazer?",
  ui_story_5051_50511002_61_dialog_content = "Caso contrário, você não ficaria com raiva de mim e quereria que eu fosse embora.",
  ui_story_5051_50511002_X61_dialog_content = "Você está com raiva porque eu fui completamente inútil, é isso...?",
  ui_story_5051_50511002_62_dialog_content = "Essa não foi minha intenção, Mia.",
  ui_story_5051_50511002_63_dialog_content = "você vai me enviar <color=#FFB400>em algum lugar longe</color> de novo?",
  ui_story_5051_50511002_64_dialog_content = "!!!",
  ui_story_5051_50511002_65_dialog_content = "Mandar você anonimamente para Umbraton para tratamento foi uma escolha que tive que fazer.",
  ui_story_5051_50511002_66_dialog_content = "Mas admito, eu era muito jovem naquela época.",
  ui_story_5051_50511002_67_dialog_content = "Se eu pudesse refazer, com certeza encontraria uma maneira melhor de lidar com tudo.",
  ui_story_5051_50511002_68_dialog_content = "É inútil dizer isso agora, mas não importa o que... essa foi uma das piores decisões que já tomei.",
  ui_story_5051_50511002_69_dialog_content = "Sinto muito pelas dificuldades que você teve que suportar por todos esses anos...",
  ui_story_5051_50511002_70_dialog_content = "Pai…",
  ui_story_5051_50511002_71_dialog_content = "Eu senti falta de mamãe e Carleen tanto... E você também.",
  ui_story_5051_50511002_72_dialog_content = "Eu sei, meu filho.",
  ui_story_5051_50511002_73_dialog_content = "Enquanto estiver em Umbraton, Istvan me informou sobre você constantemente.",
  ui_story_5051_50511002_74_dialog_content = "Eu sabia que você estava melhorando e talvez um dia eu explique tudo para você.",
  ui_story_5051_50511002_75_dialog_content = "Eu só nunca imaginei que chegaria a isso...",
  ui_story_5051_50511002_76_dialog_content = "Prometo que contarei a verdade depois que sairmos. Mas agora nossa prioridade é sair daqui.",
  ui_story_5051_50511002_77_dialog_content = "eu... ah...",
  ui_story_5051_50511002_79_dialog_content = "M-Mas se formos embora, isso não significa que nunca mais verei mamãe?",
  ui_story_5051_50511002_80_dialog_content = "...",
  ui_story_5051_50511002_81_dialog_content = "Foi por minha causa?",
  ui_story_5051_50511002_82_dialog_content = "Ela faleceu por minha causa?",
  ui_story_5051_50511002_83_dialog_content = "Falaremos sobre isso mais tarde, criança.",
  ui_story_5051_50511002_84_dialog_content = "Devemos sair daqui primeiro.",
  ui_story_5051_50511002_85_dialog_content = "Saia daqui?",
  ui_story_5051_50511002_86_dialog_content = "Não quero que mais nada de errado aconteça com você, ok?",
  ui_story_5051_50511002_87_dialog_content = "Ok...",
  ui_story_5051_50511002_88_dialog_content = "Consegues levantar-te?",
  ui_story_5051_50511002_89_dialog_content = "Me dê sua mão e vamos juntos.",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5051_50511002_91_dialog_content = "O quê?",
  ui_story_5051_50511002_92_dialog_content = "O que está acontecendo aqui?",
  ui_story_5051_50511002_93_dialog_content = "Pai!",
  ui_story_5051_50511002_94_dialog_content = "Fique longe dele, Verônica.",
  ui_story_5051_50511002_95_dialog_content = "Não se aproxime desse bandido que está te sequestrando!",
  ui_story_5051_50511002_96_dialog_content = "...",
  ui_story_5051_50511002_97_dialog_content = "(O jovem Schwartz não reconheceu que ele está de frente para si mesmo!)",
  ui_story_5051_50511002_98_dialog_content = "(compreensível, no entanto...)",
  ui_story_5051_50511002_99_dialog_content = "(Se eu não soubesse a verdade, não acreditaria que esses dois são a mesma pessoa.)",
  ui_story_5051_50511002_100_dialog_content = "Se você tem a ousadia de sequestrar uma filha de Schwartz...",
  ui_story_5051_50511002_101_dialog_content = "Por que você não tem coragem de lutar comigo agora!",
  ui_story_5051_50511002_102_dialog_content = "Não quero causar nenhum confronto desnecessário.",
  ui_story_5051_50511002_103_dialog_content = "Confronto desnecessário?",
  ui_story_5051_50511002_104_dialog_content = "Não acredito que tenha te conhecido.",
  ui_story_5051_50511002_105_dialog_content = "Você é um Tróia? Não, você não parece um.",
  ui_story_5051_50511002_106_dialog_content = "Você deve ser um Kartima, então?",
  ui_story_5051_50511002_107_dialog_content = "Nenhum. Eu sou da Verônica...",
  ui_story_5051_50511002_108_dialog_content = "Amigo.",
  ui_story_5051_50511002_109_dialog_content = "Amigo?",
  ui_story_5051_50511002_110_dialog_content = "Amigo de um amigo, mas ainda assim um amigo.",
  ui_story_5051_50511002_111_dialog_content = "Interessante, embora eu só tenha ouvido falar de \"O inimigo do meu inimigo é meu amigo\".",
  ui_story_5051_50511002_112_dialog_content = "Bem, agora você sabe.",
  ui_story_5051_50511002_113_dialog_content = "Seu tom sugere que você não quer ser meu amigo.",
  ui_story_5051_50511002_114_dialog_content = "Ele realmente é... um amigo meu de Umbraton, padre.",
  ui_story_5051_50511002_115_dialog_content = "Ele também me ajudou há pouco.",
  ui_story_5051_50511002_116_dialog_content = "Momento peculiar para ele aparecer ao lado dos Eclipsitas.",
  ui_story_5051_50511002_117_dialog_content = "Talvez coincidência demais.",
  ui_story_5051_50511002_118_dialog_content = "Deixe sua mãe rastrear de quem você é amiga de agora em diante, Verônica.",
  ui_story_5051_50511002_119_dialog_content = "...",
  ui_story_5051_50511002_120_dialog_content = "(Aham, Schwartz deve estar furioso com seu eu mais jovem agora.)",
  ui_story_5051_50511002_121_dialog_content = "(Mas isso simplesmente não pode continuar...)",
  ui_story_5051_50511002_122_dialog_content = "(E não podemos simplesmente dizer aos jovens Schwartz, \"Este é você uma dúzia de anos no futuro.\")",
  ui_story_5051_50511002_123_dialog_content = "(Apenas uma carta que posso jogar agora...)",
  ui_story_5051_50511002_124_dialog_content = "Na verdade...",
  ui_story_5051_50511002_125_dialog_content = "O quê?",
  ui_story_5051_50511002_126_dialog_content = "Por favor, perdoe-me, Senhor da Cidade.",
  ui_story_5051_50511002_127_dialog_content = "Na verdade, ele é... meu pai, em, Soroz.",
  ui_story_5051_50511002_128_dialog_content = "Não o informei que viria para Lumopolis com a princesa Veronica.",
  ui_story_5051_50511002_129_dialog_content = "É por isso que ele pediu a outros que viessem me encontrar aqui.",
  ui_story_5051_50511002_130_dialog_content = "Eu não esperava encontrar Eclipsites assim que nos conhecemos.",
  ui_story_5051_50511002_131_dialog_content = "Y-Sim!",
  ui_story_5051_50511002_132_dialog_content = "Sim. Veja, um confronto desnecessário como eu disse.",
  ui_story_5051_50511002_133_dialog_content = "Embora eu deva agradecer a você e sua família por cuidar PlayerName.",
  ui_story_5051_50511002_134_dialog_content = "Se for esse o caso, realmente entendi mal.",
  ui_story_5051_50511002_135_dialog_content = "No entanto...",
  ui_story_5051_50511002_136_dialog_content = "Você ainda não acredita em mim?",
  ui_story_5051_50511002_137_dialog_content = "PlayerName parece apenas um pouco mais velha que Veronica.",
  ui_story_5051_50511002_138_dialog_content = "Eu teria adivinhado que você é PlayerNameavô de.",
  ui_story_5051_50511002_139_dialog_content = "Ha ha ha, jovem.",
  ui_story_5051_50511002_140_dialog_content = "Obrigado por me alertar sobre como eu era desagradável na minha juventude.",
  ui_story_5051_50511002_141_dialog_content = "Eu posso imaginar isso.",
  ui_story_5051_50511002_142_dialog_content = "Felizmente, isso não me incomoda mais na minha idade.",
  ui_story_5051_50511002_143_dialog_content = "Se eu estiver correto, você deve ter negócios mais importantes para cuidar?",
  ui_story_5051_50511002_144_dialog_content = "Em qual ponto você quer chegar?",
  ui_story_5051_50511002_145_dialog_content = "Posso ser velho, mas sei uma ou duas coisas sobre como lidar com os Eclipsites.",
  ui_story_5051_50511002_146_dialog_content = "Estou disposto a levar Veronica e PlayerName para segurança.",
  ui_story_5051_50511002_147_dialog_content = "Eu aprecio o pensamento.",
  ui_story_5051_50511002_148_dialog_content = "No entanto, Veronica é minha filha.",
  ui_story_5051_50511002_149_dialog_content = "Eu sou totalmente capaz de protegê-la sozinho.",
  ui_story_5051_50511002_150_dialog_content = "Ninguém mais precisa intervir.",
  ui_story_5051_50511002_151_dialog_content = "...",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>Pai</color>...",
  ui_story_5051_50511002_153_dialog_content = "(Mia...)",
  ui_story_5051_50511002_154_dialog_content = "(Qual <color=#FFB400>pai</color> ela está respondendo agora?)",
  ui_story_5051_50511101_1_dialog_content = "A bola de cristal está realmente brilhando...",
  ui_story_5051_50511101_2_dialog_content = "PlayerName e outros devem estar por perto!",
  ui_story_5051_50511101_3_dialog_content = "Está tão quieto.",
  ui_story_5051_50511101_4_dialog_content = "Sim, isso não é tão animado quanto no nosso caminho para cá.",
  ui_story_5051_50511101_5_dialog_content = "Acho que devíamos ir onde está mais cheio.",
  ui_story_5051_50511101_6_dialog_content = "Está muito morto por aqui.",
  ui_story_5051_50511101_7_dialog_content = "Eu posso dizer que não há ninguém vendendo boa bebida.",
  ui_story_5051_50511101_8_dialog_content = "Ahem, não estamos aqui para fazer compras.",
  ui_story_5051_50511101_9_dialog_content = "Você acha que aprendeu o suficiente para me enganar agora?",
  ui_story_5051_50511101_10_dialog_content = "Aquelas pessoas em trajes formais pretos não tentaram apenas obter o nosso negócio?",
  ui_story_5051_50511101_11_dialog_content = "Pessoas em preto formals? Você está falando sobre os Eclipsitos?",
  ui_story_5051_50511101_12_dialog_content = "Você está tão bêbado que nem percebeu que eram Eclipsites?",
  ui_story_5051_50511101_13_dialog_content = "<size=30>Não é à toa que você nem percebeu que era eu...</size>",
  ui_story_5051_50511101_14_dialog_content = "Eu verifiquei a área e todos os Eclipsites devem estar mortos agora.",
  ui_story_5051_50511101_15_dialog_content = "Deve haver ampla segurança onde o Senhor da Cidade e a Princesa estão.",
  ui_story_5051_50511101_16_dialog_content = "Portanto, seus amigos devem estar seguros com eles.",
  ui_story_5051_50511101_17_dialog_content = "Muito obrigado.",
  ui_story_5051_50511101_18_dialog_content = "Se você não matasse aqueles Eclipsites em um instante, eu não saberia como poderia chegar tão longe.",
  ui_story_5051_50511101_19_dialog_content = "Você é o cavaleiro mais confiável que já conheci em Lumopolis!",
  ui_story_5051_50511101_20_dialog_content = "Eu posso até dizer sem a bola de cristal...",
  ui_story_5051_50511101_21_dialog_content = "Você se tornará uma figura proeminente eventualmente!",
  ui_story_5051_50511101_22_dialog_content = "Obrigado pelo comentário.",
  ui_story_5051_50511101_23_dialog_content = "Eu sou apenas um estagiário agora.",
  ui_story_5051_50511101_24_dialog_content = "Você acreditar em mim é o maior incentivo para mim.",
  ui_story_5051_50511101_25_dialog_content = "Está tudo bem, você ainda é jovem! Você terá a chance de...",
  ui_story_5051_50511101_26_dialog_content = "Ei, espere!",
  ui_story_5051_50511101_27_dialog_content = "(O que acontece aqui é o que o Cristal registrou doze anos atrás.)",
  ui_story_5051_50511101_28_dialog_content = "(Então isso significa que este cavaleiro é realmente muito mais velho do que eu agora!)",
  ui_story_5051_50511101_29_dialog_content = "Aham. Então, quantos anos você tem agora?",
  ui_story_5051_50511101_30_dialog_content = "Você foi bastante insistente quando quis que eu fosse seu mestre.",
  ui_story_5051_50511101_31_dialog_content = "Por que você está tão desajeitado e indeciso agora?",
  ui_story_5051_50511101_32_dialog_content = "Apenas diga se estiver interessado!",
  ui_story_5051_50511101_33_dialog_content = "O que? N-Não, não é isso que eu quero dizer!",
  ui_story_5051_50511101_34_dialog_content = "Hã?",
  ui_story_5051_50511101_35_dialog_content = "Claro, isso não significa que eu não goste de você!",
  ui_story_5051_50511101_36_dialog_content = "É só... deixa pra lá, eu também não sei por onde começar.",
  ui_story_5051_50511101_37_dialog_content = "Mas se você ainda for um cavaleiro em Lumopolis daqui a doze anos...",
  ui_story_5051_50511101_38_dialog_content = "Nos encontraremos novamente com certeza!",
  ui_story_5051_50511101_39_dialog_content = "Você quer dizer aquele clichê \"Voltarei tantos anos depois, então espere por mim\"?",
  ui_story_5051_50511101_40_dialog_content = "Fiz isso quando tinha oito anos. Que tal algo mais fresco?",
  ui_story_5051_50511101_41_dialog_content = "Ué, haha...",
  ui_story_5051_50511101_42_dialog_content = "Esta senhora bêbada não sabe o que está dizendo, então não dê atenção a ela!",
  ui_story_5051_50511101_43_dialog_content = "Eu vou te segurar nisso!",
  ui_story_5051_50511101_44_dialog_content = "Hã?",
  ui_story_5051_50511101_45_dialog_content = "Meus parentes não viam muito em mim por causa de diferentes preocupações.",
  ui_story_5051_50511101_46_dialog_content = "Mas eu não estaria aqui hoje sem que eles se revezassem para me criar.",
  ui_story_5051_50511101_47_dialog_content = "Espero poder provar meu valor para eles um dia e reconstruir a glória da Casa Kartima.",
  ui_story_5051_50511101_48_dialog_content = "Daqui a doze anos, você disse...",
  ui_story_5051_50511101_49_dialog_content = "Você me verá como o cavaleiro mais poderoso liderando um exército quando voltar!",
  ui_story_5051_50511101_50_dialog_content = "Uau, isso soa muito impressionante!",
  ui_story_5051_50511101_51_dialog_content = "É uma promessa então. Vou te procurar nos Lumo Knights!",
  ui_story_5051_50511101_52_dialog_content = "Mas ainda não sei seu nome...",
  ui_story_5051_50511101_53_dialog_content = "Sharona Cartima.",
  ui_story_5051_50511101_54_dialog_content = "Sharona? Que nome adorável.",
  ui_story_5051_50511101_55_dialog_content = "Segure...",
  ui_story_5051_50511101_56_dialog_content = "Então você é mesmo uma garota?!",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>Outro lado da rua</color>",
  ui_story_5051_50511101_58_dialog_content = "Não seja imprudente, jovem.",
  ui_story_5051_50511101_59_dialog_content = "Entendo sua situação, assim como seus sentimentos.",
  ui_story_5051_50511101_60_dialog_content = "Levei muito tempo para finalmente descobrir \"sutileza sobre poder\".",
  ui_story_5051_50511101_61_dialog_content = "Espero que você considere manter sua família fora de outros assuntos.",
  ui_story_5051_50511101_62_dialog_content = "Se eu tiver uma chance, devo apresentá-lo ao Conselho dos Anciões.",
  ui_story_5051_50511101_63_dialog_content = "Vocês teriam muito em comum para discutir e todos vocês adoram orientar os jovens.",
  ui_story_5051_50511101_64_dialog_content = "O que você achou?",
  ui_story_5051_50511101_65_dialog_content = "vejo que esqueci...",
  ui_story_5051_50511101_66_dialog_content = "Que eu achava a pregação hipócrita muito irritante quando eu era jovem.",
  ui_story_5051_50511101_67_dialog_content = "<size=45>Uau!</size>",
  ui_story_5051_50511101_68_dialog_content = "O quê?",
  ui_story_5051_50511101_69_dialog_content = "Finalmente encontrei todos vocês! Todos estão bem?",
  ui_story_5051_50511101_70_dialog_content = "Tudo está ligado e parece animado... Acho que não há nada de errado. Maravilhoso!",
  ui_story_5051_50511101_71_dialog_content = "Jakine...",
  ui_story_5051_50511101_72_dialog_content = "Não se preocupe comigo, PlayerName. Veja, eu ainda estou bem e inteiro!",
  ui_story_5051_50511101_73_dialog_content = "Então, não vamos ficar por aqui.",
  ui_story_5051_50511101_74_dialog_content = "Ahem, devido a certas razões especiais...",
  ui_story_5051_50511101_75_dialog_content = "Devemos sair daqui HOJE!",
  ui_story_5051_50511101_76_dialog_content = "Shh...",
  ui_story_5051_50511101_77_dialog_content = "problemas, PlayerName?",
  ui_story_5051_50511101_78_dialog_content = "Oh, você quer saber quem é a senhora bêbada comigo, certo?",
  ui_story_5051_50511101_79_dialog_content = "É um pouco complicado, mas certamente posso apresentar o cavaleiro que nos ajudou!",
  ui_story_5051_50511101_80_dialog_content = "Ei, onde ela está?",
  ui_story_5051_50511101_81_dialog_content = "Ela acabou de sair depois de ver que encontrei meus amigos?",
  ui_story_5051_50511101_82_dialog_content = "Vamos lá, ninguém em Lumopolis pode dizer adeus como pessoas normais?",
  ui_story_5051_50511101_83_dialog_content = "Ei, é ele quem você está procurando, garota?",
  ui_story_5051_50511101_84_dialog_content = "Como é que ele parece familiar para mim?",
  ui_story_5051_50511101_85_dialog_content = "Boaz? Você não partiu para Northland ontem à noite como programado?",
  ui_story_5051_50511101_86_dialog_content = "Eu não venho a Lumopolis com frequência *soluço*, então pensei em relaxar um pouco.",
  ui_story_5051_50511101_87_dialog_content = "Ah, eu me lembro agora. De ontem...",
  ui_story_5051_50511101_88_dialog_content = "Você é aquele cara do City Lord!",
  ui_story_5051_50511101_89_dialog_content = "(O quê? Este é o Senhor da Cidade?)",
  ui_story_5051_50511101_90_dialog_content = "(Não admira PlayerName estava piscando para mim...)",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName, venha aqui!</size>",
  ui_story_5051_50511101_92_dialog_content = "Uau, vá com calma...",
  ui_story_5051_50511101_93_dialog_content = "Diga, o que está acontecendo com tudo isso?",
  ui_story_5051_50511101_94_dialog_content = "É isso que venho tentando resolver, mas ficou mais complicado agora que você apareceu também...",
  ui_story_5051_50511101_95_dialog_content = "Como algo pode ser complicado? Provavelmente está tudo na sua cabeça.",
  ui_story_5051_50511101_96_dialog_content = "De qualquer forma, o City Lord notou o City Lord e o confundiu com um sequestrador...",
  ui_story_5051_50511101_97_dialog_content = "Por que me sinto ainda mais perdido com isso?",
  ui_story_5051_50511101_98_dialog_content = "Por isso eu disse que é muito complicado...",
  ui_story_5051_50511101_99_dialog_content = "O problema é como vamos diferenciar um City Lord do outro?",
  ui_story_5051_50511101_100_dialog_content = "Acabei de dizer a eles que o City Lord que veio aqui conosco é meu pai, Soroz...",
  ui_story_5051_50511101_101_dialog_content = "Soroz? Não é esse o nome do seu Colosso, PlayerName?",
  ui_story_5051_50511101_102_dialog_content = "Eu estava pressionando por um nome na época...",
  ui_story_5051_50511101_103_dialog_content = "um é velho Schwartz, o outro é jovem Schwartz. Não seria mais fácil?",
  ui_story_5051_50511101_104_dialog_content = "Bem, isso provavelmente é falta de educação com o Lorde da Cidade, mas por uma questão de conveniência...",
  ui_story_5051_50511101_105_dialog_content = "Então, o velho Schwartz tentei pegar Mia longe, só para os jovens Schwartz confundi-lo com um sequestrador.",
  ui_story_5051_50511101_106_dialog_content = "Agora estamos tentando sair do aperto!",
  ui_story_5051_50511101_107_dialog_content = "Ah, entendi agora, já que você colocou dessa forma!",
  ui_story_5051_50511101_108_dialog_content = "Deixa comigo!",
  ui_story_5051_50511101_109_dialog_content = "Estou bem, não estou... perdido de jeito nenhum!",
  ui_story_5051_50511101_110_dialog_content = "Tudo bem, importa-se de me dizer quem é a jovem então?",
  ui_story_5051_50511101_111_dialog_content = "Eu posso fazer isso sozinho muito bem! Eu, aluno de Boaz!",
  ui_story_5051_50511101_112_dialog_content = "Eu não sabia que Sua Majestade enviou dois enviados desta vez.",
  ui_story_5051_50511101_113_dialog_content = "Claro que o City Lord não saberia, já que só há um enviado.",
  ui_story_5051_50511101_114_dialog_content = "Sou apenas um seguidor! Embora os seguidores também tenham trabalhos a fazer!",
  ui_story_5051_50511101_115_dialog_content = "Meu trabalho é diferente do de Boaz, então não pude conhecer você e sua dama.",
  ui_story_5051_50511101_116_dialog_content = "Oh? Qual é a sua missão?",
  ui_story_5051_50511101_117_dialog_content = "Convidar PlayerName para Northland para a festa de Sua Majestade.",
  ui_story_5051_50511101_118_dialog_content = "O quê?!",
  ui_story_5051_50511101_119_dialog_content = "Parece PlayerName não está ciente disso.",
  ui_story_5051_50511101_120_dialog_content = "Claro que não. Acabei de rastrear o sujeito!",
  ui_story_5051_50511101_121_dialog_content = "Então, PlayerName, você gostaria de ir?",
  ui_story_5051_50511101_122_dialog_content = "<size=30>*tosse* Diga sim! *tosse*</size>",
  ui_story_5051_50511101_123_dialog_content = "Huh? Oh...",
  ui_story_5051_50511101_124_dialog_content = "Certamente não vou recusar um convite da Rainha!",
  ui_story_5051_50511101_125_dialog_content = "Isso está certo? Isso é ótimo!",
  ui_story_5051_50511101_126_dialog_content = "Minha mestra fez o trabalho dela e eu fiz o meu.",
  ui_story_5051_50511101_127_dialog_content = "Todos nós podemos voltar para Northland com alegria agora!",
  ui_story_5051_50511101_128_dialog_content = "(Jakine é um gênio!)",
  ui_story_5051_50511101_129_dialog_content = "(Jovem Schwartz tem que nos deixar ir agora.)",
  ui_story_5051_50511101_130_dialog_content = "...",
  ui_story_5051_50511101_131_dialog_content = "(Mas por que o velho Schwartz ainda tensa?)",
  ui_story_5051_50511101_132_dialog_content = "(Fez Jakine e eu subestimo grosseiramente a situação?)",
  ui_story_5051_50511101_133_dialog_content = "Entendi.",
  ui_story_5051_50511101_134_dialog_content = "(Eu estava vendo coisas ou o jovem Schwartz só ri?)",
  ui_story_5051_50511101_135_dialog_content = "Tenho o maior respeito pela Rainha do Norte. Qualquer convidado dela é um convidado meu.",
  ui_story_5051_50511101_136_dialog_content = "Lamento muito que você veja Lumopolis em tamanho caos.",
  ui_story_5051_50511101_137_dialog_content = "Mas prometo que não vai durar muito.",
  ui_story_5051_50511101_138_dialog_content = "Até lá, peço que me siga.",
  ui_story_5051_50511101_139_dialog_content = "Vou garantir a segurança de toda a sua festa!",
  ui_story_5051_50511101_140_dialog_content = "<size=30>A atitude dele é totalmente diferente...</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>Você não exploraria quaisquer peões grátis embrulhados para presente para você, PlayerName?</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>Peões?</size>",
  ui_story_5051_50511101_143_dialog_content = "(O que isso significa? Somos todos peões de jovens Schwartz agora?)",
  ui_story_5051_50511101_144_dialog_content = "(Mas que benefícios alguns de nós podem trazer para ele?)",
  ui_story_5051_50511101_145_dialog_content = "(Também velho Schwartz está dizendo isso...)",
  ui_story_5051_50511101_146_dialog_content = "(Porque ele tratou os outros como peças de xadrez dessa maneira?)",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName, você deve saber que o xadrez é mais do que apenas um jogo agora.</size>",
  ui_story_5051_50511101_148_dialog_content = "Pai!",
  ui_story_5051_50511101_149_dialog_content = "Essa voz...",
  ui_story_5051_50511101_150_dialog_content = "Pai!",
  ui_story_5051_50511101_151_dialog_content = "Carro...",
  ui_story_5051_50511101_152_dialog_content = "Carleen! O que faz aqui?",
  ui_story_5051_50511101_153_dialog_content = "Eu a trouxe aqui.",
  ui_story_5051_50511101_154_dialog_content = "...",
  ui_story_5051_50511101_155_dialog_content = "Por que você está de volta? A segunda onda de Eclipsites foi eliminada?",
  ui_story_5051_50511101_156_dialog_content = "Segunda onda de Eclipsites?",
  ui_story_5051_50511101_157_dialog_content = "Uh, estou apenas preocupado que talvez mais Eclipsites surjam em outro lugar.",
  ui_story_5051_50511101_158_dialog_content = "Não posso comprovar a suspeita, mas também não podemos ser descuidados.",
  ui_story_5051_50511101_159_dialog_content = "Onde está a Sra. Rot? Ela deveria partir com você. Por que ela negligenciou seu posto?",
  ui_story_5051_50511101_160_dialog_content = "A Sra. Rot não negligenciou seu posto. Comparados a mim, os civis precisavam mais de sua ajuda.",
  ui_story_5051_50511101_161_dialog_content = "Você está dificultando as coisas para mim, Joshua.",
  ui_story_5051_50511101_162_dialog_content = "E você sabe que não é a primeira vez, Daniel.",
  ui_story_5051_50511101_163_dialog_content = "Quando você vai se lembrar que minhas habilidades de luta com espada rivalizam com as suas?",
  ui_story_5051_50511101_164_dialog_content = "Você parece ter muitos amigos precisando de ajuda aqui...",
  ui_story_5051_50511101_165_dialog_content = "Deixe-me compartilhar um pouco desse fardo, Daniel.",
  ui_story_5051_50511101_166_dialog_content = "Joshua!",
  ui_story_5051_50511101_167_dialog_content = "COF cof!",
  ui_story_5051_50511101_168_dialog_content = "Você está bem, senhor?",
  ui_story_5051_50511101_169_dialog_content = "Você me parece um tanto familiar...",
  ui_story_5051_50511101_170_dialog_content = "Foi o que você disse quando nos encontramos pela primeira vez.",
  ui_story_5051_50511101_171_dialog_content = "Já nos encontramos antes...?",
  ui_story_5051_50511101_172_dialog_content = "(Agora, quem foi que me avisou para não me envolver neste mundo?)",
  ui_story_5051_50511101_173_dialog_content = "Aham. Vejo que meu pai conhecia Lady Joshua?",
  ui_story_5051_50511101_174_dialog_content = "Minhas desculpas, eu acredito que eu tinha a pessoa errada.",
  ui_story_5051_50511101_175_dialog_content = "Ah, é PlayerNamepai de, não é de admirar que você parecesse familiar!",
  ui_story_5051_50511101_176_dialog_content = "Ai!",
  ui_story_5051_50511101_177_dialog_content = "Eclipsitos! Mais Eclipsites!",
  ui_story_5051_50511101_178_dialog_content = "O City Lord adivinhou na hora. Aí vem a segunda onda!",
  ui_story_5051_50511101_179_dialog_content = "Ele pode prever o futuro também? Talvez até melhor do que eu?!",
  ui_story_5051_50511101_180_dialog_content = "...",
  ui_story_5051_50511101_181_dialog_content = "Daniel!",
  ui_story_5051_50511101_182_dialog_content = "Cuidado com os Eclipsites, pessoal!",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>Tum, tum!</color>",
  ui_story_5051_50511101_184_dialog_content = "Eu ouço passos limpos e ordenados...",
  ui_story_5051_50511101_185_dialog_content = "Provavelmente não são os Eclipsites!",
  ui_story_5051_50511101_186_dialog_content = "Isso é ótimo!",
  ui_story_5051_50511101_187_dialog_content = "Chegou o reforço!",
  ui_story_5051_50511101_188_dialog_content = "Segure-o.",
  ui_story_5051_50511101_189_dialog_content = "Esses soldados não estão aqui para nos ajudar.",
  ui_story_5051_50511101_190_dialog_content = "Hã?",
  ui_story_5051_50511101_191_dialog_content = "Em frente!",
  ui_story_5051_50511101_192_dialog_content = "Uau-!",
  ui_story_5051_50511101_193_dialog_content = "Por que eles estão apontando suas armas para nós?",
  ui_story_5051_50511102_1_dialog_content = "Atrás de você à esquerda, Jakine!",
  ui_story_5051_50511102_2_dialog_content = "Ei, fique longe!",
  ui_story_5051_50511102_3_dialog_content = "Hum...",
  ui_story_5051_50511102_4_dialog_content = "Huh? Você me salvou, PlayerName?",
  ui_story_5051_50511102_5_dialog_content = "N-não...",
  ui_story_5051_50511102_6_dialog_content = "Observe onde você está tropeçando, suas pedras ambulantes.",
  ui_story_5051_50511102_7_dialog_content = "Quem vai me dar bebida se minha pupila estiver machucada?",
  ui_story_5051_50511102_8_dialog_content = "Sim, o incrivelmente intrépido Boaz, de quem me lembro, voltou!",
  ui_story_5051_50511102_9_dialog_content = "Estou tonto, devo ter colocado muito nisso...",
  ui_story_5051_50511102_10_dialog_content = "Você assume, garota, eu terminei...",
  ui_story_5051_50511102_11_dialog_content = "Não-! Ainda não tivemos a oportunidade de recuperar o atraso!",
  ui_story_5051_50511102_12_dialog_content = "Realmente? Adormecer em um momento como este. Retiro o que disse antes!",
  ui_story_5051_50511102_13_dialog_content = "PlayerName, pegar Jakine e Mia e deslizar para fora da lacuna direita. Eu cobrirei você!",
  ui_story_5051_50511102_14_dialog_content = "Estamos deixando os outros para trás?",
  ui_story_5051_50511102_15_dialog_content = "Estamos sem tempo. O <color=#FFB400>insurreição</color> está acontecendo. Cada segundo aqui só aumenta o perigo!",
  ui_story_5051_50511102_16_dialog_content = "Insurreição?",
  ui_story_5051_50511102_17_dialog_content = "Como é que eu não me lembro de nada disso? Eu sabia disso naquela época?",
  ui_story_5051_50511102_18_dialog_content = "Não se esforce, Mia!",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5051_50511102_20_dialog_content = "Quem era aquele?",
  ui_story_5051_50511102_21_dialog_content = "Parecia estar voando do céu e indo atrás de um alvo específico?",
  ui_story_5051_50511102_22_dialog_content = "O alvo pode ser <color=#FFB400>jovem Schwartz</color>?",
  ui_story_5051_50511102_23_dialog_content = "Jovem Schwartz está prestando atenção demais no inimigo para perceber o perigo lá de cima!",
  ui_story_5051_50511102_24_dialog_content = "De jeito nenhum, até mesmo nosso antigo Lorde da Cidade teria visto isso!",
  ui_story_5051_50511102_25_dialog_content = "...",
  ui_story_5051_50511102_26_dialog_content = "Cuidado, Danilo!",
  ui_story_5051_50511102_27_dialog_content = "Olá!",
  ui_story_5051_50511102_28_dialog_content = "Err...",
  ui_story_5051_50511102_29_dialog_content = "Oh, isso parece doloroso!",
  ui_story_5051_50511102_30_dialog_content = "Ele foi esfaqueado no ombro?",
  ui_story_5051_50511102_31_dialog_content = "Temos que nos apressar enquanto todos estão distraídos!",
  ui_story_5051_50511102_32_dialog_content = "Mas...",
  ui_story_5051_50511102_33_dialog_content = "Pai!",
  ui_story_5051_50511102_34_dialog_content = "Eu vou ajudar o Pai!",
  ui_story_5051_50511102_35_dialog_content = "É mesmo?",
  ui_story_5051_50511102_36_dialog_content = "Carleen...",
  ui_story_5051_50511102_37_dialog_content = "Oh não, os rebeldes viram jovens Carleen!",
  ui_story_5051_50511102_38_dialog_content = "... O que?",
  ui_story_5051_50511102_39_dialog_content = "A-Você também é um cara mau?",
  ui_story_5051_50511102_40_dialog_content = "Olá, princesinha!",
  ui_story_5051_50511102_41_dialog_content = "D-Não pense que tenho medo de você!",
  ui_story_5051_50511102_42_dialog_content = "Eu sou muito habilidoso com espadas! Eu venci muitos soldados!",
  ui_story_5051_50511102_43_dialog_content = "Uma pena que não terei piedade de vocês como aqueles soldados!",
  ui_story_5051_50511102_44_dialog_content = "Afe!",
  ui_story_5051_50511102_45_dialog_content = "Heh, eu nem suei e você já está no chão!",
  ui_story_5051_50511102_46_dialog_content = "Não se preocupe em levantar. Você vai cair de qualquer maneira.",
  ui_story_5051_50511102_47_dialog_content = "Afe!",
  ui_story_5051_50511102_48_dialog_content = "A Lâmina do Soberano!",
  ui_story_5051_50511102_49_dialog_content = "Que diabos...",
  ui_story_5051_50511102_50_dialog_content = "(Velho Schwartz exortou-nos a correr apenas para salvar Carleen ele mesmo.)",
  ui_story_5051_50511102_51_dialog_content = "Estou salvo? Pai, é você...?",
  ui_story_5051_50511102_52_dialog_content = "...",
  ui_story_5051_50511102_53_dialog_content = "Carleen!",
  ui_story_5051_50511102_54_dialog_content = "Está ferida?",
  ui_story_5051_50511102_55_dialog_content = "Não se preocupe, mãe, não estou ferido.",
  ui_story_5051_50511102_56_dialog_content = "Por que você ainda está falando duro, criança...",
  ui_story_5051_50511102_57_dialog_content = "Ela provavelmente só ficou com medo, só isso.",
  ui_story_5051_50511102_58_dialog_content = "Obrigado por salvar Carleen, pai de PlayerName!",
  ui_story_5051_50511102_59_dialog_content = "Não precisa me agradecer. É algo que eu deveria fazer.",
  ui_story_5051_50511102_60_dialog_content = "meu pobrezinho Carleen...",
  ui_story_5051_50511102_61_dialog_content = "Mãe, como está *tosse tosse* Pai?",
  ui_story_5051_50511102_62_dialog_content = "Ele, ah...",
  ui_story_5051_50511102_63_dialog_content = "Não se preocupe, ele vai derrotar os bandidos em breve.",
  ui_story_5051_50511102_64_dialog_content = "Mãe, você deveria ir ajudar o pai. Estou bem... totalmente bem!",
  ui_story_5051_50511102_65_dialog_content = "Oh, minha menina tola.",
  ui_story_5051_50511102_66_dialog_content = "Olá!",
  ui_story_5051_50511102_67_dialog_content = "Tosse...",
  ui_story_5051_50511102_68_dialog_content = "Daniel!",
  ui_story_5051_50511102_69_dialog_content = "Não se preocupe, ele é mais do que suficiente para enfrentar o assassino sozinho.",
  ui_story_5051_50511102_70_dialog_content = "Mas ele está ferido...",
  ui_story_5051_50511102_71_dialog_content = "Então fique aqui e deixe-me ajudar seu marido.",
  ui_story_5051_50511102_72_dialog_content = "O que? Você não deve arriscar sua vida por isso.",
  ui_story_5051_50511102_73_dialog_content = "Como você pode ver, os traidores não estão mirando em você, mas em mim e na minha família.",
  ui_story_5051_50511102_74_dialog_content = "Não há tempo para tais distinções nestas circunstâncias.",
  ui_story_5051_50511102_75_dialog_content = "Espere aqui.",
  ui_story_5051_50511102_76_dialog_content = "PlayerName, espere aqui com Jakine e Mia também.",
  ui_story_5051_50511102_77_dialog_content = "Eu volto já.",
  ui_story_5051_50511102_78_dialog_content = "Espere!",
  ui_story_5051_50511102_79_dialog_content = "Gostaria de ir com você.",
  ui_story_5051_50511102_80_dialog_content = "...",
  ui_story_5051_50511102_81_dialog_content = "Você pega o flanco esquerdo e eu o direito. Vamos embora!",
  ui_story_5051_50511102_82_dialog_content = "... S-Claro!",
  ui_story_5051_50511102_83_dialog_content = "Estou alucinando?",
  ui_story_5051_50511102_84_dialog_content = "Ou é aquele Daniel que eu vi em PlayerNamepai de...?",
  ui_story_5051_50511102_85_dialog_content = "Err...",
  ui_story_5051_50511102_86_dialog_content = "Há muito tempo que te espero.",
  ui_story_5051_50511102_87_dialog_content = "O quê?",
  ui_story_5051_50511102_88_dialog_content = "Heh, esta ferida não é tão ruim quanto eu imaginei que seria.",
  ui_story_5051_50511102_89_dialog_content = "Então você já percebeu.",
  ui_story_5051_50511102_90_dialog_content = "Pare de falar e vamos terminar isso.",
  ui_story_5051_50511102_91_dialog_content = "Vou ajudar!",
  ui_story_5051_50511102_92_dialog_content = "Retiro!",
  ui_story_5051_50511102_93_dialog_content = "Todos, retirem-se!",
  ui_story_5051_50511102_94_dialog_content = "Obrigado a todos por me darem essa oportunidade...",
  ui_story_5051_50511102_95_dialog_content = "Aurora Aeterna sob a Luz!",
  ui_story_5051_50511102_96_dialog_content = "Ugh!",
  ui_story_5051_50511102_97_dialog_content = "Como mencionei...",
  ui_story_5051_50511102_98_dialog_content = "Como senhor da cidade, sou mais do que apenas um burocrata.",
  ui_story_5051_50511201_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5051_50511201_2_dialog_content = "Você está bem, tio?",
  ui_story_5051_50511201_3_dialog_content = "Sharona?!",
  ui_story_5051_50511201_4_dialog_content = "Eu não lhe disse para tirar meio dia de folga? O que você está fazendo aqui?",
  ui_story_5051_50511201_5_dialog_content = "Prometemos ao amigo da princesa Veronica encontrar algumas pessoas esta manhã, então pensei que talvez pudesse ajudar...",
  ui_story_5051_50511201_6_dialog_content = "É minha culpa não seguir suas ordens, tio.",
  ui_story_5051_50511201_7_dialog_content = "Mas quando os Eclipsitas invadiram a cidade, é meu dever como cavaleiro em treinamento proteger o povo!",
  ui_story_5051_50511201_8_dialog_content = "Além disso, eu estava preocupado com os Kartimas patrulhando a cidade... assim como você.",
  ui_story_5051_50511201_9_dialog_content = "Está bem.",
  ui_story_5051_50511201_10_dialog_content = "Você irá para casa agora e deixará Lumopolis com sua tia e primos!",
  ui_story_5051_50511201_11_dialog_content = "Pegue o dirigível estacionado no jardim traseiro.",
  ui_story_5051_50511201_12_dialog_content = "Por que, tio?",
  ui_story_5051_50511201_13_dialog_content = "Não pergunte por que, apenas faça!",
  ui_story_5051_50511201_14_dialog_content = "Olhe para os Eclipsites na rua, tio. Eles parecem hesitantes em atacar você ou a mim.",
  ui_story_5051_50511201_15_dialog_content = "O sangue Kartima correndo por nós pode ser a ruína deles.",
  ui_story_5051_50511201_16_dialog_content = "Se conseguirmos que todo o clã repela os Eclipsitas de Lumópolis desta vez...",
  ui_story_5051_50511201_17_dialog_content = "Nós definitivamente ganharemos o favor do Senhor da Cidade e recuperaremos a glória da família!",
  ui_story_5051_50511201_18_dialog_content = "Então, por que você está me instruindo a fugir com a família neste momento?",
  ui_story_5051_50511201_19_dialog_content = "Você acabou de me lembrar, você pode encontrar outros Eclipsites depois de sair de Lumopolis...",
  ui_story_5051_50511201_20_dialog_content = "No meu escritório há uma katana de herança da Kartima chamada Azure Chama.",
  ui_story_5051_50511201_21_dialog_content = "Lembre-se de trazê-lo com você!",
  ui_story_5051_50511201_22_dialog_content = "Eu não entendo, tio...",
  ui_story_5051_50511201_23_dialog_content = "Talvez essa profecia seja verdadeira, mas nunca acreditei nela.",
  ui_story_5051_50511201_24_dialog_content = "A pessoa que vai salvar os Kartimas é você...",
  ui_story_5051_50511201_25_dialog_content = "Eu não.",
  ui_story_5051_50511201_26_dialog_content = "...",
  ui_story_5051_50511201_27_dialog_content = "Tudo isso aconteceu exatamente como da vez anterior?",
  ui_story_5051_50511201_28_dialog_content = "Praticamente idêntico.",
  ui_story_5051_50511201_29_dialog_content = "Exceto que o ferimento de Carleen era pior e eu não estava lá para protegê-la.",
  ui_story_5051_50511201_30_dialog_content = "É por isso que você não pôde deixar de ir quando ouviu a voz dela.",
  ui_story_5051_50511201_31_dialog_content = "Você estava tentando compensar isso?",
  ui_story_5051_50511201_32_dialog_content = "Estaria mentindo se dissesse que não.",
  ui_story_5051_50511201_33_dialog_content = "Como é Carleen?",
  ui_story_5051_50511201_34_dialog_content = "Geralmente bem, apenas alguns arranhões nas mãos e nos pés.",
  ui_story_5051_50511201_35_dialog_content = "Mas você, no entanto, está sangrando no ombro!",
  ui_story_5051_50511201_36_dialog_content = "Não é mais grave do que uma picada de mosquito.",
  ui_story_5051_50511201_37_dialog_content = "Faz muito tempo que não praticamos luta de espadas juntos.",
  ui_story_5051_50511201_38_dialog_content = "Este nível de emboscada não teria te tocado antes...",
  ui_story_5051_50511201_39_dialog_content = "Foi abrupto e provavelmente também fiquei um pouco desequilibrado.",
  ui_story_5051_50511201_40_dialog_content = "Primeiro uma invasão dos Eclipsitas, depois o envio de assassinos no próprio dia da Schwartz Dia da família...",
  ui_story_5051_50511201_41_dialog_content = "Quem guardaria tal rancor contra nós?",
  ui_story_5051_50511201_42_dialog_content = "Senhor Schwartz, Senhora Josué.",
  ui_story_5051_50511201_43_dialog_content = "Por favor, perdoe a mim e ao meu esquadrão pela nossa chegada tardia.",
  ui_story_5051_50511201_44_dialog_content = "É a nossa negligência que fez com que a princesa e o senhor se machucassem.",
  ui_story_5051_50511201_45_dialog_content = "A culpa não é sua, Sra. Rot.",
  ui_story_5051_50511201_46_dialog_content = "Para garantir a segurança dos civis é sua prioridade.",
  ui_story_5051_50511201_47_dialog_content = "Obrigado minha senhora.",
  ui_story_5051_50511201_48_dialog_content = "Mais alguma coisa a relatar?",
  ui_story_5051_50511201_49_dialog_content = "Sim, meu senhor.",
  ui_story_5051_50511201_50_dialog_content = "Nós vasculhamos a vizinhança e capturamos vários rebeldes vivos.",
  ui_story_5051_50511201_51_dialog_content = "Diga-me o que você descobriu.",
  ui_story_5051_50511201_52_dialog_content = "Encontramos armas com imagens únicas em suas pessoas.",
  ui_story_5051_50511201_53_dialog_content = "Após comparações, verificamos que as imagens são marcações da Casa Kartima.",
  ui_story_5051_50511201_54_dialog_content = "Casa Kartima?",
  ui_story_5051_50511201_55_dialog_content = "Eu estava conversando com a esposa de Mime em uma festa não muito tempo atrás.",
  ui_story_5051_50511201_56_dialog_content = "Seus dois filhos tinham mais ou menos a mesma idade de Carleen.",
  ui_story_5051_50511201_57_dialog_content = "Não, algo está errado aqui.",
  ui_story_5051_50511201_58_dialog_content = "Por que eles estariam carregando armas que poderiam facilmente incriminá-los?",
  ui_story_5051_50511201_59_dialog_content = "Pessoas arrogantes também costumam ser muito ingênuas.",
  ui_story_5051_50511201_60_dialog_content = "Eles tinham certeza de que poderiam acabar comigo hoje e acabar com o reinado de Schwartz.",
  ui_story_5051_50511201_61_dialog_content = "Sra. Rot.",
  ui_story_5051_50511201_62_dialog_content = "Ao seu serviço, meu senhor.",
  ui_story_5051_50511201_63_dialog_content = "Notifique o Tribunal de Justiça sobre evidências concretas da insurreição da Casa Kartima.",
  ui_story_5051_50511201_64_dialog_content = "Coloque um boletim de todos os pontos em toda a cidade <color=#FFB400>Todos os membros</color> da família Kartima imediatamente",
  ui_story_5051_50511201_65_dialog_content = "Solicitar que o Tribunal de Justiça emita o mesmo e nos auxilie na apreensão.",
  ui_story_5051_50511201_66_dialog_content = "Execute o suspeito no local quando encontrar resistência.",
  ui_story_5051_50511201_67_dialog_content = "Sim, meu senhor.",
  ui_story_5051_50511201_68_dialog_content = "Todos os membros da Casa Kartima? O que você está fazendo, Daniel...?",
  ui_story_5051_50511201_69_dialog_content = "Já vi muitas coisas assim acontecerem este ano.",
  ui_story_5051_50511201_70_dialog_content = "Os espíritos da Casa Pyrrhus e da Casa Gautier não são suficientes?",
  ui_story_5051_50511201_71_dialog_content = "Joshua...",
  ui_story_5051_50511201_72_dialog_content = "Carleen precisa de descanso. Levá-la para casa.",
  ui_story_5051_50511201_73_dialog_content = "...",
  ui_story_5051_50511201_74_dialog_content = "Joshua... Lady Joshua, estou prestes a partir com meu filho também.",
  ui_story_5051_50511201_75_dialog_content = "Permita-me acompanhá-lo de volta.",
  ui_story_5051_50511201_76_dialog_content = "Agradeço a oferta.",
  ui_story_5051_50511201_77_dialog_content = "Mas como os Eclipsites foram removidos da cidade, acredito que posso cuidar disso sozinho.",
  ui_story_5051_50511201_78_dialog_content = "Sr. Soroz... Se bem me lembro, esse é o seu nome, certo?",
  ui_story_5051_50511201_79_dialog_content = "Sim.",
  ui_story_5051_50511201_80_dialog_content = "Me desculpe por ter duvidado de você.",
  ui_story_5051_50511201_81_dialog_content = "Como você mencionou, você é perfeitamente capaz de lidar com os Eclipsites.",
  ui_story_5051_50511201_82_dialog_content = "Um guerreiro excepcional como você não deve permanecer anônimo.",
  ui_story_5051_50511201_83_dialog_content = "Não fui um anfitrião perfeito hoje, portanto, talvez possamos manter uma longa troca depois que tudo isso acabar.",
  ui_story_5051_50511201_84_dialog_content = "Sou apenas um velho comum.",
  ui_story_5051_50511201_85_dialog_content = "Que desejou uma passagem segura para casa para seu filho.",
  ui_story_5051_50511201_86_dialog_content = "Que pena, pensei que teríamos muito em comum para conversar.",
  ui_story_5051_50511201_87_dialog_content = "Talvez aqueles que são muito parecidos não devam ser amigos.",
  ui_story_5051_50511201_88_dialog_content = "Ei, é mesmo?",
  ui_story_5051_50511201_89_dialog_content = "Tudo bem. Venha, Verônica.",
  ui_story_5051_50511201_90_dialog_content = "M-eu?",
  ui_story_5051_50511201_91_dialog_content = "Há mais alguém aqui chamado Veronica?",
  ui_story_5051_50511201_92_dialog_content = "Onde estamos indo?",
  ui_story_5051_50511201_93_dialog_content = "Perseguir os rebeldes sobreviventes de Kartima.",
  ui_story_5051_50511201_94_dialog_content = "Espero que você aprenda a lutar comigo, a partir de hoje.",
  ui_story_5051_50511201_95_dialog_content = "Acha que estou qualificado, padre...",
  ui_story_5051_50511201_96_dialog_content = "As habilidades da princesa Veronica estavam em plena exibição.",
  ui_story_5051_50511201_97_dialog_content = "Mas ela ainda é jovem e gastou muita energia hoje.",
  ui_story_5051_50511201_98_dialog_content = "É melhor ela voltar para casa para descansar.",
  ui_story_5051_50511201_99_dialog_content = "Sr. Soroz, talvez PlayerName precisa descansar, mas Veronica é minha filha.",
  ui_story_5051_50511201_100_dialog_content = "Vamos cuidar de nossos filhos, respectivamente.",
  ui_story_5051_50511201_101_dialog_content = "<size=30>Bem, é...</size>",
  ui_story_5051_50511201_102_dialog_content = "Ela precisa descansar.",
  ui_story_5051_50511201_103_dialog_content = "Ela precisa aprender.",
  ui_story_5051_50511201_104_dialog_content = "<size=45>Bem!</size>",
  ui_story_5051_50511201_105_dialog_content = "O quê?",
  ui_story_5051_50511201_106_dialog_content = "E-eu...",
  ui_story_5051_50511201_107_dialog_content = "Eu quero ir!",
  ui_story_5051_50511201_108_dialog_content = "?!",
  ui_story_5051_50511201_109_dialog_content = "Papai nunca foi tão aprovado por mim...",
  ui_story_5051_50511201_110_dialog_content = "Eu nunca vou decepcioná-lo novamente!",
  ui_story_5051_50511201_111_dialog_content = "Além disso, gostaria de ver como será essa história da qual nunca fiz parte.",
  ui_story_5051_50511201_112_dialog_content = "...",
  ui_story_5051_50511201_113_dialog_content = "Hora de ir, Verônica!",
  ui_story_5051_50511201_114_dialog_content = "C-Chegando!",
  ui_story_5051_50511201_115_dialog_content = "Então eu vou também!",
  ui_story_5051_50511201_116_dialog_content = "Vocês são muito teimosos.",
  ui_story_5051_50511201_117_dialog_content = "Ei, velho Schwartz, Boaz está completamente fora e não parece certo...",
  ui_story_5051_50511201_118_dialog_content = "A senhora disse que a traria para tratamento, mas não posso deixá-la entregue ao destino.",
  ui_story_5051_50511201_119_dialog_content = "Você deve ter cuidado se for a outro lugar.",
  ui_story_5051_50511201_120_dialog_content = "Além disso, certifique-se de voltar antes do fim do dia, ou podemos ficar presos aqui para sempre...",
  ui_story_5051_50511201_121_dialog_content = "... Entendo.",
  ui_story_5051_50511201_122_dialog_content = "Mas do que você acabou de me chamar?",
  ui_story_5051_50511201_123_dialog_content = "Ops, foi um deslize.",
  ui_story_5051_50511201_124_dialog_content = "De qualquer forma, volte assim que puder!",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>Residência Otto</color>",
  ui_story_5051_50511201_126_dialog_content = "Você sabia disso, Duque Troy?",
  ui_story_5051_50511201_127_dialog_content = "O que? A que se refere, duque Hermes?",
  ui_story_5051_50511201_128_dialog_content = "Está uma grande bagunça lá fora, então pare de me enganar.",
  ui_story_5051_50511201_129_dialog_content = "Oh, você quer dizer que alguém tentou tirar proveito de uma incursão Eclipsite para assassinar o Senhor da Cidade?",
  ui_story_5051_50511201_130_dialog_content = "Sim!",
  ui_story_5051_50511201_131_dialog_content = "Por mais que eu desaprove Schwartz, Eu nunca desceria tão baixo e correria o risco de arruinar o nome de minha família.",
  ui_story_5051_50511201_132_dialog_content = "Então, você realmente não sabia nada disso?",
  ui_story_5051_50511201_133_dialog_content = "Duque Hermes, por que você deve ser tão paranóico e suspeitar de todos?",
  ui_story_5051_50511201_134_dialog_content = "Não pretendo questioná-lo, duque Troy.",
  ui_story_5051_50511201_135_dialog_content = "Mas... você sabe, todos os descendentes da família Hermes se juntaram aos Cavaleiros Lumo.",
  ui_story_5051_50511201_136_dialog_content = "Schwartz agora está convocando toda a ordem para ajudar Umbraton, ao qual sempre me opus!",
  ui_story_5051_50511201_137_dialog_content = "Esses Eclipsites rastejantes não podem afetar Lumopolis.",
  ui_story_5051_50511201_138_dialog_content = "Então, por que devemos ser enviados para a morte?",
  ui_story_5051_50511201_139_dialog_content = "Eu não sou o único com esse pensamento, sou?",
  ui_story_5051_50511201_140_dialog_content = "O Lorde da Cidade também tem suas preocupações, Duque Hermes.",
  ui_story_5051_50511201_141_dialog_content = "Lumopolis seria capaz de exercer um controle mais rígido sobre Umbraton se nós o defendermos, não é melhor?",
  ui_story_5051_50511201_142_dialog_content = "Não é como se você não entendesse, duque Hermes.",
  ui_story_5051_50511201_143_dialog_content = "Mesmo uma pequena borda como essa provavelmente acabaria agarrada por Schwartz, de qualquer forma.",
  ui_story_5051_50511201_144_dialog_content = "E ele teve a ousadia de comemorar o chamado Schwartz Dia da família.",
  ui_story_5051_50511201_145_dialog_content = "As famílias Hermes e Troy fizeram contribuições significativas para tornar Lumopolis o que é hoje!",
  ui_story_5051_50511201_146_dialog_content = "Por que a casa deveria Schwartz conseguiu tudo?!",
  ui_story_5051_50511201_147_dialog_content = "Se os Kartimas tivessem nos informado sobre o plano e combinado nossas forças...",
  ui_story_5051_50511201_148_dialog_content = "Estaríamos de pé para Schwartz!",
  ui_story_5051_50511201_149_dialog_content = "Tenha cuidado com suas palavras, duque Hermes.",
  ui_story_5051_50511201_150_dialog_content = "Acabei de receber a notícia de que o Lorde da Cidade ordenou a prisão de todos os Kartimas.",
  ui_story_5051_50511201_151_dialog_content = "Mesmo uma criança pode descobrir como isso vai acabar para eles.",
  ui_story_5051_50511201_152_dialog_content = "Não pode ser tão ruim quanto para a Casa Pyrrhus e a Casa Gautier!",
  ui_story_5051_50511201_153_dialog_content = "Suspirar. Você ainda não entendeu? É aí que está o problema.",
  ui_story_5051_50511201_154_dialog_content = "O que? Você quer dizer...",
  ui_story_5051_50511201_155_dialog_content = "Espere, entendi, conectei todos os pontos agora!",
  ui_story_5051_50511201_156_dialog_content = "Os Kartimas são tão tolos!",
  ui_story_5051_50511201_157_dialog_content = "Eles apenas deram Schwartz mais influência com o que eles acabaram de fazer!",
  ui_story_5051_50511201_158_dialog_content = "Schwartz pode usá-lo para convocar os Lumo Knights e até mesmo exércitos de casas particulares para suas mortes em Umbraton.",
  ui_story_5051_50511201_159_dialog_content = "Mime Kartima, seu tolo sem cérebro!",
  ui_story_5051_50511201_160_dialog_content = "Dadas as circunstâncias, quanto menos falado melhor, Duque Hermes.",
  ui_story_5051_50511201_161_dialog_content = "E eu cochilei e perdi tudo o que você disse.",
  ui_story_5051_50511201_162_dialog_content = "Obrigado, Duque Troy. Por favor, não me deixe ficar com você. Até a próxima.",
  ui_story_5051_50511201_163_dialog_content = "Servo.",
  ui_story_5051_50511201_164_dialog_content = "Sim.",
  ui_story_5051_50511201_165_dialog_content = "E destrua todos os indícios de correspondência com a Casa Kartima.",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50511201_167_dialog_content = "O que foi isso?",
  ui_story_5051_50511201_168_dialog_content = "vou verificar.",
  ui_story_5051_50511201_169_dialog_content = "Você viu quem era?",
  ui_story_5051_50511201_170_dialog_content = "Era a senhorita Rohsee. Você deveria vê-la antes do jantar.",
  ui_story_5051_50511201_171_dialog_content = "Ela estava esperando lá fora por um tempo.",
  ui_story_5051_50511201_172_dialog_content = "Mas acabou de sair em pânico.",
  ui_story_5051_50511201_173_dialog_content = "Ah, crianças hoje em dia...",
  ui_story_5051_50511301_1_dialog_content = "Também não encontramos nada nesta propriedade de Kartima, senhor da cidade.",
  ui_story_5051_50511301_2_dialog_content = "Todos os bens da Kartima em Lumopolis Gardens foram confiscados. Além de servos, nenhum pessoal armado foi descoberto.",
  ui_story_5051_50511301_3_dialog_content = "Exceto por um dirigível que ignorou os avisos e deixou Lumópolis...",
  ui_story_5051_50511301_4_dialog_content = "Todos os outros membros da Casa Kartima ainda devem estar escondidos na cidade.",
  ui_story_5051_50511301_5_dialog_content = "E quanto ao Pátio de Lumopolis e ao Lower Lumopolis?",
  ui_story_5051_50511301_6_dialog_content = "O pessoal foi despachado, mas é necessário tempo para reunir detalhes específicos.",
  ui_story_5051_50511301_7_dialog_content = "Eles não fugiram, mas se esconderam na cidade?",
  ui_story_5051_50511301_8_dialog_content = "Parece que eles estão esperando uma oportunidade para atacar novamente.",
  ui_story_5051_50511301_9_dialog_content = "A House Kartima possui muitos membros e ganhou amplos afiliados nos últimos anos.",
  ui_story_5051_50511301_10_dialog_content = "Diante disso, a situação é mais precária do que se imagina...",
  ui_story_5051_50511301_11_dialog_content = "Não podemos ser passivos.",
  ui_story_5051_50511301_12_dialog_content = "Devemos continuar a busca no pátio de Lumopolis.",
  ui_story_5051_50511301_13_dialog_content = "Um momento por favor.",
  ui_story_5051_50511301_14_dialog_content = "Afinal, você veio!",
  ui_story_5051_50511301_15_dialog_content = "...",
  ui_story_5051_50511301_16_dialog_content = "<size=30>Não tenha medo, Mia, eu não estou aqui para levá-lo de volta.</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>Eu ponderei e você tem o direito de conhecer esta parte da história.</size>",
  ui_story_5051_50511301_18_dialog_content = "Sr Soroz? Eu sabia que nos encontraríamos novamente muito em breve.",
  ui_story_5051_50511301_19_dialog_content = "Embora eu não esperasse que fosse tão rápido.",
  ui_story_5051_50511301_20_dialog_content = "De repente, lembrei que posso ter as pistas que você está procurando.",
  ui_story_5051_50511301_21_dialog_content = "Espero que não esteja me atrasando de propósito.",
  ui_story_5051_50511301_22_dialog_content = "Claro que não. Também espero que meu filho rebelde volte para casa comigo de bom grado a tempo.",
  ui_story_5051_50511301_23_dialog_content = "No entanto, gostaria que você me prometesse que não perseguirá minha fonte de informação.",
  ui_story_5051_50511301_24_dialog_content = "Claro, eu prometo que não vou perseguir sua fonte. Diga-me, quais pistas você tem?",
  ui_story_5051_50511301_25_dialog_content = "Há sinais de exércitos particulares acampando em um campo subdesenvolvido em Lower Lumopolis.",
  ui_story_5051_50511301_26_dialog_content = "Você já ouviu isso, Sra. Rot?",
  ui_story_5051_50511301_27_dialog_content = "Deserto perto da periferia...",
  ui_story_5051_50511301_28_dialog_content = "Pode ser aquela colina rochosa?",
  ui_story_5051_50511301_29_dialog_content = "Já ouvi relatos de gritos estranhos e ocasionais de animais, mas é desolado.",
  ui_story_5051_50511301_30_dialog_content = "Você está dizendo, Sr. Soroz, que é onde os Kartimas podem estar escondidos?",
  ui_story_5051_50511301_31_dialog_content = "Estou cem por cento certo.",
  ui_story_5051_50511301_32_dialog_content = "Por que você tem tanta certeza? De onde você tirou essa informação?",
  ui_story_5051_50511301_33_dialog_content = "Você me prometeu não perguntar.",
  ui_story_5051_50511301_34_dialog_content = "Mas você pode me punir como quiser, caso a informação seja falsa.",
  ui_story_5051_50511301_35_dialog_content = "Tudo bem. Sra. Rot, vamos para a área.",
  ui_story_5051_50511301_36_dialog_content = "A liderança é confiável, Senhor da Cidade?",
  ui_story_5051_50511301_37_dialog_content = "A rendição e queda dos Kartimas são inevitáveis.",
  ui_story_5051_50511301_38_dialog_content = "Importa não confiar nele desta vez.",
  ui_story_5051_50511301_39_dialog_content = "Claro, também não pare de pentear outras áreas.",
  ui_story_5051_50511301_40_dialog_content = "Sim, meu senhor.",
  ui_story_5051_50511301_41_dialog_content = "Hum...",
  ui_story_5051_50511301_42_dialog_content = "Você tem uma pergunta para mim?",
  ui_story_5051_50511301_43_dialog_content = "Sobre essa pista, você conseguiu de alguém naquela época?",
  ui_story_5051_50511301_44_dialog_content = "Não, não encontramos nenhuma informação útil na cidade.",
  ui_story_5051_50511301_45_dialog_content = "Somente à noite notamos movimentos no deserto e sofremos uma ofensiva brutal deles.",
  ui_story_5051_50511301_46_dialog_content = "No entanto, no final das contas, eles ainda não conseguiram evitar a derrota.",
  ui_story_5051_50511301_47_dialog_content = "Você acelerou a linha do tempo para que possamos voltar o mais rápido possível?",
  ui_story_5051_50511301_48_dialog_content = "Às vezes, eu pensava que se tivesse localizado as forças rebeldes antes...",
  ui_story_5051_50511301_49_dialog_content = "Talvez os soldados que me seguem há anos tenham alguns filhos que agora consideram problemáticos.",
  ui_story_5051_50511301_50_dialog_content = "Você não tem estado apreensivo em bagunçar este mundo?",
  ui_story_5051_50511301_51_dialog_content = "Já fizemos o suficiente. Este não fará grande diferença.",
  ui_story_5051_50511301_52_dialog_content = "Você não é exatamente o Senhor Schwartz Eu sabia agora.",
  ui_story_5051_50511301_53_dialog_content = "Você acha? Eu também me sinto diferente, uma vez que deixei de lado meu status de Lorde da Cidade.",
  ui_story_5051_50511301_54_dialog_content = "Especialmente depois de conhecer meu eu mais jovem.",
  ui_story_5051_50511301_55_dialog_content = "Este é o lugar?",
  ui_story_5051_50511301_56_dialog_content = "De acordo com batedores, os Kartimas realmente se reuniram na colina à frente.",
  ui_story_5051_50511301_57_dialog_content = "Eles parecem estar planejando lutar até o último suspiro!",
  ui_story_5051_50511301_58_dialog_content = "Venha, Verônica.",
  ui_story_5051_50511301_59_dialog_content = "Diga-me, o que você faria nesta situação se estivesse no comando?",
  ui_story_5051_50511301_60_dialog_content = "Se eu estivesse no comando...",
  ui_story_5051_50511301_61_dialog_content = "Eu enviaria um enviado para argumentar ou persuadi-los.",
  ui_story_5051_50511301_62_dialog_content = "Incentive-os a admitir o erro de seus caminhos e compensá-lo.",
  ui_story_5051_50511301_63_dialog_content = "Errado, Verônica.",
  ui_story_5051_50511301_64_dialog_content = "Se você quer assumir maiores responsabilidades, deve se esforçar para vencer <color=#FFB400>a qualquer custo</color>.",
  ui_story_5051_50511301_65_dialog_content = "Ganhar a qualquer custo?",
  ui_story_5051_50511301_66_dialog_content = "Dos Jardins de Lumopolis até Umbraton, todos os olhos estão voltados para esta batalha.",
  ui_story_5051_50511301_67_dialog_content = "Eles estão esperando para ver quem sairá vitorioso e só vão elogiar o vencedor, independentemente de quem seja.",
  ui_story_5051_50511301_68_dialog_content = "A história é escrita pelos vencedores.",
  ui_story_5051_50511301_69_dialog_content = "A história de Lumopolis provavelmente mudará em um futuro não muito distante.",
  ui_story_5051_50511301_70_dialog_content = "Você ainda tem muito a aprender, Verônica.",
  ui_story_5051_50511301_71_dialog_content = "Seja qual for o custo? Acho essa perspectiva... difícil de engolir.",
  ui_story_5051_50511301_72_dialog_content = "É mesmo?",
  ui_story_5051_50511301_73_dialog_content = "(Opa, esqueci que zombar dos jovens Schwartz é o mesmo que zombar dele!)",
  ui_story_5051_50511301_74_dialog_content = "Uh, isso não foi intencional...",
  ui_story_5051_50511301_75_dialog_content = "Você só precisa tomar algumas decisões quando está no topo, mesmo que isso pareça uma desculpa para fugir da culpa.",
  ui_story_5051_50511301_76_dialog_content = "Mas o eu atual não vai se gabar enfaticamente de ser um grande líder impecável.",
  ui_story_5051_50511301_77_dialog_content = "Eu só espero...",
  ui_story_5051_50511301_78_dialog_content = "Que você abrirá sua própria trilha no futuro e encontrará um caminho que pertence exclusivamente a você.",
  ui_story_5051_50511301_79_dialog_content = "Pode deixar!",
  ui_story_5051_50511301_80_dialog_content = "Espero que, quando envelhecer, não me arrependa do meu eu mais jovem.",
  ui_story_5051_50511301_81_dialog_content = "Uh, isso não era para ser sarcasmo com você!",
  ui_story_5051_50511301_82_dialog_content = "Ha ha ha!",
  ui_story_5051_50511301_83_dialog_content = "(Esta é a primeira vez que me lembro de ter visto Schwartz Rindo alto.)",
  ui_story_5051_50511301_84_dialog_content = "(Acabei de perceber, fora deste velho e jovem Schwartz...)",
  ui_story_5051_50511301_85_dialog_content = "(Em um passado ainda mais distante, havia um Daniel inocente e risonho...)",
  ui_story_5051_50511301_86_dialog_content = "Eu sinto algo à frente.",
  ui_story_5051_50511301_87_dialog_content = "... Rebeldes em emboscada!",
  ui_story_5051_50511302_1_dialog_content = "Eu procurei em todas as salas principais.",
  ui_story_5051_50511302_2_dialog_content = "No entanto, ainda não consigo encontrá-lo!",
  ui_story_5051_50511302_3_dialog_content = "Fez Schwartz construir uma câmara secreta?",
  ui_story_5051_50511302_4_dialog_content = "Deve ser esse o caso.",
  ui_story_5051_50511302_5_dialog_content = "A julgar pela personalidade de Schwartz, ele deve estar escondendo muitos segredos de Joshua.",
  ui_story_5051_50511302_6_dialog_content = "A entrada secreta poderia estar em seu escritório?",
  ui_story_5051_50511302_7_dialog_content = "Hmm, o que é isso na estante?",
  ui_story_5051_50511302_8_dialog_content = "O Cristal da Memória Eterna?!",
  ui_story_5051_50511302_9_dialog_content = "Sim, é de fato o Cristal da Memória Eterna!",
  ui_story_5051_50511302_10_dialog_content = "O lugar mais perigoso é o mais seguro, hein?",
  ui_story_5051_50511302_11_dialog_content = "Hahaha.",
  ui_story_5051_50511302_12_dialog_content = "eu não posso acreditar Schwartz deixaria algo tão precioso em aberto.",
  ui_story_5051_50511302_13_dialog_content = "Assim como o que ele fez com minha querida irmã...",
  ui_story_5051_50511302_14_dialog_content = "Você está de volta, minha senhora!",
  ui_story_5051_50511302_15_dialog_content = "É ela...",
  ui_story_5051_50511302_16_dialog_content = "Você parece nervoso. O que aconteceu?",
  ui_story_5051_50511302_17_dialog_content = "Por favor, perdoe minha inaptidão!",
  ui_story_5051_50511302_18_dialog_content = "Um guarda do portão foi nocauteado esta tarde e ainda está na enfermaria.",
  ui_story_5051_50511302_19_dialog_content = "Verificamos em todos os lugares, mas ainda não conseguimos encontrar o culpado...",
  ui_story_5051_50511302_20_dialog_content = "Alguém da Casa Kartima de novo?",
  ui_story_5051_50511302_21_dialog_content = "Entendi.",
  ui_story_5051_50511302_22_dialog_content = "Temos convidados para a noite. Por favor, seja mais vigilante.",
  ui_story_5051_50511302_23_dialog_content = "Sim minha senhora!",
  ui_story_5051_50511302_24_dialog_content = "Além disso, certifique-se de que o guarda ferido se recupere em paz.",
  ui_story_5051_50511302_25_dialog_content = "Eu pago a conta médica.",
  ui_story_5051_50511302_26_dialog_content = "Obrigado minha senhora!",
  ui_story_5051_50511302_27_dialog_content = "Os Kartimas...",
  ui_story_5051_50511302_28_dialog_content = "Você não conhece alguém dessa família?",
  ui_story_5051_50511302_29_dialog_content = "Sim, mas não acho que ela seja uma das traidoras.",
  ui_story_5051_50511302_30_dialog_content = "Ela era obviamente muito gentil e honesta.",
  ui_story_5051_50511302_31_dialog_content = "Ela também me disse que quer se tornar uma capitã incrível!",
  ui_story_5051_50511302_32_dialog_content = "Seu amigo provavelmente é inocente e não sabia nada sobre a trama.",
  ui_story_5051_50511302_33_dialog_content = "O que vai acontecer se ela for pega?",
  ui_story_5051_50511302_34_dialog_content = "Eu não sei ainda.",
  ui_story_5051_50511302_35_dialog_content = "Mas relaxe, farei o possível para defender os inocentes.",
  ui_story_5051_50511302_36_dialog_content = "Mesmo que o povo dela tenha tentado assassinar você e sua família?",
  ui_story_5051_50511302_37_dialog_content = "Os pecadores merecem ser punidos.",
  ui_story_5051_50511302_38_dialog_content = "Mas não acho que os inocentes devam ser apenas por causa de sua linhagem.",
  ui_story_5051_50511302_39_dialog_content = "Não vamos falar sobre isso agora.",
  ui_story_5051_50511302_40_dialog_content = "Deixe-me preparar o jantar e também um remédio para ressaca para Boaz.",
  ui_story_5051_50511302_41_dialog_content = "Você não está preocupado com o Senhor da Cidade?",
  ui_story_5051_50511302_42_dialog_content = "É claro que sim!",
  ui_story_5051_50511302_43_dialog_content = "Mas estou muito mais confiante no retorno de Daniel com segurança.",
  ui_story_5051_50511302_44_dialog_content = "É por isso que tenho que ter o jantar pronto quando ele voltar!",
  ui_story_5051_50511302_45_dialog_content = "Já estou começando a sentir sua falta, Lady Joshua!",
  ui_story_5051_50511302_46_dialog_content = "Então você deve passar por Lumopolis com mais frequência, Jakine!",
  ui_story_5051_50511302_47_dialog_content = "Verônica e Carleen adoraria ter um novo amigo como você.",
  ui_story_5051_50511302_48_dialog_content = "*funga*",
  ui_story_5051_50511302_49_dialog_content = "Xiu!",
  ui_story_5051_50511302_50_dialog_content = "Boaz e Carleen ainda estão dormindo. Tente não acordá-los!",
  ui_story_5051_50511401_1_dialog_content = "Achei que com a interferência dos Eclipsites, eu tinha Schwartz na mochila.",
  ui_story_5051_50511401_2_dialog_content = "Ainda assim, eu o subestimei.",
  ui_story_5051_50511401_3_dialog_content = "Anunciar ao mundo que está doente foi um estratagema deliberado.",
  ui_story_5051_50511401_4_dialog_content = "Acho que ele já percebeu minha trama.",
  ui_story_5051_50511401_5_dialog_content = "Quando se trata de astúcia, muito poucos em Lumopolis são melhores Schwartz.",
  ui_story_5051_50511401_6_dialog_content = "E eu pensei que tinha me tornado desonesto o suficiente ao longo dos anos...",
  ui_story_5051_50511401_7_dialog_content = "...",
  ui_story_5051_50511401_8_dialog_content = "Como isso pôde acontecer? Mime, por que você despertou o <color=#FFB400>Dragonkin</color>?",
  ui_story_5051_50511401_9_dialog_content = "Isso é imperdoável na Casa Kartima!",
  ui_story_5051_50511401_10_dialog_content = "Não fiz de propósito... Salve-me, mãe!",
  ui_story_5051_50511401_11_dialog_content = "Nunca deixe ninguém saber sobre isso, meu filho.",
  ui_story_5051_50511401_12_dialog_content = "Mas minha cabeça está prestes a explodir...",
  ui_story_5051_50511401_13_dialog_content = "Espere, Mime! Diga-me... Diga-me que você pode suprimir esse poder!",
  ui_story_5051_50511401_14_dialog_content = "A pessoa para liderar a Casa Kartima tem que ser e deve ser você!",
  ui_story_5051_50511401_15_dialog_content = "Dói... Não posso fazer isso!",
  ui_story_5051_50511401_16_dialog_content = "Você deve!",
  ui_story_5051_50511401_17_dialog_content = "Eu te desafio a dizer isso de novo!",
  ui_story_5051_50511401_18_dialog_content = "Mesmo que você tenha me trancado nesta torre oscilante *tosse*",
  ui_story_5051_50511401_19_dialog_content = "Ainda vou repetir as mesmas palavras!",
  ui_story_5051_50511401_20_dialog_content = "Mime, você não pode salvar a família Kartima.",
  ui_story_5051_50511401_21_dialog_content = "Você não é o líder da família!",
  ui_story_5051_50511401_22_dialog_content = "Sim, eu despertei o Dragonkin, e daí?",
  ui_story_5051_50511401_23_dialog_content = "Pois eu sou o líder da Casa Kartima. Isso é um fato simples.",
  ui_story_5051_50511401_X23_dialog_content = "Você despertou o Dragonkin?!",
  ui_story_5051_50511401_X24_dialog_content = "Estou surpreso que você conseguiu esconder a verdade daqueles membros do clã que consideram o Dragonkin um pecado... Você realmente tem alguns truques na manga.",
  ui_story_5051_50511401_X25_dialog_content = "Ainda assim, devo dizer que não é você quem vai salvar a Casa Kartima.",
  ui_story_5051_50511401_X26_dialog_content = "Não importa se você despertou o Dragonkin ou não.",
  ui_story_5051_50511401_X27_dialog_content = "Pena que ninguém vai acreditar na sua profecia.",
  ui_story_5051_50511401_24_dialog_content = "Hahahaha! Tosse...",
  ui_story_5051_50511401_25_dialog_content = "Tenha medo, a garota que salvará os Kartimas logo aparecerá para você.",
  ui_story_5051_50511401_26_dialog_content = "Você está completamente louco.",
  ui_story_5051_50511401_27_dialog_content = "Ninguém mais gosta dessa criança ou está disposto a criá-la.",
  ui_story_5051_50511401_28_dialog_content = "Boa noite, Lorde Mime.",
  ui_story_5051_50511401_29_dialog_content = "Eu sou Sharona.",
  ui_story_5051_50511401_30_dialog_content = "!!!",
  ui_story_5051_50511401_31_dialog_content = "Você pode ser aquele de quem o ancião falou?",
  ui_story_5051_50511401_32_dialog_content = "Eu prometo que não vou causar nenhum problema para você.",
  ui_story_5051_50511401_33_dialog_content = "Eu estou levando esse garoto para dentro.",
  ui_story_5051_50511401_34_dialog_content = "Obrigado, Lorde Mime!",
  ui_story_5051_50511401_35_dialog_content = "Esteja preparado, você nunca será nada aqui.",
  ui_story_5051_50511401_36_dialog_content = "Suspirar...",
  ui_story_5051_50511401_37_dialog_content = "Senhor Mime, Senhor Mime...",
  ui_story_5051_50511401_38_dialog_content = "O que foi?",
  ui_story_5051_50511401_39_dialog_content = "Todos os membros e soldados da Casa Kartima se reuniram.",
  ui_story_5051_50511401_40_dialog_content = "Eu fiz de vocês cúmplices no final...",
  ui_story_5051_50511401_41_dialog_content = "Não temos nenhum problema com isso, meu senhor!",
  ui_story_5051_50511401_42_dialog_content = "Schwartz tem diminuído o poder da Casa Kartima.",
  ui_story_5051_50511401_43_dialog_content = "Se não fosse por você, Schwartz já teria nos arruinado há muito tempo.",
  ui_story_5051_50511401_44_dialog_content = "Tudo bem, chega disso.",
  ui_story_5051_50511401_45_dialog_content = "Não, eu devo falar! Devemos falar!",
  ui_story_5051_50511401_46_dialog_content = "Todos nós vimos as contribuições que você fez para a Casa Kartima.",
  ui_story_5051_50511401_47_dialog_content = "Estamos dispostos a te seguir até o fim sem arrependimentos!",
  ui_story_5051_50511401_48_dialog_content = "Schwartz sabia que todos se opunham ao envio de reforços para Umbraton...",
  ui_story_5051_50511401_49_dialog_content = "No entanto, ele tentou forçá-lo a fazer um juramento de apoio a essa mesma ideia na cerimônia de hoje.",
  ui_story_5051_50511401_50_dialog_content = "Isso claramente nos tornou o alvo de outras casas para promover sua própria ambição.",
  ui_story_5051_50511401_51_dialog_content = "Comparado a morrer nas mãos de Eclipsites pelo interesse de Schwartz...",
  ui_story_5051_50511401_52_dialog_content = "Estamos consideravelmente mais dispostos a morrer pela Casa Kartima!",
  ui_story_5051_50511401_53_dialog_content = "<size=45>Morra pela Casa Kartima! Morra pela Casa Kartima! Morra pela Casa Kartima!</size>",
  ui_story_5051_50511401_54_dialog_content = "Maravilhoso! Mas discordo de um dos pontos.",
  ui_story_5051_50511401_55_dialog_content = "O resultado desta batalha ainda não foi determinado!",
  ui_story_5051_50511401_56_dialog_content = "Você está correto, meu senhor!",
  ui_story_5051_50511401_57_dialog_content = "Estamos prontos para segui-lo e recuperar a glória perdida de Kartimas!",
  ui_story_5051_50511401_58_dialog_content = "Estamos totalmente preparados e aguardando seu pedido.",
  ui_story_5051_50511401_59_dialog_content = "Juramos defender a honra da Casa Kartima até a morte!",
  ui_story_5051_50511401_60_dialog_content = "<size=45>Defenda a honra de Kartima! Defenda a honra de Kartima! Defenda a honra de Kartima!</size>",
  ui_story_5051_50511401_61_dialog_content = "Vamos!",
  ui_story_5051_50511401_62_dialog_content = "Agora, deixe-me revelar nosso reforço final.",
  ui_story_5051_50511401_63_dialog_content = "Reforços?",
  ui_story_5051_50511401_64_dialog_content = "\"O dragão voando pelo céu, o parceiro eterno de Kartima.\"",
  ui_story_5051_50511401_65_dialog_content = "\"Abra suas asas e perfure a noite sem fim.\"",
  ui_story_5051_50511401_66_dialog_content = "\"Venha até mim.\"",
  ui_story_5051_50511401_67_dialog_content = "\"Venha até nós.\"",
  ui_story_5051_50511401_68_dialog_content = "\"A Casa Kartima nunca esquece nosso pacto.\"",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>Rugido-!</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "Essa voz...",
  ui_story_5051_50511401_71_dialog_content = "Você acabou de convocar o <color=#FFB400>Dragão</color>, meu Senhor?!",
  ui_story_5051_50511401_72_dialog_content = "O dragão sempre foi o aliado mais leal da Casa Kartima.",
  ui_story_5051_50511401_73_dialog_content = "Algumas pessoas invejaram nosso poder e convenceram nossos antepassados de que os dragões são presságios do mal.",
  ui_story_5051_50511401_74_dialog_content = "Algumas pessoas? Isso poderia ser casa Schwartz...?",
  ui_story_5051_50511401_75_dialog_content = "<size=45>Vem Ganon! Venha para seus amigos e familiares!</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>Rosnar!</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "Agora, não precisamos mais nos preocupar com hereges.",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>Rugido!</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "Ouçam, membros da Casa Kartima!",
  ui_story_5051_50511401_80_dialog_content = "O dragão voltou!",
  ui_story_5051_50511401_81_dialog_content = "Isso nos ajudará a dominar Lumopolis!",
  ui_story_5051_50511401_82_dialog_content = "Viva o dragão!",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>Rugido-!!!</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>Enquanto isso em Umbraton</color>",
  ui_story_5051_50511401_85_dialog_content = "Você ouviu isso?",
  ui_story_5051_50511401_86_dialog_content = "Eu pensei que algo estava errado com minha orelha!",
  ui_story_5051_50511401_87_dialog_content = "Não pode ser os Eclipsites atacando de novo, pode?",
  ui_story_5051_50511401_88_dialog_content = "Pare de falar besteira e vá para casa!",
  ui_story_5051_50511401_89_dialog_content = "Sim, vamos aguardar nosso destino em casa.",
  ui_story_5051_50511401_90_dialog_content = "Umbraton está mais úmido do que eu me lembrava.",
  ui_story_5051_50511401_91_dialog_content = "Olhando para Lumopolis deste ponto de vista...",
  ui_story_5051_50511401_92_dialog_content = "Parece muito diferente.",
  ui_story_5051_50511401_93_dialog_content = "As noites lá em cima parecem mais frias do que aqui.",
  ui_story_5051_50511401_94_dialog_content = "Esse rugido veio de um Eclipsite?",
  ui_story_5051_50511401_95_dialog_content = "Não, não é o Eclipse.",
  ui_story_5051_50511401_96_dialog_content = "O que mais poderia ser, então?",
  ui_story_5051_50511401_97_dialog_content = "Olha, está chegando.",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>Rugido-!</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "Um dragão voador?",
  ui_story_5051_50511401_100_dialog_content = "Sim, eles estão realmente cegos pelo ódio do dragão maligno.",
  ui_story_5051_50511401_101_dialog_content = "A linhagem Kartima está destinada a ser vinculada para sempre a essa antiga barganha?",
  ui_story_5051_50511401_102_dialog_content = "O dragão vai estar aqui em breve!",
  ui_story_5051_50511401_103_dialog_content = "Fique para trás, Verônica!",
  ui_story_5051_50511401_104_dialog_content = "Deixe-me verificar do que esse dragão é capaz.",
  ui_story_5051_50511401_105_dialog_content = "É enorme em tamanho, capaz de cuspir fogo.",
  ui_story_5051_50511401_106_dialog_content = "A fim de evitar ferimentos graves, a melhor opção é atingir primeiro seu ponto vulnerável.",
  ui_story_5051_50511401_107_dialog_content = "E o ponto vulnerável deste dragão é...",
  ui_story_5051_50511401_108_dialog_content = "Eu sei o que é, naturalmente.",
  ui_story_5051_50511401_109_dialog_content = "Ele saiu antes que você pudesse terminar.",
  ui_story_5051_50511401_110_dialog_content = "Vejo que esta batalha vai levar algum tempo.",
  ui_story_5051_50511401_111_dialog_content = "Você não conhecia o ponto fraco do dragão?",
  ui_story_5051_50511401_112_dialog_content = "Ou você não conseguiu acertar na primeira tentativa?",
  ui_story_5051_50511401_113_dialog_content = "...",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5051_50511401_115_dialog_content = "O vento está aumentando. Isso é diferente do que eu lembrava.",
  ui_story_5051_50511401_116_dialog_content = "(Ele apenas ignorou seletivamente essa pergunta?)",
  ui_story_5051_50511401_117_dialog_content = "Se pudermos aproveitar a direção do vento, talvez...",
  ui_story_5051_50511401_118_dialog_content = "A batalha pode terminar cedo.",
  ui_story_5051_50511401_119_dialog_content = "Ha—!",
  ui_story_5051_50511401_120_dialog_content = "Luz da Noite Branca!",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>Graw!</anim>",
  ui_story_5051_50511401_122_dialog_content = "(Jovem Schwartz atingiu o dragão precisamente na garganta para impedi-lo de cuspir fogo temporariamente...)",
  ui_story_5051_50511401_123_dialog_content = "(Essa é a sua fraqueza, no entanto?)",
  ui_story_5051_50511401_124_dialog_content = "(Eu realmente não posso dizer, mas parece haver uma figura nas costas do dragão.)",
  ui_story_5051_50511401_125_dialog_content = "É Mime Kartima!",
  ui_story_5051_50511401_126_dialog_content = "O capitão dos cavaleiros que encontramos quando estávamos entrando na cidade?",
  ui_story_5051_50511401_127_dialog_content = "Heh, isso é tudo que o dragão pode fazer?",
  ui_story_5051_50511401_128_dialog_content = "Vejo que não preciso lutar com força total.",
  ui_story_5051_50511401_129_dialog_content = "Considere-se sortudo por resistir ao primeiro ataque.",
  ui_story_5051_50511401_130_dialog_content = "Não confunda sorte com bravura, estimado Senhor da Cidade.",
  ui_story_5051_50511401_131_dialog_content = "Você escapou fortuitamente da chama de Ganon, como se você fortuitamente se tornasse o Senhor da Cidade.",
  ui_story_5051_50511401_132_dialog_content = "Ganon? Você nomeou seu dragão, eu vejo.",
  ui_story_5051_50511401_133_dialog_content = "Este é um movimento perigoso, Mime.",
  ui_story_5051_50511401_134_dialog_content = "Você ficará incrivelmente triste quando ele for morto.",
  ui_story_5051_50511401_135_dialog_content = "Tu falas demais!",
  ui_story_5051_50511401_136_dialog_content = "Carga, Ganon!",
  ui_story_5051_50511401_137_dialog_content = "Entregue sua chama mais feroz a este homem diante de você!",
  ui_story_5051_50511401_138_dialog_content = "Um presente seu para o meu ombro é o bastante. Eu não deveria aceitar outro.",
  ui_story_5051_50511401_139_dialog_content = "No entanto, permita-me retribuir!",
  ui_story_5051_50511401_140_dialog_content = "Noites efêmeras e dias sem fim!",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5051_50511401_142_dialog_content = "Em frente!",
  ui_story_5051_50511401_143_dialog_content = "Os rebeldes estão atacando...",
  ui_story_5051_50511401_144_dialog_content = "Todas as mãos, ouçam!",
  ui_story_5051_50511401_145_dialog_content = "Prepare-se para a batalha!",
  ui_story_5051_50511401_146_dialog_content = "...",
  ui_story_5051_50511401_147_dialog_content = "Você também está lutando, Mia?",
  ui_story_5051_50511401_148_dialog_content = "Se possível, não quero manchar minha arma com o sangue do meu povo...",
  ui_story_5051_50511401_149_dialog_content = "Por que fizemos a escolha naquela época, padre?",
  ui_story_5051_50511401_150_dialog_content = "Porque eles queriam manchar suas armas com nosso sangue.",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_5051_50511402_2_dialog_content = "Não, Ganon!",
  ui_story_5051_50511402_3_dialog_content = "Isso não é real...",
  ui_story_5051_50511402_4_dialog_content = "Não é para acontecer assim!",
  ui_story_5051_50511402_5_dialog_content = "(Jovem Schwartz de fato derrotou o dragão aproveitando o vento.)",
  ui_story_5051_50511402_6_dialog_content = "(Esta batalha terminou mais rápido do que eu imaginava.)",
  ui_story_5051_50511402_7_dialog_content = "Mime Kartima!",
  ui_story_5051_50511402_8_dialog_content = "Como capitão dos Cavaleiros de Lumopolis, você deve estar determinado a defender a cidade.",
  ui_story_5051_50511402_9_dialog_content = "Mas você escolheu trair Lumopolis e a fé como um cavaleiro.",
  ui_story_5051_50511402_10_dialog_content = "Você causou dano e sofrimento irreparáveis ao povo de Lumopolis.",
  ui_story_5051_50511402_11_dialog_content = "Avante, Noite Branca!",
  ui_story_5051_50511402_12_dialog_content = "Suas ações constituíram traição.",
  ui_story_5051_50511402_13_dialog_content = "Doravante, você está para sempre destituído de todos os títulos e postagens.",
  ui_story_5051_50511402_14_dialog_content = "Você está condenado a aguardar o julgamento final do Tribunal de Justiça na prisão.",
  ui_story_5051_50511402_15_dialog_content = "Ei, por que esperar...",
  ui_story_5051_50511402_16_dialog_content = "Apenas me mate agora, Schwartz!",
  ui_story_5051_50511402_17_dialog_content = "Você não deseja ver seus parentes novamente?",
  ui_story_5051_50511402_18_dialog_content = "Você...",
  ui_story_5051_50511402_19_dialog_content = "Tudo isso é minha culpa. Ninguém mais tem nada a ver com isso!",
  ui_story_5051_50511402_20_dialog_content = "Eu os coagi a atacar...",
  ui_story_5051_50511402_21_dialog_content = "Se ainda lhe resta um fio de decência, poupe as crianças e os idosos!",
  ui_story_5051_50511402_22_dialog_content = "Neste ponto, a decisão não cabe a mim.",
  ui_story_5051_50511402_23_dialog_content = "Salve seu pedido para o tribunal.",
  ui_story_5051_50511402_24_dialog_content = "O Tribunal de Justiça fará um julgamento justo.",
  ui_story_5051_50511402_25_dialog_content = "Hehehe...",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>Hahaha!</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "Na verdade, não sou eu quem vai salvar a Casa Kartima...",
  ui_story_5051_50511402_28_dialog_content = "Se a anciã estivesse correta, ela completaria a missão para mim!",
  ui_story_5051_50511402_29_dialog_content = "Foi você quem acabou de destruir a Casa Kartima.",
  ui_story_5051_50511402_30_dialog_content = "Se você jurasse publicamente reforçar Umbraton comigo como combinamos anteriormente...",
  ui_story_5051_50511402_31_dialog_content = "Talvez o final fosse diferente.",
  ui_story_5051_50511402_32_dialog_content = "Você...!",
  ui_story_5051_50511402_33_dialog_content = "Sem chance!",
  ui_story_5051_50511402_34_dialog_content = "Atenção!!",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5051_50511402_36_dialog_content = "Err...",
  ui_story_5051_50511402_37_dialog_content = "(Mime ainda tentou atacar mesmo sabendo que era inútil...)",
  ui_story_5051_50511402_38_dialog_content = "Admiro sua coragem, Mime Kartima.",
  ui_story_5051_50511402_39_dialog_content = "Assuma para mim, Sra. Rot.",
  ui_story_5051_50511402_40_dialog_content = "eu preciso verificar Carleen. Espere por mim na sala de conferências.",
  ui_story_5051_50511402_41_dialog_content = "Sim!",
  ui_story_5051_50511501_1_dialog_content = "Estou de volta, Josué.",
  ui_story_5051_50511501_2_dialog_content = "Daniel...",
  ui_story_5051_50511501_3_dialog_content = "Deixe-me ver... A ferida abriu? Alguma lesão nova?",
  ui_story_5051_50511501_4_dialog_content = "Relaxe, Josué. Eu disse que ficaria bem.",
  ui_story_5051_50511501_5_dialog_content = "A propósito, como é Carleen?",
  ui_story_5051_50511501_6_dialog_content = "O médico esteve aqui e disse que ela ficaria bem depois de alguns dias de repouso.",
  ui_story_5051_50511501_7_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5051_50511501_8_dialog_content = "A ceia está pronta para você participar.",
  ui_story_5051_50511501_9_dialog_content = "Não, ainda tenho negócios a tratar.",
  ui_story_5051_50511501_10_dialog_content = "Você deve se entregar cedo.",
  ui_story_5051_50511501_11_dialog_content = "Você esteve ocupado o dia todo, Daniel. Você é quem deve se entregar.",
  ui_story_5051_50511501_12_dialog_content = "Devo consultar o Conselho de Anciãos e o Tribunal de Justiça sobre o assunto com a Casa Kartima o mais rápido possível.",
  ui_story_5051_50511501_13_dialog_content = "Desculpe, Josué.",
  ui_story_5051_50511501_14_dialog_content = "Da próxima vez, depois que eu terminar com isso, nós quatro nos sentaremos para um jantar em família, certo?",
  ui_story_5051_50511501_15_dialog_content = "Daniel, você pode me dizer o que eles vão fazer com a Casa Kartima?",
  ui_story_5051_50511501_16_dialog_content = "Nem se preocupe com isso. Os Kartimas terão o que merecem.",
  ui_story_5051_50511501_17_dialog_content = "E aqueles que nada sabiam disso?",
  ui_story_5051_50511501_18_dialog_content = "Será que eles vão se envolver nisso também?",
  ui_story_5051_50511501_19_dialog_content = "Não se esqueça, Josué.",
  ui_story_5051_50511501_20_dialog_content = "Hoje, aquelas pessoas da Casa Kartima apontaram lâminas frias para nós, para nossas queridas filhas.",
  ui_story_5051_50511501_21_dialog_content = "Eles nunca consideraram nossas filhas inocentes quando nos traíram.",
  ui_story_5051_50511501_22_dialog_content = "Mas...",
  ui_story_5051_50511501_23_dialog_content = "Deixa eu te fazer uma pergunta, Daniel.",
  ui_story_5051_50511501_24_dialog_content = "Você descobriu sobre a trama de Kartima antes do tempo?",
  ui_story_5051_50511501_25_dialog_content = "Quem te contou?",
  ui_story_5051_50511501_26_dialog_content = "É você, Daniel, você não tem se comportado ultimamente.",
  ui_story_5051_50511501_27_dialog_content = "Pare com a teoria da conspiração, certo?",
  ui_story_5051_50511501_28_dialog_content = "Mas como você sabia que haveria duas ondas de Eclipsites?",
  ui_story_5051_50511501_29_dialog_content = "Também pensei nisso...",
  ui_story_5051_50511501_30_dialog_content = "Quando estávamos praticando, você podia sentir um pequeno movimento a cinquenta metros de distância.",
  ui_story_5051_50511501_31_dialog_content = "No entanto, você não conseguiu reagir a tempo ao ataque flagrantemente óbvio do assassino?",
  ui_story_5051_50511501_32_dialog_content = "Você fez isso... <color=#FFB400>de propósito</color>?",
  ui_story_5051_50511501_33_dialog_content = "Embora eu não conseguisse entender por que você fez isso.",
  ui_story_5051_50511501_34_dialog_content = "É para angariar a simpatia do público pela lesão e solidificar o caso contra Kartimas?",
  ui_story_5051_50511501_35_dialog_content = "Não é o que você pensa.",
  ui_story_5051_50511501_36_dialog_content = "Se eu conhecesse os planos deles, por que permitiria que você e nossos filhos viessem?",
  ui_story_5051_50511501_37_dialog_content = "!!!",
  ui_story_5051_50511501_38_dialog_content = "Com Carleen e eu ao seu lado, os rebeldes não desconfiariam de nada e seguiriam com seu plano...",
  ui_story_5051_50511501_39_dialog_content = "Você nos tratou como <color=#FFB400>peões</color>!",
  ui_story_5051_50511501_40_dialog_content = "...",
  ui_story_5051_50511501_41_dialog_content = "Eu sou o Senhor da Cidade de Lumopolis, decidindo o futuro desta cidade flutuante.",
  ui_story_5051_50511501_42_dialog_content = "Para isso, vou transformar até a mim mesmo em uma peça de xadrez.",
  ui_story_5051_50511501_43_dialog_content = "Essa é a obrigação que temos, Joshua.",
  ui_story_5051_50511501_44_dialog_content = "Eu sei que tudo que você fez foi para lutar contra os Eclipsites.",
  ui_story_5051_50511501_45_dialog_content = "Mas por que você não me contou?",
  ui_story_5051_50511501_46_dialog_content = "Talvez possamos bolar um plano perfeito.",
  ui_story_5051_50511501_47_dialog_content = "Não vou reclamar de você me usar como peão.",
  ui_story_5051_50511501_48_dialog_content = "Mas como você poderia realmente usar nossos filhos também como peças de xadrez?",
  ui_story_5051_50511501_49_dialog_content = "E se Carleen pegou-",
  ui_story_5051_50511501_50_dialog_content = "Eu não vou deixar isso acontecer.",
  ui_story_5051_50511501_51_dialog_content = "Na verdade, ela está bem agora, não está?",
  ui_story_5051_50511501_52_dialog_content = "Isso foi pura sorte, mas e se?",
  ui_story_5051_50511501_53_dialog_content = "Se houver uma próxima vez, promete que me avisa antes?",
  ui_story_5051_50511501_54_dialog_content = "A política da vida real é milhares de vezes mais complicada do que nos livros.",
  ui_story_5051_50511501_55_dialog_content = "Eu te amo Josué...",
  ui_story_5051_50511501_56_dialog_content = "É por isso que não desejo envolvê-lo no redemoinho imundo.",
  ui_story_5051_50511501_57_dialog_content = "Não foi isso que você me disse quando estávamos na escola.",
  ui_story_5051_50511501_58_dialog_content = "Você disse que vamos mudar Lumopolis juntos.",
  ui_story_5051_50511501_59_dialog_content = "E agora você se recusa a confiar em mim.",
  ui_story_5051_50511501_60_dialog_content = "Eu sempre confiei em você. Não tenho nenhum problema em deixar você comandar a família.",
  ui_story_5051_50511501_61_dialog_content = "Da mesma forma, você deve confiar em minhas decisões na arena política.",
  ui_story_5051_50511501_62_dialog_content = "Sacrificar uma família inteira para abrir caminho para sua dominação política.",
  ui_story_5051_50511501_63_dialog_content = "Se esse é o seu jogo final...",
  ui_story_5051_50511501_64_dialog_content = "Acho que não sei mais quem você é, Daniel...",
  ui_story_5051_50511501_65_dialog_content = "Você está começando a fazer o que for preciso para garantir seu lugar como Lorde da Cidade.",
  ui_story_5051_50511501_66_dialog_content = "Não, não é apenas o que for preciso.",
  ui_story_5051_50511501_67_dialog_content = "Você tem um coração mais gélido do que a neve nos picos das Terras do Norte!",
  ui_story_5051_50511501_68_dialog_content = "Veronica se tornou uma esquisitice aos olhos do público por sua causa...",
  ui_story_5051_50511501_69_dialog_content = "Carleen provavelmente perderá a vida um dia por sua causa também...",
  ui_story_5051_50511501_70_dialog_content = "Eu também vou te deixar e sumir do mundo...",
  ui_story_5051_50511501_71_dialog_content = "Josué... Josué!",
  ui_story_5051_50511501_72_dialog_content = "Meu Josué!",
  ui_story_5051_50511501_73_dialog_content = "Por quê?",
  ui_story_5051_50511501_74_dialog_content = "<size=45>Por que você me deixou?!</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>Suspiro... Suspiro... Suspiro...</anim>",
  ui_story_5051_50511501_76_dialog_content = "Você está bem? Há algo de errado?",
  ui_story_5051_50511501_77_dialog_content = "Joshua!",
  ui_story_5051_50511501_78_dialog_content = "Qual é o problema, Sr. Soroz?",
  ui_story_5051_50511501_79_dialog_content = "Seu aperto está cortando a mão de Lady Joshua, PAI.",
  ui_story_5051_50511501_80_dialog_content = "Sinto muito.",
  ui_story_5051_50511501_X80_dialog_content = "Por alguma razão, isso me lembra dos pesadelos que tenho com frequência.",
  ui_story_5051_50511501_81_dialog_content = "Eu provavelmente preciso de mais descanso nesta velhice...",
  ui_story_5051_50511501_82_dialog_content = "Por favor, fique à vontade. A refeição será servida em breve.",
  ui_story_5051_50511501_83_dialog_content = "Você é um grande anfitrião, Joshua.",
  ui_story_5051_50511501_84_dialog_content = "O jantar estará pronto em breve. Por que não vamos todos para o refeitório?",
  ui_story_5051_50511501_85_dialog_content = "Eu não, ainda tenho negócios a tratar.",
  ui_story_5051_50511501_86_dialog_content = "Certifique-se de chegar cedo depois de terminar, todos vocês.",
  ui_story_5051_50511501_87_dialog_content = "Você esteve ocupado o dia todo, Daniel. Você é quem deve se entregar.",
  ui_story_5051_50511501_88_dialog_content = "...",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName, faça algo para distraí-los, rápido!</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>O que? Por que?</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>Caso contrário, veremos uma briga que não desejo testemunhar novamente...</size>",
  ui_story_5051_50511501_92_dialog_content = "Devo consultar o Conselho de Anciãos e o Tribunal de Justiça sobre o assunto com a Casa Kartima o mais rápido possível.",
  ui_story_5051_50511501_93_dialog_content = "Desculpe, Josué.",
  ui_story_5051_50511501_94_dialog_content = "Da próxima vez, depois que eu terminar com isso, nós quatro nos sentaremos para um jantar em família, certo?",
  ui_story_5051_50511501_95_dialog_content = "Sim, acho uma ótima ideia!",
  ui_story_5051_50511501_96_dialog_content = "Hã?",
  ui_story_5051_50511501_97_dialog_content = "Quem deve trabalhar deve trabalhar, quem deve descansar deve descansar.",
  ui_story_5051_50511501_98_dialog_content = "Acho... que é melhor para todos.",
  ui_story_5051_50511501_99_dialog_content = "Sim, as crianças e eu estamos famintos, devido às atividades de hoje.",
  ui_story_5051_50511501_100_dialog_content = "Não se apresse e descanse um pouco, Sr. Soroz. Podemos conversar outro dia.",
  ui_story_5051_50511501_101_dialog_content = "Isso é tudo.",
  ui_story_5051_50511501_102_dialog_content = "...",
  ui_story_5051_50511501_103_dialog_content = "E ele vai embora assim.",
  ui_story_5051_50511501_104_dialog_content = "Desculpe, Sr. Soroz, mas preciso de alguns minutos.",
  ui_story_5051_50511501_105_dialog_content = "A ceia deve estar pronta em breve.",
  ui_story_5051_50511501_106_dialog_content = "Obrigado.",
  ui_story_5051_50511501_107_dialog_content = "É impossível para mim imaginar você discutindo com alguém tão doce quanto Lady Joshua.",
  ui_story_5051_50511501_108_dialog_content = "Você e mamãe... discutiram neste dia?",
  ui_story_5051_50511501_109_dialog_content = "...",
  ui_story_5051_50511501_110_dialog_content = "Você é tão covarde para admitir o que fez?",
  ui_story_5051_50511501_111_dialog_content = "Calebe? De onde você veio?",
  ui_story_5051_50511501_112_dialog_content = "Tio?",
  ui_story_5051_50511501_113_dialog_content = "ouvi Jakine fugir e deixar você para trás, Caleb. Quando você vai mostrar alguma maturidade?",
  ui_story_5051_50511501_114_dialog_content = "Não saia pela tangente, Senhor da Cidade.",
  ui_story_5051_50511501_115_dialog_content = "Você realmente não vai admitir o que fez?",
  ui_story_5051_50511501_116_dialog_content = "Então deixe-me refrescar sua memória.",
  ui_story_5051_50511501_117_dialog_content = "Por causa dessa discussão, minha irmã deixou Castle Schwartz com Carleen.",
  ui_story_5051_50511501_118_dialog_content = "Vocês dois praticamente nunca mais se falaram ou fizeram uma refeição em família juntos...",
  ui_story_5051_50511501_119_dialog_content = "Até que minha irmã trouxe a moribunda Veronica de volta do campo de batalha.",
  ui_story_5051_50511501_120_dialog_content = "Você fingiu estar enterrado na luta contra os Eclipsitas, quando na verdade, não queria enfrentá-la...",
  ui_story_5051_50511501_121_dialog_content = "Então, por causa de suas ambições políticas, você enviou a Veronica ferida para aquele laboratório em Illumina.",
  ui_story_5051_50511501_122_dialog_content = "Sem saber que a instalação era administrada por lunáticos impiedosos.",
  ui_story_5051_50511501_123_dialog_content = "Minha irmã mais uma vez resgatou Veronica do laboratório, mas ela estava gravemente ferida e ficou acamada...",
  ui_story_5051_50511501_124_dialog_content = "Estou certo, cunhado?",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>Laboratório Illumina</color>... Minha cabeça, dói.",
  ui_story_5051_50511501_126_dialog_content = "Sentar-se, Mia. Pare de pensar no passado.",
  ui_story_5051_50511501_127_dialog_content = "...",
  ui_story_5051_50511501_128_dialog_content = "Para onde você fugiu, Caleb?",
  ui_story_5051_50511501_129_dialog_content = "Você está desaparecido há um dia inteiro. Isso me fez pensar que você não queria ir embora!",
  ui_story_5051_50511501_130_dialog_content = "Eu estive aqui o tempo todo, ela simplesmente não me reconheceu.",
  ui_story_5051_50511501_131_dialog_content = "Eu não queria que minha presença a distraísse...",
  ui_story_5051_50511501_132_dialog_content = "Mas sim, eu não posso mais ficar.",
  ui_story_5051_50511501_133_dialog_content = "Me tire daqui, Jakine!",
  ui_story_5051_50511501_134_dialog_content = "Isso é o mais direto possível para alguém que está desaparecido.",
  ui_story_5051_50511501_135_dialog_content = "Bem, todos estão aqui, não deveríamos sair agora?",
  ui_story_5051_50511501_136_dialog_content = "Você não disse que tínhamos que deixar o Cristal da Memória Eterna rápido ou haveria problemas?",
  ui_story_5051_50511501_137_dialog_content = "Sim, eu disse isso.",
  ui_story_5051_50511501_138_dialog_content = "Prontos para sair, pessoal?",
  ui_story_5051_50511501_139_dialog_content = "Mamãe ainda nos espera para o jantar...",
  ui_story_5051_50511501_140_dialog_content = "Ainda há tempo. Podemos ficar um pouco.",
  ui_story_5051_50511501_141_dialog_content = "Mas você não estava nos incitando a sair antes, City Lord?",
  ui_story_5051_50511501_142_dialog_content = "Isso porque estávamos todos em perigo.",
  ui_story_5051_50511501_143_dialog_content = "Mas agora a maior ameaça já passou.",
  ui_story_5051_50511501_144_dialog_content = "E...",
  ui_story_5051_50511501_145_dialog_content = "(Talvez Caleb esteja certo. Essa briga foi o começo do fim.)",
  ui_story_5051_50511501_146_dialog_content = "(Enquanto ganhei o apoio de todos os nobres em Lumopolis naquele dia, feri profundamente meu amado.)",
  ui_story_5051_50511501_147_dialog_content = "Pai?",
  ui_story_5051_50511501_148_dialog_content = "Sem falar que se formos embora agora...",
  ui_story_5051_50511501_149_dialog_content = "Joshua terá que passar uma noite estressante sozinho como antes.",
  ui_story_5051_50511501_150_dialog_content = "Por que você está tentando convencer com seu ato, Schwartz?",
  ui_story_5051_50511501_151_dialog_content = "Eu sei que você sempre me odiou por causa do que aconteceu com Joshua, Caleb.",
  ui_story_5051_50511501_152_dialog_content = "É tarde demais para eu consertar os erros do passado.",
  ui_story_5051_50511501_153_dialog_content = "Eu entendo a animosidade que você sente por mim.",
  ui_story_5051_50511501_154_dialog_content = "Se eu tiver outra chance, não vou deixá-la...",
  ui_story_5051_50511501_155_dialog_content = "Hehe, não adianta falar sobre isso agora.",
  ui_story_5051_50511501_156_dialog_content = "Este mundo inteiro é falso até o âmago...",
  ui_story_5051_50511501_157_dialog_content = "Expiar aqui não vai mudar nada!",
  ui_story_5051_50511501_158_dialog_content = "U-tio...",
  ui_story_5051_50511501_159_dialog_content = "Eu gostaria de dizer adeus à mãe",
  ui_story_5051_50511501_160_dialog_content = "Eu sei que este mundo não é real, mas as emoções certamente são.",
  ui_story_5051_50511501_161_dialog_content = "Por favor, dê-nos este precioso último momento.",
  ui_story_5051_50511501_162_dialog_content = "A-Na verdade, eu também gostaria de me despedir de alguém.",
  ui_story_5051_50511501_163_dialog_content = "Ainda temos tempo e nenhuma ameaça no momento...",
  ui_story_5051_50511501_164_dialog_content = "Então, por que todos não vão se despedir?",
  ui_story_5051_50511501_165_dialog_content = "Afinal, eles podem não nos reconhecer na próxima vez que viermos.",
  ui_story_5051_50511501_166_dialog_content = "Vocês...!",
  ui_story_5051_50511501_167_dialog_content = "Sente-te acompanhando-me para a minha despedida, PlayerName?",
  ui_story_5051_50511501_168_dialog_content = "Eu sou apenas um estranho para ela agora. Não será adequado sem a sua presença.",
  ui_story_5051_50511501_169_dialog_content = "Mas como você vai dizer o que quer dizer quando deveria ser meu pai?",
  ui_story_5051_50511501_170_dialog_content = "Se ao menos Joshua pudesse reconhecê-lo...",
  ui_story_5051_50511501_171_dialog_content = "Ei, Jakine, você não pode controlar o cristal?",
  ui_story_5051_50511501_172_dialog_content = "Alguma maneira de fazer Joshua reconhecer nosso Senhor da Cidade?",
  ui_story_5051_50511501_173_dialog_content = "Bom, não que não tenha como...",
  ui_story_5051_50511501_174_dialog_content = "É que nunca experimentei antes e não quero outra confusão.",
  ui_story_5051_50511501_175_dialog_content = "Está tudo certo. Tente.",
  ui_story_5051_50511501_176_dialog_content = "Você confia em mim, Senhor da Cidade?",
  ui_story_5051_50511501_177_dialog_content = "Acho que estou sem desculpas. Vou ajudá-lo a limpar o ar!",
  ui_story_5051_50511501_178_dialog_content = "No entanto...",
  ui_story_5051_50511501_179_dialog_content = "Dê-me tempo para ler meu livro primeiro! Heehee.",
  ui_story_5051_50511501_180_dialog_content = "Ahem, isso vai funcionar, meu senhor?",
  ui_story_5051_50511501_181_dialog_content = "Eu me abaixei e me esquivei por mais de uma década, meu jovem...",
  ui_story_5051_50511501_182_dialog_content = "Para mim, vir aqui pode não ser mera coincidência.",
  ui_story_5051_50511501_183_dialog_content = "Talvez o Deus da Luz esteja me guiando.",
  ui_story_5051_50511501_184_dialog_content = "É hora de enfrentar minha covardia.",
  ui_story_5051_50511501_185_dialog_content = "Devo lembrá-lo de que a ilusão durará pouco tempo, meu senhor.",
  ui_story_5051_50511501_186_dialog_content = "Certifique-se de voltar antes que o tempo acabe!",
  ui_story_5051_50511501_187_dialog_content = "Tô pronto.",
  ui_story_5051_50511501_188_dialog_content = "Deixe-me começar, então!",
  ui_story_5051_50511501_189_dialog_content = "Mutação! Mutação! Mutação!",
  ui_story_5051_50511501_190_dialog_content = "Por favor mude Daniel Schwartz de volta ao seu dia mais jovem!",
  ui_story_5051_50511501_191_dialog_content = "Abracadabra!",
  ui_story_5051_50511501_192_dialog_content = "<color=#828282>Bam!</color>",
  ui_story_5051_50511501_193_dialog_content = "Uau!",
  ui_story_5051_50511501_194_dialog_content = "O que está acontecendo? Por que você está tão surpreso, PlayerName?",
  ui_story_5051_50511501_195_dialog_content = "Você certamente parecia... memorável quando era jovem.",
  ui_story_5051_50511501_196_dialog_content = "Tadinha...",
  ui_story_5051_50511501_197_dialog_content = "Uh, como você mudou City Lord para se parecer com Judge Jr.?",
  ui_story_5051_50511501_198_dialog_content = "Judge Jr.?!",
  ui_story_5051_50511501_199_dialog_content = "Ahem... Acho que fiquei muito empolgado e não imaginei como era o seu eu jovem em minha mente...",
  ui_story_5051_50511501_200_dialog_content = "Não conhecemos seu eu mais jovem apenas alguns minutos atrás?",
  ui_story_5051_50511501_201_dialog_content = "Ah, isso mesmo!",
  ui_story_5051_50511501_202_dialog_content = "Isso deve facilitar. Deixe-me tentar de novo!",
  ui_story_5051_50511501_203_dialog_content = "Mutação! Mutação! Mutação!",
  ui_story_5051_50511501_204_dialog_content = "Por favor mude Daniel Schwartz de volta ao seu dia mais jovem!",
  ui_story_5051_50511501_205_dialog_content = "Abracadabra!",
  ui_story_5051_50511501_206_dialog_content = "<color=#828282>Bam!</color>",
  ui_story_5051_50511501_207_dialog_content = "É você na porta, guarda?",
  ui_story_5051_50511501_208_dialog_content = "A ceia está pronta. Você se importaria de informar a todos para mim?",
  ui_story_5051_50511501_209_dialog_content = "...",
  ui_story_5051_50511501_210_dialog_content = "Guarda?",
  ui_story_5051_50511501_211_dialog_content = "É você?",
  ui_story_5051_50511501_212_dialog_content = "...",
  ui_story_5051_50511501_213_dialog_content = "<size=30>Desculpe.</size>",
  ui_story_5051_50511501_214_dialog_content = "O que você disse?",
  ui_story_5051_50511501_215_dialog_content = "Nenhuma coisa.",
  ui_story_5051_50511501_216_dialog_content = "Você acabou de pedir desculpas, Daniel?",
  ui_story_5051_50511501_217_dialog_content = "Joshua...",
  ui_story_5051_50511501_218_dialog_content = "É bom que você esteja de volta.",
  ui_story_5051_50511501_219_dialog_content = "Você deveria voltar para casa quando estiver exausto.",
  ui_story_5051_50511501_220_dialog_content = "Estou bem. E as crianças e eu ficaremos com você, sempre.",
  ui_story_5051_50511501_221_dialog_content = "...",
  ui_story_5051_50511501_222_dialog_content = "Faça uma pausa enquanto peço a alguém que arrume outro lugar na mesa.",
  ui_story_5051_50511501_223_dialog_content = "...",
  ui_story_5051_50511501_224_dialog_content = "Como vou fazer alguma coisa com você me segurando, Daniel?",
  ui_story_5051_50511501_225_dialog_content = "Eu tenho muito que eu quero te dizer.",
  ui_story_5051_50511501_226_dialog_content = "Então você finalmente se lembrou de que há mais alguém na família que vai ouvir suas queixas?",
  ui_story_5051_50511501_227_dialog_content = "O que é, e tem que ser agora?",
  ui_story_5051_50511501_228_dialog_content = "Sim.",
  ui_story_5051_50511501_229_dialog_content = "Tudo bem, acho que todo mundo vai ter que matar a fome um pouco mais.",
  ui_story_5051_50511501_230_dialog_content = "Vamos ouvir o que você tem a dizer!",
  ui_story_5051_50511501_231_dialog_content = "...",
  ui_story_5051_50511501_232_dialog_content = "Sinto muito sua falta.",
  ui_story_5051_50511501_233_dialog_content = "Hã?",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>Em um canto</color>",
  ui_story_5051_50511501_235_dialog_content = "Se apresse, Jakine!",
  ui_story_5051_50511501_236_dialog_content = "Por que seu feitiço para de funcionar quando é minha vez?",
  ui_story_5051_50511501_237_dialog_content = "Ei, não me apresse, ok! Você tem que estar com vontade de lançar o feitiço, sabe.",
  ui_story_5051_50511501_238_dialog_content = "Ou talvez você tenha preferido a cabeça de gesso que acabamos de ver!",
  ui_story_5051_50511501_239_dialog_content = "Você...",
  ui_story_5051_50511501_240_dialog_content = "Meu pai... Será que ele desabafou?",
  ui_story_5051_50511501_241_dialog_content = "Acho que sim pelo que parece. Esses dois ainda parecem muito amigos.",
  ui_story_5051_50511501_242_dialog_content = "<size=45>Ahhh! O que aquele hipócrita está tentando fazer com minha irmã!</size>",
  ui_story_5051_50511501_243_dialog_content = "Por que você acabou de cobrir meus olhos, PlayerName?",
  ui_story_5051_50511501_244_dialog_content = "Não é você quem cobriu meus olhos, Mia?",
  ui_story_5051_50511501_245_dialog_content = "Nossa, cada um de vocês pirralhos...",
  ui_story_5051_50511501_246_dialog_content = "<size=45>Chega de espiar!</size>",
  ui_story_5051_50511601_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5051_50511601_2_dialog_content = "Como alguém pode ainda estar fora depois da cura da ressaca?",
  ui_story_5051_50511601_3_dialog_content = "Mas está tudo bem, isso me dá uma chance de chamá-lo em voz alta...",
  ui_story_5051_50511601_4_dialog_content = "M-mamãe...",
  ui_story_5051_50511601_5_dialog_content = "Ei, qual é o problema comigo. Eu me sinto um pouco estranho gritando isso.",
  ui_story_5051_50511601_6_dialog_content = "Espero vê-lo novamente desde que você saiu de casa há doze anos para meditar.",
  ui_story_5051_50511601_7_dialog_content = "Eu fantasiei que um dia poderia descobrir onde você está com a adivinhação.",
  ui_story_5051_50511601_8_dialog_content = "E se perguntou se você ainda parecia o mesmo...",
  ui_story_5051_50511601_9_dialog_content = "Sempre usando um véu, estando ocupada sozinha em uma cabana remota na floresta.",
  ui_story_5051_50511601_10_dialog_content = "Mas os anos se passaram e minhas memórias de você se tornaram um borrão.",
  ui_story_5051_50511601_11_dialog_content = "Imagine minha surpresa quando encontrei o jovem você em Lumopolis hoje.",
  ui_story_5051_50511601_12_dialog_content = "O que é ainda mais surpreendente é que você parecia tão... não confiável!",
  ui_story_5051_50511601_13_dialog_content = "Mas comparado com o que eu lembrava, você ainda era mais extrovertido, adorável, ousado...",
  ui_story_5051_50511601_14_dialog_content = "Depois que você partiu, papai pensou em nos mudar de Northland.",
  ui_story_5051_50511601_15_dialog_content = "Mas eu temia que se partíssemos, você não nos encontraria quando voltasse, então fiquei para trás, sozinho.",
  ui_story_5051_50511601_16_dialog_content = "Mas não se preocupe, eu tenho muitos e muitos amigos!",
  ui_story_5051_50511601_17_dialog_content = "Aprendi feitiços com o livro de adivinhação que você deixou para trás... Embora eu ainda não seja muito bom e tenha feito muitas besteiras.",
  ui_story_5051_50511601_18_dialog_content = "Mas é só você esperar!",
  ui_story_5051_50511601_19_dialog_content = "Vou me tornar o maior pupilo de Boaz e criar uma bola de cristal ainda mais poderosa que o Cristal da Memória Eterna!",
  ui_story_5051_50511601_20_dialog_content = "Talvez então eu possa detectar onde você está se escondendo em Northland.",
  ui_story_5051_50511601_21_dialog_content = "De qualquer forma, você verá quando nos encontrarmos novamente!",
  ui_story_5051_50511601_22_dialog_content = "Meu filho.",
  ui_story_5051_50511601_23_dialog_content = "O que? Você está acordado?",
  ui_story_5051_50511601_24_dialog_content = "Ahem, eu estava apenas tagarelando. Não ligue para isso.",
  ui_story_5051_50511601_25_dialog_content = "Não que você fosse compreender uma palavra do que eu disse, de qualquer maneira... Desculpe acordá-lo. Eu só queria dizer adeus.",
  ui_story_5051_50511601_26_dialog_content = "Oh, você pensa mal da minha compreensão?",
  ui_story_5051_50511601_27_dialog_content = "Sim, desde que você esteve bêbado o tempo todo...",
  ui_story_5051_50511601_28_dialog_content = "Espere, por que você está agindo sério agora? Não estou acostumada com isso!",
  ui_story_5051_50511601_29_dialog_content = "Serão necessárias habilidades muito além do seu nível atual para desvendar os segredos do Cristal.",
  ui_story_5051_50511601_30_dialog_content = "Muito menos criar um.",
  ui_story_5051_50511601_31_dialog_content = "Tem certeza que é isso que você quer fazer, Jakine?",
  ui_story_5051_50511601_32_dialog_content = "Sim, cem por cento de certeza!",
  ui_story_5051_50511601_33_dialog_content = "Espere, você não se recusou a admitir que sou sua filha?",
  ui_story_5051_50511601_34_dialog_content = "Você, de fato, não é MINHA filha Jakine.",
  ui_story_5051_50511601_35_dialog_content = "Mas eu também sei que você é de fato Jakine.",
  ui_story_5051_50511601_36_dialog_content = "Você finalmente voltou, Jakine.",
  ui_story_5051_50511601_37_dialog_content = "Ei, desculpe, eu tinha muito a dizer e esqueci a hora.",
  ui_story_5051_50511601_38_dialog_content = "O que está errado? Algo está te incomodando?",
  ui_story_5051_50511601_39_dialog_content = "Eu-Tem?",
  ui_story_5051_50511601_40_dialog_content = "Oh, Caleb, quer tentar de novo? Garanto que vou fazer você parecer mais jovem!",
  ui_story_5051_50511601_X41_dialog_content = "Esqueça. Ter cabeça de coelho não é para mim.",
  ui_story_5051_50511601_42_dialog_content = "Shh...",
  ui_story_5051_50511601_43_dialog_content = "Não deixe que papai e mamãe nos encontrem.",
  ui_story_5051_50511601_44_dialog_content = "O City Lord ainda está se despedindo de Lady Joshua?",
  ui_story_5051_50511601_45_dialog_content = "Parece que não vai acabar tão cedo...",
  ui_story_5051_50511601_46_dialog_content = "Hmm, como é que as crianças e os convidados ainda não chegaram?",
  ui_story_5051_50511601_47_dialog_content = "Eles... já estão dormindo.",
  ui_story_5051_50511601_48_dialog_content = "Todos nós tivemos um dia cansativo, mas não podemos simplesmente pular refeições!",
  ui_story_5051_50511601_49_dialog_content = "Vou arranjar alguém para mandar comida para os quartos deles...",
  ui_story_5051_50511601_50_dialog_content = "Eu já dei o pedido. Você não precisa se preocupar com isso.",
  ui_story_5051_50511601_51_dialog_content = "Oh? Isso é diferente de você, Daniel.",
  ui_story_5051_50511601_52_dialog_content = "Você está se sentindo culpado por alguma coisa?",
  ui_story_5051_50511601_53_dialog_content = "Sentindo culpado?",
  ui_story_5051_50511601_54_dialog_content = "Sim. Caso contrário, por que o inundado City Lord de repente arranjaria tempo para sua esposa?",
  ui_story_5051_50511601_55_dialog_content = "Eu só sinto...",
  ui_story_5051_50511601_56_dialog_content = "Fazia muito tempo que não nos sentávamos e jantávamos assim como um casal.",
  ui_story_5051_50511601_57_dialog_content = "É verdade, mas pensei que você tivesse parado de se importar com isso.",
  ui_story_5051_50511601_58_dialog_content = "Desculpe.",
  ui_story_5051_50511601_59_dialog_content = "Oh, por que você está dizendo isso o tempo todo esta noite?",
  ui_story_5051_50511601_60_dialog_content = "O que o levou a pedir desculpas a mim?",
  ui_story_5051_50511601_61_dialog_content = "Não posso te dizer neste momento.",
  ui_story_5051_50511601_62_dialog_content = "Daniel...",
  ui_story_5051_50511601_63_dialog_content = "É por causa da Casa Kartima?",
  ui_story_5051_50511601_64_dialog_content = "Você realmente não vai deixar cada um deles ir, Daniel?",
  ui_story_5051_50511601_65_dialog_content = "...",
  ui_story_5051_50511601_66_dialog_content = "Não é verdade.",
  ui_story_5051_50511601_67_dialog_content = "Somente os verdadeiros infratores devem ser punidos.",
  ui_story_5051_50511601_68_dialog_content = "Você mentiu apenas para me aplacar?",
  ui_story_5051_50511601_69_dialog_content = "Não é isso, Josué!",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5051_50511601_71_dialog_content = "Joshua?",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>Mentindo para mim.</anim>",
  ui_story_5051_50511601_73_dialog_content = "Joshua?",
  ui_story_5051_50511601_74_dialog_content = "O que há de errado, Josué?!",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>Você mentiu para mim...</anim>",
  ui_story_5051_50511601_76_dialog_content = "Eu era o culpado pelo que você se tornou, Joshua?",
  ui_story_5051_50511601_77_dialog_content = "Coloquei tudo para me livrar da Casa Kartima...",
  ui_story_5051_50511601_78_dialog_content = "Não confiei no seu julgamento, optando por ignorar o seu conselho...",
  ui_story_5051_50511601_79_dialog_content = "Não apreciei seu esforço, incumbindo-o de todas as obrigações familiares...",
  ui_story_5051_50511601_80_dialog_content = "Eu não fiquei ao seu lado quando você mais precisou de mim...",
  ui_story_5051_50511601_81_dialog_content = "Sinto muito!",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>Daniel...</anim>",
  ui_story_5051_50511601_84_dialog_content = "Estou aqui, estou aqui, Joshua!",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>Daniel... Verônica... Carleen...</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>Ahhhh!!!</anim>",
  ui_story_5051_50511601_87_dialog_content = "Joshua!",
  ui_story_5051_50511601_88_dialog_content = "Mãe? O que aconteceu com a mãe?",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>Estrondo</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_5051_50511601_91_dialog_content = "Aquele barulho de trovão de novo?",
  ui_story_5051_50511601_92_dialog_content = "Terremoto? É um terremoto?",
  ui_story_5051_50511601_93_dialog_content = "Não. Nenhum terremoto naquela noite na história real.",
  ui_story_5051_50511601_94_dialog_content = "Acho que não consigo ver nada...",
  ui_story_5051_50511601_95_dialog_content = "Eu também! Estou recorrendo aos poucos poderes psíquicos que me restam para discernir a direção.",
  ui_story_5051_50511601_96_dialog_content = "O tempo está quase acabando, Jakine?",
  ui_story_5051_50511601_97_dialog_content = "Não, ainda devemos ter muito tempo até o fim do dia. Não pode ser isso?!",
  ui_story_5051_50511601_98_dialog_content = "Não me diga que estamos prestes a cair nas rachaduras entre o Cristal e o mundo real!",
  ui_story_5051_50511601_99_dialog_content = "O que você está esperando, Jakine?",
  ui_story_5051_50511601_100_dialog_content = "Levar todos nós para fora!",
  ui_story_5051_50511601_101_dialog_content = "Reúnam-se à minha volta, todos!",
  ui_story_5051_50511601_102_dialog_content = "Mas estamos sentindo falta do meu pai...",
  ui_story_5051_50511601_103_dialog_content = "É apropriado para aquele cara hipócrita estar preso aqui. Esqueça ele, vamos!",
  ui_story_5051_50511601_104_dialog_content = "Mesmo que seja o mais vil dos canalhas, não devemos deixá-lo para trás assim...",
  ui_story_5051_50511601_105_dialog_content = "Chame o Senhor da Cidade",
  ui_story_5051_50511601_106_dialog_content = "Estamos aqui, Senhor Schwartz!",
  ui_story_5051_50511601_107_dialog_content = "Pai!",
  ui_story_5051_50511601_108_dialog_content = "Senhor Schwartz!",
  ui_story_5051_50511601_109_dialog_content = "Por que ele não responde...?",
  ui_story_5051_50511601_110_dialog_content = "Entre em contato com o Lorde da Cidade mentalmente",
  ui_story_5051_50511601_111_dialog_content = "Maldições…",
  ui_story_5051_50511601_112_dialog_content = "Ainda não consigo contatar ninguém mentalmente no Cristal!",
  ui_story_5051_50511601_113_dialog_content = "Oh!",
  ui_story_5051_50511601_114_dialog_content = "O que foi, Mia?",
  ui_story_5051_50511601_115_dialog_content = "O espaço atrás de nós... Está caindo lentamente no vazio!",
  ui_story_5051_50511601_116_dialog_content = "Tem que se apressar, PlayerName!",
  ui_story_5051_50511601_117_dialog_content = "Siga-me e dirija-se para onde estava o Senhor da Cidade!",
  ui_story_5051_50511601_118_dialog_content = "Jakine, se ainda não pudermos vê-lo no último segundo...",
  ui_story_5051_50511601_119_dialog_content = "Tire-nos daqui!",
  ui_story_5051_50511601_120_dialog_content = "Beleza!",
  ui_story_5051_50511601_121_dialog_content = "Psst.",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5051_50511601_123_dialog_content = "Alguém acabou de passar correndo?",
  ui_story_5051_50511601_124_dialog_content = "Quem poderia correr tão rápido nessas circunstâncias?",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>Daniel... Verônica... Carleen...</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "Alguém está chamando meu nome?",
  ui_story_5051_50511601_127_dialog_content = "É quase inaudível. Não sei dizer de onde vem.",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>H-Aqui?</anim>",
  ui_story_5051_50511601_129_dialog_content = "O quê...",
  ui_story_5051_50511601_130_dialog_content = "Cuidado!",
  ui_story_5051_50511601_131_dialog_content = "Pai!",
  ui_story_5051_50511601_132_dialog_content = "Esteja alerta, temos um visitante não convidado aqui.",
  ui_story_5051_50511601_133_dialog_content = "Que ataque impiedoso... Quem nos atacaria assim?",
  ui_story_5051_50511601_134_dialog_content = "Já estamos na brecha entre o Cristal e o mundo real?",
  ui_story_5051_50511601_135_dialog_content = "Não! Não-!",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>H-Aqui?</anim>",
  ui_story_5051_50511601_137_dialog_content = "Eca, monstro!",
  ui_story_5051_50511601_138_dialog_content = "Só você pode dizer a direção agora, PlayerName.",
  ui_story_5051_50511601_139_dialog_content = "Assuma a liderança!",
  ui_story_5051_50511602_1_dialog_content = "Huff... puff...",
  ui_story_5051_50511602_2_dialog_content = "Pausa para uma pausa, Mia!",
  ui_story_5051_50511602_3_dialog_content = "Mas... não, eu quero te ajudar, ajudar todo mundo...",
  ui_story_5051_50511602_4_dialog_content = "Por aqui?",
  ui_story_5051_50511602_5_dialog_content = "Ative, bola de cristal!",
  ui_story_5051_50511602_6_dialog_content = "Vamos lá, por que o monstro continua atacando?",
  ui_story_5051_50511602_7_dialog_content = "Como é que existe tal monstro no Cristal, Jakine?",
  ui_story_5051_50511602_8_dialog_content = "Eu também não faço ideia.",
  ui_story_5051_50511602_9_dialog_content = "Tem certeza que não é algo que apareceu em Lumopolis?",
  ui_story_5051_50511602_10_dialog_content = "...",
  ui_story_5051_50511602_11_dialog_content = "Noite Branca, proteja-nos!",
  ui_story_5051_50511602_12_dialog_content = "Não havia tal monstro em Lumopolis naquela época.",
  ui_story_5051_50511602_13_dialog_content = "Mas não ceda!",
  ui_story_5051_50511602_14_dialog_content = "Comparado a antes, seus poderes obviamente diminuíram e os intervalos entre os ataques estão ficando mais longos.",
  ui_story_5051_50511602_15_dialog_content = "Jakine, depois que ele atacar novamente, tire-nos durante o intervalo!",
  ui_story_5051_50511602_16_dialog_content = "Entendi, Senhor Schwartz!",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5051_50511602_18_dialog_content = "Como é que tudo parou de repente?",
  ui_story_5051_50511602_19_dialog_content = "Silêncio... Você ouviu isso?",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>Daniel... Verônica... Carleen...</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "Está chamando meu nome e o do meu pai e da minha irmã?",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>Daniel, Verônica, Carleen.</anim>",
  ui_story_5051_50511602_23_dialog_content = "Essa voz...",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>E... Calebe.</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>Joshua</color>?!",
  ui_story_5051_50511602_26_dialog_content = "Como isso pode ser?",
  ui_story_5051_50511602_27_dialog_content = "I-É minha irmã?",
  ui_story_5051_50511602_28_dialog_content = "Não, não, não... Impossível, ela não pode estar aqui!",
  ui_story_5051_50511602_29_dialog_content = "Será que...?",
  ui_story_5051_50511602_30_dialog_content = "...",
  ui_story_5051_50511602_31_dialog_content = "Por que parou?",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>Não!</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>Você não pode fazer isso!</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>Por que não?</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>Eles são a fonte de toda a sua dor.</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>O obstáculo para realizar seus sonhos!</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>São as pessoas que mais me importam!</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>Mate-os e você estará livre para partir!</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>Porque esperar? Eles estão quase no fim da corda.</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>Isso é irritante!</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>Sair!</anim>",
  ui_story_5051_50511602_42_dialog_content = "Ele está falando sozinho?",
  ui_story_5051_50511602_X43_dialog_content = "Isso é muito estranho... parece que estou discutindo comigo mesmo.",
  ui_story_5051_50511602_44_dialog_content = "Joshua, é mesmo você?",
  ui_story_5051_50511602_45_dialog_content = "Mãe...?",
  ui_story_5051_50511602_46_dialog_content = "Como ousa imitar a voz de Joshua?",
  ui_story_5051_50511602_47_dialog_content = "Não terei piedade de você!",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>Schwar...</anim>",
  ui_story_5051_50511602_49_dialog_content = "Vou sacudir cada estrela—!!!",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>Eca...</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>Te odeio...!</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "O quê?",
  ui_story_5051_50511602_53_dialog_content = "Seu ataque funcionou!",
  ui_story_5051_50511602_54_dialog_content = "Parece estar em agonia, mas não é exatamente o tipo físico...",
  ui_story_5051_50511602_55_dialog_content = "Não pode ser ela. Impossível. Se for ela...",
  ui_story_5051_50511602_56_dialog_content = "Tire-nos daqui agora, Jakine. Agora!",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50511602_58_dialog_content = "Isso é o som de um relógio?",
  ui_story_5051_50511602_59_dialog_content = "Oh, não, não, não... O relógio marca meia-noite!",
  ui_story_5051_50511602_60_dialog_content = "Vamos ficar presos aqui?",
  ui_story_5051_50511602_61_dialog_content = "Por que... eu só encontro depois de tudo isso...",
  ui_story_5051_50511602_62_dialog_content = "Só mais um minuto...",
  ui_story_5051_50511602_63_dialog_content = "Por quê?!",
  ui_story_5051_50511602_64_dialog_content = "O que é isso que você tem na mão, Caleb?",
  ui_story_5051_50511602_65_dialog_content = "Esse é o Cristal da Memória Eterna para este mundo?",
  ui_story_5051_50511602_66_dialog_content = "Um Cristal dentro do Cristal?",
  ui_story_5051_50511602_67_dialog_content = "E daí? É inútil mesmo se eu o encontrasse.",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50511602_69_dialog_content = "O relógio está prestes a chegar às doze!",
  ui_story_5051_50511602_70_dialog_content = "Por que você estava procurando por isso no Cristal, Caleb?",
  ui_story_5051_50511602_71_dialog_content = "Eu já disse, é inútil.",
  ui_story_5051_50511602_72_dialog_content = "Não, pode haver uma maneira!",
  ui_story_5051_50511602_73_dialog_content = "Dê-me o Cristal, Caleb!",
  ui_story_5051_50511602_74_dialog_content = "Pegue.",
  ui_story_5051_50511602_75_dialog_content = "Mãe...",
  ui_story_5051_50511602_76_dialog_content = "Você previu isso acontecendo, não previu?",
  ui_story_5051_50511602_77_dialog_content = "As pessoas gostam de prever o futuro por meio da adivinhação.",
  ui_story_5051_50511602_78_dialog_content = "Mas então percebi que sempre subestimamos a rapidez com que esquecemos as coisas.",
  ui_story_5051_50511602_79_dialog_content = "Então, em certos aspectos, o que é mais imprevisível é o <color=#FFB400>passado</color>.",
  ui_story_5051_50511602_80_dialog_content = "Foi por isso que criei o Cristal da Memória Eterna em primeiro lugar.",
  ui_story_5051_50511602_81_dialog_content = "Originalmente, pensei que seria o método mais seguro para revisar o histórico.",
  ui_story_5051_50511602_82_dialog_content = "Mas sua aparição me alertou sobre cenários imprevistos com o Cristal.",
  ui_story_5051_50511602_83_dialog_content = "Felizmente, há um sistema de segurança no mundo interior.",
  ui_story_5051_50511602_84_dialog_content = "... Um Cristal dentro do Cristal.",
  ui_story_5051_50511602_85_dialog_content = "Essa é a única coisa que falta no livro.",
  ui_story_5051_50511602_86_dialog_content = "Espero que você nunca tenha que acessar essa informação.",
  ui_story_5051_50511602_87_dialog_content = "Eu não vou deixar você para baixo!",
  ui_story_5051_50511602_88_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5051_50511602_89_dialog_content = "Presença de anúncio!",
  ui_story_5051_50511602_90_dialog_content = "Volte ao início, voltemos à realidade!",
  ui_story_5051_50511602_91_dialog_content = "<size=45>Abracadabra!</size>",
  ui_story_5051_50511602_92_dialog_content = "Argh!",
  ui_story_5051_50511602_93_dialog_content = "Mais uma vez... O mundo está girando ao meu redor...",
  ui_story_5051_50511602_94_dialog_content = "Segure-se um no outro e não solte!",
  ui_story_5051_50511602_95_dialog_content = "Venha até mim, Mia e PlayerName!",
  ui_story_5051_50511602_96_dialog_content = "Oh, não, não posso prender Caleb!",
  ui_story_5051_50511602_97_dialog_content = "Sinto muito, minha irmã... não estarei mais perto de você...",
  ui_story_5051_50511602_98_dialog_content = "Não podemos... deixar ninguém para trás!",
  ui_story_5051_50511602_99_dialog_content = "PlayerName?!",
  ui_story_5051_50511602_100_dialog_content = "Calebe!",
  ui_story_5051_50511602_101_dialog_content = "Segura a minha mão!",
  ui_story_5051_50511602_102_dialog_content = "Afe!",
  ui_story_5051_50511602_103_dialog_content = "Pare de se alongar, PlayerName. Meu pai está perdendo o controle sobre você!",
  ui_story_5051_50511602_104_dialog_content = "Eu não posso desistir!",
  ui_story_5051_50511602_105_dialog_content = "PlayerName!",
  ui_story_5051_50511602_106_dialog_content = "Peguei vocês! Peguei o Calebe!",
  ui_story_5051_50511602_107_dialog_content = "PlayerName...?",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5051_50511602_109_dialog_content = "(Isso é um copo quebrando?)",
  ui_story_5051_50511602_110_dialog_content = "(Mas só tem um copo na sala...)",
  ui_story_5051_50511602_111_dialog_content = "(Então aquele bom vinho ainda não conseguiu acalmar o Sr. Caleb, entendo...)",
  ui_story_5051_50511602_112_dialog_content = "Isso foi uma grande comoção, Sra. Rot.",
  ui_story_5051_50511602_113_dialog_content = "Qual convidado de honra foi tão descuidado a ponto de quebrar objetos no quarto do City Lord?",
  ui_story_5051_50511602_114_dialog_content = "Ou devo dizer qual convidado enfureceu tanto o senhor que ele teve que recorrer ao arremesso de objetos?",
  ui_story_5051_50511602_115_dialog_content = "Admiro sua imaginação, Duke.",
  ui_story_5051_50511602_116_dialog_content = "No entanto, não é da nossa conta discutir ou especular sobre o conteúdo da conversa do Senhor da Cidade e de seu convidado.",
  ui_story_5051_50511602_117_dialog_content = "Humph. Você não é mais o capitão da Nightwatch, é?",
  ui_story_5051_50511602_118_dialog_content = "Mas não serei negligente no desempenho de minhas funções para o Lorde da Cidade.",
  ui_story_5051_50511602_119_dialog_content = "Obrigações? Você é apenas um anfitrião provisório da festa.",
  ui_story_5051_50511602_120_dialog_content = "Se você gosta de fazer isso, posso convidá-lo para ajudar no aniversário do meu filho, Sra. Rot?",
  ui_story_5051_50511602_121_dialog_content = "Acho que não fui claro, Duke.",
  ui_story_5051_50511602_122_dialog_content = "Eu ainda estou trabalhando para o Senhor da Cidade.",
  ui_story_5051_50511602_123_dialog_content = "Diga o que disser, ele não poderá conceder uma audiência a seu filho esta noite.",
  ui_story_5051_50511602_124_dialog_content = "Bem, eu nunca fiz tal exigência, Sra. Rot.",
  ui_story_5051_50511602_125_dialog_content = "Eu só queria dizer adeus a ele, já que estava ficando tarde.",
  ui_story_5051_50511602_126_dialog_content = "Mas o jeito que você escolheu seguir o caminho mais baixo...",
  ui_story_5051_50511602_127_dialog_content = "Isso é impróprio para alguém que trabalha para o Lorde da Cidade.",
  ui_story_5051_50511602_128_dialog_content = "Bem, você nunca pode ser muito cuidadoso.",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5051_50511602_130_dialog_content = "O quê?",
  ui_story_5051_50511602_131_dialog_content = "Fora...",
  ui_story_5051_50511602_132_dialog_content = "O vento está aumentando.",
  ui_story_5051_50511602_133_dialog_content = "<color=#e8d9bb>Enquanto isso na residência de Caleb</color>",
  ui_story_5051_50511602_134_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5051_50511602_135_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5051_50511602_136_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5051_50511602_137_dialog_content = "...",
  ui_story_5051_50511602_138_dialog_content = "...",
  ui_story_5051_50511602_139_dialog_content = "...",
  ui_story_5051_50511602_140_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5051_50511602_141_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5051_50511602_142_dialog_content = "<color=#e8d9bb>Estrondo!!!</color>",
  ui_story_5051_50511602_143_dialog_content = "Continua..."
}
return config
